// Буття — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["На початку створив Бог небо і землю.","Земля ж була безвидна і порожня, і темрява була над безоднею, і Дух Божий носився над водою.","І сказав Бог: нехай буде світло. І стало світло.","І побачив Бог світло, що воно добре, і відокремив Бог світло від темряви.","І назвав Бог світло днем, темряву ніччю. І був вечір, і був ранок: день перший.","І сказав Бог: нехай буде твердь посеред води, і нехай відділяє вона воду від води. [І стало так.]","І створив Бог твердь, і відокремив воду, що під твердю, від води, що над твердю. І стало так.","І назвав Бог твердь небом. [І побачив Бог, що це добре.] І був вечір, і був ранок: день другий.","І сказав Бог: нехай збереться вода, що під небом, в одне місце, і нехай з’явиться суша. І стало так. [І зібралася вода під небом у свої місця, і з’явилася суша.]","І назвав Бог сушу землею, а зібрання вод назвав морями. І побачив Бог, що це добре.","І сказав Бог: нехай вирощує земля зелень, траву, що сіє насіння за [родом і за подобою своєю, і] дерево плідне, що приносить за родом своїм плід, у якому насіння його на землі. І стало так.","І виростила земля зелень, траву, що сіє насіння за родом [і за подобою] її, і дерево [плідне], що приносить плід, у якому насіння його за родом його [на землі]. І побачив Бог, що це добре.","І був вечір, і був ранок: день третій.","І сказав Бог: нехай будуть світила на тверді небесній [для освітлення землі і] для відокремлення дня від ночі, і для знамень, і часу, і днів, і років;","і нехай будуть вони світильниками на тверді небесній, щоб освітлювати землю. І стало так.","І створив Бог два світила великі: світило більше — для управління днем, і світило менше — для управління ніччю, і зорі;","і поставив їх Бог на тверді небесній, щоб світити на землю,","і управляти днем і ніччю, і відокремлювати світло від темряви. І побачив Бог, що це добре.","І був вечір, і був ранок: день четвертий.","І сказав Бог: нехай породить вода плазунів, душу живу; і птахи нехай полетять над землею, під твердю небесною. [І стало так.]","І створив Бог риб великих і всяку душу тварин-плазунів, яких породила вода, за родом їх, і всякого птаха пернатого за родом його. І побачив Бог, що це добре.","І благословив їх Бог, промовивши: плодіться і розмножуйтеся, і наповнюйте води в морях, і птахи нехай розмножуються на землі.","І був вечір, і був ранок: день п’ятий.","І сказав Бог: нехай родить земля душу живу за родом її, тварин і плазунів, і звірів земних за родом їх. І стало так.","І створив Бог звірів земних за родом їх, і худобу за родом її, і всіх плазунів земних за родом їх. І побачив Бог, що це добре.","І сказав Бог: створімо людину за образом Нашим [і] за подобою Нашою, і нехай володарює вона над рибами морськими, і над птахами небесними, [і над звірами,] і над худобою, і над усією землею, і над усіма плазунами, що повзають по землі.","І створив Бог Людину за образом Своїм, за образом Божим створив її; чоловіка і жінку створив їх.","І благословив їх Бог, і сказав їм Бог: плодіться і розмножуйтеся, і наповнюйте землю, і володійте нею, і владарюйте над рибами морськими [і над звірами,] і над птахами небесними, [і над усякою худобою, і над усією землею,] і над усякою твариною, що плазує по землі.","І сказав Бог: ось, Я дав вам усяку траву, що сіє насіння, яка є на всій землі, і всяке дерево, яке має плід, що сіє насіння; — вам це буде в їжу;","а всім звірам земним, і всім птахам небесним, і всякому [плазуну,] на землі, в якому душа жива, дав Я всю зелень трав’яну в їжу. І стало так.","І побачив Бог усе, що Він створив, і ось, добре воно. І був вечір, і був ранок: день шостий."],"x":{"1":"25.88.12-13|25.135.5|25.145.6|30.18.1|53.1.3|54.14.15|75.11.3|76.14.7","3":"25.32.9","6":"25.32.6|25.135.5|25.148.4|32.10.12|32.51.15","9":"25.32.7|25.135.6","14":"25.135.7-9","16":"4.4.19|32.31.35","18":"25.103.19-20","21":"24.40.20|25.103.25","22":"0.8.17","24":"24.12.7|30.16.31","26":"0.5.1|29.2.23|30.17.3","27":"0.5.1-2|50.19.4|51.10.6|63.11.7|68.3.10","28":"0.8.17|0.9.1:7","29":"0.9.3","31":"25.110.3|30.39.21"}},{"v":["Так були створені небо і земля і все воїнство їх.","І звершив Бог до сьомого дня діла Свої, які Він робив, і спочив у день сьомий від усіх діл Своїх, які чинив.","І благословив Бог сьомий день, і освятив його, бо спочив від усіх діл Своїх, які Бог чинив і створював.","Ось походження неба і землі, при створенні їх, у той час, коли Господь Бог створив землю і небо,","і всякий польовий чагарник, якого ще не було на землі, і всяку польову траву, що ще не росла, тому що Господь Бог не посилав дощу на землю, і не було людини для обробки землі,","але пара піднімалася з землі й зрошувала усе лице землі.","І створив Господь Бог людину з пороху земного, і вдихнув у лице її дихання життя, і стала людина душею живою.","І насадив Господь Бог рай у Едемі на сході, і примістив там людину, яку створив.","І виростив Господь Бог із землі всяке дерево, приємне на вигляд і добре для їжі, і дерево життя посеред раю, і дерево пізнання добра і зла.","З Едему витікала ріка для зрошення раю; і потім розділялася на чотири ріки.","Ім’я однієї Фисон: вона обтікає всю землю Хавила, ту, де золото;","і золото тієї землі добре; там бдолах і камень онікс.","Ім’я другої ріки Гихон [Геон]: вона обтікає всю землю Куш.","Ім’я третьої ріки Хиддекель [Тигр]: вона протікає перед Ассирією. Четверта ріка Євфрат.","І взяв Господь Бог людину, [яку створив,] і оселив її в саду Едемському, щоб обробляти його й оберігати його.","І заповів Господь Бог людині, сказавши: від усякого дерева в саду ти будеш їсти,","а від дерева пізнання добра і зла не їж від нього, бо в той день, коли ти з’їси від нього, смертю помреш.","І сказав Господь Бог: не добре бути чоловікові одному; створімо йому помічника, за його подобою.","Господь Бог створив із землі всіх тварин польових і всіх птахів небесних, і привів [їх] до людини, щоб бачити, як вона назве їх, і щоб, як назве людина всяку душу живу, так і було ім’я їй.","І нарекла людина імена всій худобі і птахам небесним і всім звірам польовим; але для чоловіка не знайшлося помічника, подібного до нього.","І навів Господь Бог на чоловіка міцний сон; і, коли він заснув, узяв одне з ребер його, і закрив те місце плоттю.","І створив Господь Бог з ребра, яке взяв у чоловіка, жінку, і привів її до чоловіка.","І сказав чоловік: ось, це кістка від кісток моїх і плоть від плоті моєї; вона буде зватися жінкою, бо взята від чоловіка [свого].","Тому залишить чоловік батька свого і матір свою і пристане до жінки своєї; і стануть [два] однією плоттю.","І були вони обоє нагі, Адам і дружина його, і не соромилися."],"x":{"1":"31.45.12","2":"1.20.11|1.31.17|75.4.4","7":"63.15.45","8":"0.4.16","9":"76.2.7|76.22.2","11":"30.24.27","14":"37.10.4","17":"62.5.12|62.6.23","18":"27.4.8-9","22":"71.2.13","23":"63.11.8","24":"50.19.5|51.10.7-8|63.6.16|66.5.31"}},{"v":["Змій був хитрішим за всіх звірів польових, яких створив Господь Бог. І сказав змій жінці: чи дійсно сказав Бог: не їжте ні від якого дерева в раю?","І сказала жінка змію: плоди з дерев ми можемо їсти,","тільки плодів з дерева, яке посеред раю, сказав Бог, не їжте їх і не доторкайтеся до них, щоб вам не померти.","І сказав змій жінці: ні, не вмрете,","але знає Бог, що того дня, коли ви з’їсте їх, розкриються очі ваші, і ви будете, як боги, що знають добро і зло.","І побачила жінка, що дерево добре для їжі, і що воно приємне для очей і жадане, тому що дає знання; і взяла плодів його і їла; і дала також чоловікові своєму, і він їв.","І розкрилися очі у них обох, і пізнали вони, що нагі, і зшили вони фігове листя, і зробили собі оперезання.","І почули голос Господа Бога, Який ходив по раю під час прохолоди дня; і сховався Адам і жінка його від лиця Господа Бога між деревами раю.","І покликав Господь Бог Адама і сказав йому: [Адаме,] де ти?","Він сказав: почув я голос Твій у раю, і злякався, тому що я нагий, і сховався.","І сказав [Бог]: хто сказав тобі, що ти нагий? Чи не їв ти від дерева, з якого Я заборонив тобі їсти?","Адам сказав: жінка, яку Ти мені дав, вона дала мені від дерева, і я їв.","І сказав Господь Бог жінці: що це ти зробила? Жінка сказала: змій спокусив мене, і я їла.","І сказав Господь Бог змієві: за те, що ти зробив це, проклятий ти перед усією худобою і перед усіма звірами польовими; ти будеш ходити на череві твоїм, і будеш їсти прах у всі дні життя твого;","і ворожнечу покладу між тобою і між жінкою, і між сіменем твоїм і між сіменем її; воно буде уражати тебе в голову, а ти будеш жалити його в п’яту*.","Жінці сказав: примножуючи примножу скорботи твої у вагітності твоїй; у болях будеш народжувати дітей; і до чоловіка твого жадання твоє, і він буде панувати над тобою.","Адамові ж сказав: за те, що ти послухав голос жінки твоєї і їв від дерева, про яке Я заповідав тобі, сказавши: не їж від нього, проклята земля через тебе; у скорботі будеш їсти від неї в усі дні життя твого;","терня й осот буде родити вона тобі; і ти будеш їсти польову траву;","у поті лиця твого будеш їсти хліб, доки не повернешся в землю, з якої ти взятий, бо порох ти і до пороху повернешся.","І нарік Адам ім’я жінці своїй: Єва*, бо вона стала матір’ю всіх, хто живе.","І зробив Господь Бог Адаму і дружині його одяг шкіряний і одягнув їх.","І сказав Господь Бог: ось, Адам став як один з Нас, знаючи добро і зло; і тепер як би не простяг він руки своєї, і не взяв також від дерева життя, і не з’їв, і не став жити вічно.","І вислав його Господь Бог із саду Едемського, щоб обробляти землю, із якої він узятий.","І вигнав Адама, і поставив на сході біля саду Едемського Херувима і полум’яний меч, який обертався навколо, щоб охороняти путь до дерева життя."],"x":{"1":"29.2.24","4":"53.8.44|64.11.3","6":"30.25.27|71.2.14","7":"0.2.25|76.3.17","8":"25.137.6|40.9.2","11":"0.2.17","13":"64.11.3","14":"25.71.9","15":"0.14.18|48.6.13|0.22.9|48.12.10|53.3.14","16":"63.14.34","17":"0.4.12|0.5.29","19":"25.127.2|27.12.7","22":"0.1.27|58.5.7|0.2.9"},"n":{"15":["За іншим читанням: і між Сіменем її; Він буде уражати тебе в голову, а ти будеш жалити Його в п’яту."],"20":["Життя."]}},{"v":["Адам пізнав Єву, дружину свою; і вона зачала, і народила Каїна, і сказала: придбала я людину від Господа.","І ще народила брата його, Авеля. І був Авель пастирем овець, а Каїн був хліборобом.","Через деякий час Каїн приніс від плодів землі дар Господу,","і Авель також приніс від первістків отари своєї і від лона їх. І зглянувся Господь на Авеля і на жертву його,","а на Каїна і на жертву його не зглянувся. Каїн дуже засмутився, і поникло обличчя його.","І сказав Господь [Бог] Каїнові: чому ти засмутився? і від чого поникло обличчя твоє?","якщо ти робиш добре, то чи не піднімаєш обличчя? а якщо не робиш доброго, то біля дверей гріх лежить; він тягне тебе до себе, але ти пануй над ним.","І сказав Каїн Авелю, брату своєму: [підемо в поле]. І коли вони були в полі, повстав Каїн на Авеля, брата свого, й убив його.","І сказав Господь [Бог] Каїнові: де Авель, брат твій? Він сказав: не знаю; хіба я сторож братові моєму?","І сказав [Господь]: що ти зробив? Голос крови брата твого волає до Мене від землі;","і нині проклятий ти від землі, що розкрила вуста свої прийняти кров брата твого від руки твоєї;","коли ти будеш обробляти землю, вона не стане більш давати сили своєї для тебе; ти будеш вигнанцем і мандрівцем на землі.","І сказав Каїн Господу [Богу]: покарання моє більше, ніж можна знести;","ось, Ти тепер зганяєш мене з лиця землі, і від лиця Твого я сховаюсь, і буду вигнанцем і мандрівцем на землі; і всякий, хто зустрінеться зі мною, уб’є мене.","І сказав йому Господь [Бог]: за те всякому, хто уб’є Каїна, відомститься всемеро. І зробив Господь [Бог] Каїнові знамення, щоб ніхто, зустрівшись з ним, не убив його.","І пішов Каїн від лиця Господнього й оселився в землі Нод, на схід від Едема.","І пізнав Каїн дружину свою; і вона зачала і народила Єноха. І побудував він місто; і назвав місто за ім’ям сина свого: Єнох.","В Єноха народився Ірад [Гаїдад]; Ірад народив Мехіаеля [Малелеїла]; Мехіаель народив Мафусала; Мафусал народив Ламеха.","І взяв собі Ламех дві дружини: ім’я однієї: Ада, й ім’я другої: Цилла [Селла].","Ада народила Іавала: він був батьком тих, хто живе в наметах з отарами.","Ім’я брата його Іувал: він був батьком всіх, хто грає на гуслях і сопілках.","Цилла також народила Тувалкаїна [Фовела], що був ковачем усякого знаряддя з міді і заліза. І сестра Тувалкаїна Ноема.","І сказав Ламех дружинам своїм: Ада і Цилла! послухайте голосу мого, дружини Ламехові! слухайте слова мої: я убив чоловіка на виразку собі й отрока на рану собі;","якщо за Каїна відомститься всемеро, то за Ламеха в сімдесят разів усемеро.","І пізнав Адам ще [Єву,] дружину свою, і вона народила сина, і нарекла йому ім’я: Сиф, тому що, [говорила вона,] Бог поклав мені інше сім’я, замість Авеля, якого убив Каїн.","У Сифа також народився син, і він нарік йому ім’я: Єнос; тоді почали призивати ім’я Господа [Бога]."],"x":{"4":"75.11.4","5":"26.15.8|31.1.13","6":"50.20.15","7":"62.6.16","8":"65.5.17|29.10.3|50.23.35|58.3.12|61.1.11","9":"25.9.13|25.115.6","10":"75.12.24|76.6.10","14":"0.9.6","19":"0.2.24","25":"0.5.3"}},{"v":["Ось родовід Адама: коли Бог створив людину, за подобою Божою створив її,","чоловіка і жінку створив їх, і благословив їх, і нарік їм ім’я: людина, в день створення їх.","Адам жив сто тридцять [230] років і породив [сина] за подобою своєю [і] за образом своїм, і нарік йому ім’я: Сиф.","Днів Адама після народження ним Сифа було вісімсот [700] років, і породив він синів і дочок.","Усіх же днів життя Адамового було дев’ятсот тридцять років; і він помер.","Сиф жив сто п’ять [205] років і породив Єноса.","Після народження Єноса Сиф жив вісімсот сім [707] років і породив синів і дочок.","Усіх же днів Сифових було дев’ятсот дванадцять років; і він помер.","Єнос жив дев’яносто [190] років і породив Каїнана.","Після народження Каїнана Єнос жив вісімсот п’ятнадцять [715] років і породив синів і дочок.","Усіх же днів Єноса було дев’ятсот п’ять років; і він помер.","Каїнан жив сімдесят [170] років і породив Малелеїла.","Після народження Малелеїла Каїнан жив вісімсот сорок [740] років і породив синів і дочок.","Усіх же днів Каїнана було дев’ятсот десять років; і він помер.","Малелеїл жив шістдесят п’ять [165] років і родив Яреда.","Після народження Яреда Малелеїл жив вісімсот тридцять [730] років і породив синів і дочок.","Усіх же днів Малелеїла було вісімсот дев’яносто п’ять років; і він помер.","Яред жив сто шістдесят два роки і породив Єноха.","Після народження Єноха Яред жив вісімсот років і породив синів і дочок.","Усіх же днів Яреда було дев’ятсот шістдесят два роки; і він помер.","Єнох жив шістдесят п’ять [165] років і породив Мафусала.","І ходив Єнох перед Богом, після народження Мафусала, триста [200] років і породив синів і дочок.","Усіх же днів Єноха було триста шістдесят п’ять років.","І ходив Єнох перед Богом; і не стало його, тому що Бог узяв його.","Мафусал жив сто вісімдесят сім років і породив Ламеха.","Після народження Ламеха Мафусал жив сімсот вісімдесят два роки і породив синів і дочок.","Усіх же днів Мафусала було дев’ятсот шістдесят дев’ять років; і він помер.","Ламех жив сто вісімдесят два [188] роки і породив сина,","і дав йому йому ім’я: Ной, сказавши: він утішить нас у ділах наших й у праці рук наших при оброблянні землі, яку прокляв Господь [Бог].","І жив Ламех після народження Ноя п’ятсот дев’яносто п’ять [565] років і породив синів і дочок.","Усіх же днів Ламеха було сімсот сімдесят сім [753] років; і він помер.","Ною було п’ятсот років і породив Ной [трьох синів]: Сима, Хама і Яфета."],"x":{"1":"12.1.1|0.1.26-27|0.9.6|29.2.23|30.17.3","3":"52.3.38|63.15.48-49","24":"30.44.15|30.49.16|75.11.5","29":"56.3.20|75.11.7|0.3.17","32":"12.1.4"}},{"v":["Коли люди почали примножуватися на землі і народилися у них дочки,","тоді сини Божі побачили дочок людських, що вони красиві, і брали їх собі за дружин, яку хто обрав.","І сказав Господь [Бог]: не вічно Духу Моєму бути зневаженим людьми [цими], тому що вони плоть; нехай будуть дні їх сто двадцять років.","У той час були на землі велетні, особливо ж з тих часів, коли сини Божі стали входити до дочок людських, і вони стали народжувати їм: це сильні, спрадавна славні люди.","І побачив Господь [Бог], що велике розбещення людей на землі, і що всі їх думки і помисли серця їх були злом повсякденно;","і розкаявся Господь, що створив людину на землі, і засмутився у серці Своєму.","І сказав Господь: знищу з лиця землі людей, яких Я створив, від людини до худоби, і плазунів і птахів небесних знищу, бо Я розкаявся, що створив їх.","Ной же придбав благодать перед очима Господа [Бога].","Ось житіє Ноя: Ной був чоловіком праведним і непорочним у роді своєму; Ной ходив перед Богом.","Ной породив трьох синів: Сима, Хама і Яфета.","Але земля розбестилася перед лицем Божим, і наповнилася земля злодіяннями.","І споглянув [Господь] Бог на землю, і ось, вона розбещена, тому що всяка плоть спотворила шлях свій на землі.","І сказав [Господь] Бог Ною: кінець усякій плоті прийшов перед лицем Моїм, тому що земля наповнилася від них злодіяннями; і ось, Я знищу їх з землі.","Зроби собі ковчег з дерева гофер; відділення зроби в ковчезі й обсмоли його смолою усередині і ззовні.","І зроби його так: довжина ковчега триста ліктів; ширина його п’ятдесят ліктів, а висота його тридцять ліктів.","І зроби отвір у ковчезі, і в лікоть зведи його вгорі, і двері в ковчег зроби з боку його; влаштуй у ньому нижнє, друге і третє [житло].","І ось, Я наведу на землю потоп водний, щоб винищити всяку плоть, у якій є дух життя, під небесами; усе, що є на землі, позбудеться життя.","Але з тобою Я укладу завіт Мій, і ввійдеш у ковчег ти, і сини твої, і дружина твоя, і дружини синів твоїх з тобою.","Введи також у ковчег [з усякої худоби, і з усіх плазунів, і] з усіх тварин, і від усякої плоті по парі, щоб вони залишилися з тобою живими; чоловічої статі і жіночої нехай вони будуть.","З [усіх] птахів за родом їх, і з [усієї] худоби за родом її, і з усіх плазунів на землі за родом їх, з усіх по парі ввійдуть до тебе, щоб залишилися живими [з тобою, чоловічої статі і жіночої].","Ти ж візьми собі всякої їжі, яку споживають, і збери до себе; і буде вона для тебе і для них споживою.","І зробив Ной усе: як повелів йому [Господь] Бог, так він і зробив."],"x":{"2":"4.14.1|58.3.1|50.24.38","3":"54.7.51|65.5.16|56.3.20","5":"0.8.21|50.15.19|51.7.21","6":"3.23.19|8.15.11","9":"30.44.16","13":"57.2.5","14":"75.11.7","17":"25.28.10","19":"0.7.9","22":"0.7.5"}},{"v":["І сказав Господь [Бог] Ною: увійди ти і вся сім’я твоя в ковчег, тому що тебе побачив Я праведним переді Мною в роді цьому;","і всякої худоби чистої візьми по семеро, чоловічої статі і жіночої, а з худоби нечистої по двоє, чоловічої статі і жіночої;","також і з птахів небесних [чистих] по сім, чоловічої статі і жіночої, [і з усіх птахів нечистих по двоє, чоловічої статі і жіночої,] щоб зберегти сім’я для всієї землі,","тому що через сім днів Я буду лити дощ на землю сорок днів і сорок ночей; і винищу все, що існує, що Я створив, з лиця землі.","Ной зробив усе, що Господь [Бог] повелів йому.","Ной же був шестисот років, коли потоп водний прийшов на землю.","І ввійшов Ной і сини його, і дружина його, і дружини синів його з ним в ковчег від вод потопу.","І [з птахів чистих і з птахів нечистих, і] з худоби чистої і з худоби нечистої, [і зі звірів] і з усіх плазунів, що на землі","по парі, чоловічої статі і жіночої, ввійшли до Ноя в ковчег, як [Господь] Бог повелів Ною.","Через сім днів води потопу ринули на землю.","В шестисотий рік життя Ноя, у другий місяць, у сімнадцятий [27] день місяця, у цей день відкрилися усі джерела великої безодні, і вікна небесні розчинились;","і лився на землю дощ сорок днів і сорок ночей.","У цей самий день увійшов у ковчег Ной і Сим, Хам і Яфет, сини Ноєві, і дружина Ноєва, і три дружини синів його з ними.","Вони, і всі звірі [землі] за родом їх, і всяка худоба за родом її, і всі плазуни, що плазують по землі, за родом їх, і всі, що літають за родом їх, усі птахи, усі крилаті,","і ввійшли до Ноя в ковчег по парі [чоловічої статі і жіночої] від усякої плоті, в якій є дух життя;","і ті, що ввійшли [до Ноя в ковчег] чоловічої і жіночої статі, від усякої плоті ввійшли, як повелів йому [Господь] Бог. І зачинив Господь [Бог] за ним [ковчег].","І тривав на землі потоп сорок днів [і сорок ночей], і примножилася вода, і підняла ковчег, і він піднявся над землею;","вода ж посилювалася і дуже примножувалася на землі, і ковчег плавав по поверхні вод.","І піднялася вода на землі надзвичайно, так що покрилися усі високі гори, які є під усім небом;","на п’ятнадцять ліктів піднялася над ними вода, і покрилися [усі високі] гори.","І позбулася життя всяка плоть, що рухається по землі, і птахи, і худоба, і звірі, і всі плазуни, що плазують по землі, і всі люди;","усе, що мало дихання духа життя в ніздрях своїх на суші, вмерло.","Знищились усі істоти, що були на поверхні [усієї] землі; від людини до худоби, і плазунів, і птахів небесних, усі були знищені на землі, залишився тільки Ной і те, що було з ним в ковчезі.","Вода ж прибувала на землі сто п’ятдесят днів."],"x":{"1":"56.3.20","5":"0.6.22","7":"50.24.38|52.17.27|56.3.20","9":"0.6.19","11":"24.38.8|26.8.29|11.7.2","16":"0.6.19-20","23":"29.10.4|50.24.39"}},{"v":["І згадав Бог про Ноя, і про всіх звірів, і про всю худобу, [і про всіх птахів, і про всіх плазунів, що плазують,] що були з ним у ковчезі; і навів Бог вітер на землю, і води зупинилися.","І закрилися джерела безодні і вікна небесні, і припинився дощ з неба.","Вода ж поступово поверталася з землі, і стала спадати вода після закінчення ста п’ятдесяти днів.","І зупинився ковчег у сьомому місяці, у сімнадцятий день місяця, на горах Араратських.","Вода постійно спадала до десятого місяця; у перший день десятого місяця показалися верхівки гір.","Після сорока днів Ной відчинив зроблене ним вікно ковчега","і випустив ворона, [щоб бачити, чи спала вода з землі,] який, вилетівши, відлітав і прилітав, доки не осушилася земля від води.","Потім випустив від себе голуба, щоб побачити, чи зійшла вода з лиця землі,","але голуб не знайшов місця спокою для ніг своїх і повернувся до нього в ковчег, тому що вода була ще на поверхні всієї землі; і він простягнув руку свою, і взяв його, і прийняв до себе в ковчег.","І почекав ще сім днів інших і знову випустив голуба з ковчега.","Голуб повернувся до нього у вечірній час, і ось, свіжий оливковий листок у дзьобі в нього, і Ной дізнався, що вода зійшла з землі.","Він почекав ще сім днів інших і [знову] випустив голуба; і він уже не повернувся до нього.","Шістсот першого року [життя Ноя] до першого [дня] першого місяця припинилася вода на землі; і відкрив Ной покрівлю ковчега і подивився, і ось, обсохла поверхня землі.","Й у другому місяці, до двадцять сьомого дня місяця, земля висохла.","І сказав [Господь] Бог Ною:","вийди з ковчега ти і дружина твоя, і сини твої, і дружини синів твоїх з тобою;","виведи із собою всіх тварин, що з тобою, від усякої плоті, з птахів, і худоби, і всіх плазунів, що плазують по землі: нехай розійдуться вони по землі, й нехай плодяться і розмножуються на землі.","І вийшов Ной і сини його, і дружина його, і дружини синів його з ним;","усі звірі, й [уся худоба, й] усі плазуни, й усі птахи, все, що рухається по землі, за родами своїми, вийшли з ковчега.","І влаштував Ной жертовник Господу; і взяв із усякої худоби чистої і з усіх птахів чистих і приніс у всепалення на жертовнику.","І відчув Господь приємні пахощі, і сказав Господь [Бог] у серці Своєму: не буду більше проклинати землю за людину, тому що помисли серця людського — зло від юности його; і не буду більше знищувати усе живе, як Я зробив:","надалі в усі дні землі сівба і жнива, холод і спека, літо і зима, день і ніч не припиняться."],"x":{"1":"25.111.6","2":"0.7.11","4":"32.51.27","17":"0.1.28|0.9.1:7","21":"0.6.5|50.15.19|51.7.21"}},{"v":["І благословив Бог Ноя і синів його і сказав їм: плодіться і розмножуйтеся, і наповнюйте землю, [і володійте нею];","нехай бояться вас і нехай тремтять перед вами усі звірі земні, [і вся худоба земна,] і всі птахи небесні, все, що рухається на землі, й усі риби морські: у ваші руки віддані вони;","все, що рухається, що живе, буде вам у їжу; як зелень трав’яну даю вам усе;","тільки плоті з душею її, з кров’ю її, не їжте;","Я стягну і вашу кров, у якій життя ваше, стягну її від усякого звіра, стягну також душу людини від руки людини, від руки брата її;","хто проллє кров людську, того кров проллється рукою людини: бо людина створена за образом Божим;","ви ж плодіться і розмножуйтесь, і розповсюджуйтеся по землі, і примножуйтеся на ній.","І сказав Бог Ною і синам його з ним:","ось, Я укладу завіт Мій з вами і з нащадками вашими після вас,","і з усякою душею живою, що з вами, із птахами і з худобою, і з усіма звірами земними, які у вас, з усіма, що вийшли з ковчега, з усіма тваринами земними;","укладу завіт Мій з вами, що не буде більше знищена всяка плоть водами потопу, і не буде вже потопу на спустошення землі.","І сказав [Господь] Бог: ось знамення завіту, який Я укладаю між Мною і між вами і між усякою душею живою, що з вами, в роди назавжди:","Я покладаю веселку Мою у хмарі, щоб вона була знаменням [вічного] завіту між Мною і між землею.","І буде, коли Я наведу хмару на землю, то з’явиться веселка [Моя] у хмарі;","і Я згадаю завіт Мій, що між Мною і між вами і між усякою душею живою в усякій плоті; і не буде більше вода потопом на знищення всякої плоті.","І буде веселка [Моя] у хмарі, і Я побачу її, і згадаю завіт вічний між Богом [і між землею] і між усякою душею живою в усякій плоті, що на землі.","І сказав Бог Ною: ось знамення завіту, який Я уклав між Мною і між усякою плоттю, що на землі.","Сини Ноєві, що вийшли з ковчега, були: Сим, Хам і Яфет. Хам же був батьком Ханаана.","Ці троє були синами Ноєвими, і від них заселилась уся земля.","Ной почав обробляти землю і насадив виноградник;","і випив він вина, і сп’янів, і лежав оголеним у наметі своєму.","І побачив Хам, батько Ханаана, наготу батька свого, і, вийшовши, розповів двом братам своїм.","Сим же і Яфет взяли одяг і, поклавши його на плечі свої, пішли задом і покрили наготу батька свого; обличчя їхні були повернені назад, і вони не бачили наготи батька свого.","Ной витверезів від вина свого і довідався, що вчинив над ним менший син його,","і сказав: проклятий Ханаан; раб рабів буде він у братів своїх.","Потім сказав: благословенний Господь Бог Симів; Ханаан же буде рабом йому;","нехай поширить Бог Яфета, нехай оселиться він у наметах Симових; Ханаан же буде рабом йому.","І жив Ной після потопу триста п’ятдесят років.","Усіх же днів Ноєвих було дев’ятсот п’ятдесят років, і він помер."],"x":{"1":"0.1.28|0.8.17","2":"0.1.28","4":"2.3.17|2.7.26|2.17.14","6":"50.26.52|76.13.10|0.1.27","7":"0.1.28|0.8.17|0.9.1","11":"31.54.9","13":"30.43.12","26":"5.16.10|6.1.9"}},{"v":["Ось родовід синів Ноєвих: Сима, Хама і Яфета. Після потопу народилися в них діти.","Сини Яфета: Гомер, Магог, Мадай, Іаван, [Єлиса,] Фувал, Мешех і Фирас.","Сини Гомера: Аскеназ, Рифат і Фогарма.","Сини Іавана: Єлиса, Фарсис, Киттим і Доданим.","Від цих населилися острови народів у землях їх, кожен за мовою своєю, за племенем своїм, у народах своїх.","Сини Хама: Хуш, Мицраїм, Фут і Ханаан.","Сини Хуша: Сева, Хавила, Савта, Раама і Савтеха. Сини Раами: Шева і Дедан.","Хуш породив також Нимрода; цей став сильним на землі;","він був сильним звіроловом перед Господом [Богом], тому і говориться: сильний звіролов, як Нимрод, перед Господом [Богом].","Царство його спочатку складали: Вавилон, Ерех, Аккад і Халне в землі Сеннаар.","З цієї землі вийшов Ассур і побудував Ниневію, Реховофир, Калах","і Ресен між Ниневією і між Калахом; це місто велике.","Від Мицраїма пішли Лудим, Анамим, Легавим, Нафтухим,","Патрусим, Каслухим, звідки вийшли филистимляни, і Кафторим.","Від Ханаана народилися: Сидон, первісток його, Хет,","Ієвусей, Аморрей, Гергесей,","Евей, Аркей, Синей,","Арвадей, Цемарей і Химафей. Згодом племена ханаанські розсіялися,","і були межі хананеїв від Сидона до Герара до Гази, звідси до Содома, Гоморри, Адми і Цевоїма до Лаши.","Це сини Хамові, за племенами їх, за мовою їх, у землях їх, у народах їх.","Були діти й у Сима, батька всіх синів Єверових, старшого брата Яфетового.","Сини Сима: Єлам, Ассур, Арфаксад, Луд, Арам [і Каїнан].","Сини Арама: Уц, Хул, Гефер і Маш.","Арфаксад породив [Каїнана, Каїнан породив] Салу, Сала породив Євера.","У Євера народилося два сини; ім’я одному: Фалек, тому що в дні його земля була розділена; ім’я брата його: Іоктан.","Іоктан породив Алмодада, Шалефа, Хацармавефа, Ієраха,","Гадорама, Узала, Диклу,","Овалу, Авимаїла, Шеву,","Офира, Хавилу та Іовава. Усі ці сини Іоктана.","Поселення їх були від Меши до Сефара, гори східної.","Це сини Симові за племенами їх, за мовами їх, у землях їх, у народах їх.","Ось племена синів Ноєвих, за родоводом їх, у народах їх. Від них пішли народи на землі після потопу."],"x":{"1":"0.5.32","2":"12.1.5","4":"3.24.24|31.23.1","8":"12.1.10|32.16.16","10":"40.6.2","14":"4.2.23","22":"12.1.17","25":"12.1.19|0.11.8","30":"3.23.7"}},{"v":["На всій землі була одна мова й один говір.","Рухаючись зі сходу, вони знайшли в землі Сеннаар рівнину й оселилися там.","І сказали одне одному: наробимо цегли і випалимо вогнем. І стала у них цегла замість каменю, а земляна смола замість вапна.","І сказали вони: збудуємо собі місто і вежу, висотою до небес, і зробимо собі ім’я, перш ніж розсіємося по лицю всієї землі.","І зійшов Господь подивитися місто і вежу, що будували сини людські.","І сказав Господь: ось, один народ, і одна у всіх мова; і ось що почали вони робити, і не відстануть вони від того, що задумали робити;","зійдемо ж і змішаємо там мову їхню, так щоб один не розумів мови іншого.","І розсіяв їх Господь звідти по всій землі; і вони перестали будувати місто [і вежу].","Тому дано йому ім’я: Вавилон, бо там змішав Господь мову всієї землі, і звідти розсіяв їх Господь по всій землі.","Ось родовід Сима: Сим був ста років і породив Арфаксада, через два роки після потопу;","після народження Арфаксада Сим жив п’ятсот років і породив синів і дочок [і помер].","Арфаксад жив тридцять п’ять [135] років і породив [Каїнана. Після нарождення Каїнана Арфаксад жив триста тридцять років і породив синів і дочок і помер. Каїнан жив сто тридцять років, і породив] Салу.","Після нарождення Сали Арфаксад [Каїнан] жив чотириста три [330] роки і породив синів і дочок [і помер].","Сала жив тридцять [130] років і породив Євера.","Після народження Євера Сала жив чотириста три [330] роки і породив синів і дочок [і помер].","Євер жив тридцять чотири [134] роки і породив Фалека.","Після народження Фалека Євер жив чотириста тридцять [370] років і породив синів і дочок [і помер].","Фалек жив тридцять [130] років і породив Рагава.","Після народження Рагава Фалек жив двісті дев’ять років і породив синів і дочок [і помер].","Рагав жив тридцять два [132] роки і породив Серуха.","Після народження Серуха Рагав жив двісті сім років і породив синів і дочок [і помер].","Серух жив тридцять [130] років і породив Нахора.","Після народження Нахора Серух жив двісті років і породив синів і дочок [і помер].","Нахор жив двадцять дев’ять [79] років і породив Фарру.","Після народження Фарри Нахор жив сто дев’ятнадцять [129] років і породив синів і дочок [і помер].","Фарра жив сімдесят років і породив Аврама, Нахора й Арана.","Ось родовід Фарри: Фарра породив Аврама, Нахора й Арана. Аран породив Лота.","І вмер Аран за Фарри, батька свого, у землі народження свого, в Урі халдейському.","Аврам і Нахор взяли собі дружин; ім’я дружини Аврамової: Сара; ім’я дружини Нахорової: Милка, дочка Арана, батька Милки і батька Іски.","І Сара була неплідна і бездітна.","І взяв Фарра Аврама, сина свого, і Лота, сина Аранового, онука свого, і Сару, невістку свою, дружину Аврама, сина свого, і вийшов з ними з Ура халдейського, щоб іти в землю Ханаанську; але, дійшовши до Харрана, вони зупинилися там.","І було днів життя Фарри [у Харранській землі] двісті п’ять років, і вмер Фарра в Харрані."],"x":{"4":"4.1.28","8":"4.32.8","10":"12.1.17","16":"12.1.19","26":"5.24.2|12.1.26-27","31":"5.24.3"}},{"v":["І сказав Господь Авраму: піди з землі твоєї, від роду твого і з дому батька твого [і йди] у землю, яку Я покажу тобі;","і Я спороджу від тебе великий народ, і благословлю тебе, і звеличу ім’я твоє, і будеш ти благословенням;","Я благословлю тих, що благословляють тебе, і тих, що лихословлять тебе, прокляну; і благословляться у тобі всі племена земні.","І пішов Аврам, як сказав йому Господь; і з ним пішов Лот. Аврам був сімдесяти п’яти років, коли вийшов з Харрана.","І взяв Аврам з собою Сару, дружину свою, Лота, сина брата свого, і все майно, яке вони придбали, і всіх людей, яких вони мали в Харрані; і вийшли, щоб іти в землю Ханаанську; і прийшли в землю Ханаанську.","І пройшов Аврам по землі цій [у довжину її] до місця Сихема, до діброви Море́. У цій землі тоді [жили] хананеї.","І явився Господь Авраму і сказав [йому]: нащадкам твоїм віддам Я землю цю. І зробив там [Аврам] жертовник Господу, Який явився йому.","Звідти рушив він до гори, на схід від Вефиля; і поставив намет свій так, що від нього Вефиль був на захід, а Гай на схід; і зробив там жертовник Господу і закликав ім’я Господа [Який явився йому].","І піднявся Аврам і продовжував йти на південь.","І був голод у тій землі. І прийшов Аврам у Єгипет, щоб пожити там, тому що посилився голод у землі тій.","Коли ж він наближався до Єгипту, то сказав Сарі, дружині своїй: ось, я знаю, що ти жінка, прекрасна на вигляд;","і коли єгиптяни побачать тебе, то скажуть: це дружина його; і вб’ють мене, а тебе залишать живою;","скажи ж, що ти моя сестра, щоб мені добре було заради тебе, і щоб жива була душа моя через тебе.","І було, коли прийшов Аврам у Єгипет, єгиптяни побачили, що вона жінка дуже красива;","побачили її і вельможі фараонові і похвалили її перед фараоном; і взята вона була до дому фараонового.","І Авраму добре було заради неї; і була у нього дрібна і велика худоба й осли, і раби і рабині, і мули і верблюди.","Але Господь уразив тяжкими ударами фараона і дім його за Сару, дружину Аврамову.","І покликав фараон Аврама і сказав: що це ти зробив зі мною? чому не сказав мені, що вона дружина твоя?","чому ти сказав: вона сестра моя? і я взяв було її собі за дружину. І тепер ось дружина твоя; візьми [її] і йди.","І дав фараон повеління про нього людям, і провели його, і дружину його, й усе, що в нього було, [і Лота з ним]."],"x":{"1":"54.7.3","3":"0.18.18|0.22.18|0.26.4|65.3.8:16","6":"0.18.1|0.33.18|0.37.12","7":"0.13.15|0.15.7:18|0.26.3-4|4.34.4","8":"0.13.3|0.28.19","13":"0.20.2","16":"0.13.2","17":"25.104.14"}},{"v":["І піднявся Аврам з Єгипту, сам і дружина його, й усе, що в нього було, і Лот з ним, на південь.","І був Аврам дуже багатий на худобу, і срібло, і золото.","І продовжував він переходи свої від півдня до Вефиля, до місця, де колись був намет його між Вефилем і між Гаєм,","до місця жертовника, який він зробив там спочатку; і там прикликав Аврам ім’я Господа.","І у Лота, який ходив з Аврамом, також була дрібна і велика худоба і намети.","І не вміщала їх та земля, щоб жити разом, бо майно їхнє було таке велике, що вони не могли жити разом.","І була суперечка між пастухами худоби Аврамової і між пастухами худоби Лотової; і хананеї і ферезеї жили тоді в тій землі.","І сказав Аврам Лотові: нехай не буде розбрату між мною і тобою, і між пастухами моїми і пастухами твоїми, тому що ми родичі;","чи не вся земля перед тобою? відділись же від мене: якщо ти ліворуч, то я праворуч; а якщо ти праворуч, то я ліворуч.","Лот звів очі свої і побачив усю околицю Йорданську, що вона, перш ніж знищив Господь Содом і Гоморру, вся до Сигора зрошувалася водою, як сад Господній, як земля Єгипетська;","і обрав собі Лот усю околицю Йорданську; і рушив Лот на схід. І відокремилися вони один від одного.","Аврам став жити в землі Ханаанській; а Лот став жити у містах околиці і розкинув намети до Содома.","Жителі ж содомські були злі і грішні перед Господом.","І сказав Господь Авраму, після того як Лот відокремився від нього: зведи очі твої з місця, на якому ти тепер, подивися на північ і на південь, і на схід і на захід;","бо всю землю, що ти бачиш, Я дам тобі і нащадкам твоїм навіки,","і зроблю нащадків твоїх, як пісок земний; якщо хто може порахувати пісок земний, то і нащадки твої полічені будуть;","встань, пройди по землі цій у довжину й у ширину її, бо Я дам її тобі [і нащадкам твоїм назавжди].","І зняв Аврам намет, і пішов, і оселився біля діброви Мамре, що в Хевроні; і зробив там жертовник Господу."],"x":{"1":"25.104.13","2":"0.24.35|26.10.22","3":"0.12.8|0.35.6","4":"0.12.7-8","6":"0.36.7","7":"0.21.25","8":"25.33.15|0.11.27|0.14.12","10":"0.2.8|31.51.3|31.28.13","13":"0.18.20|0.19.13|36.16.49","15":"0.12.7|0.15.18|0.26.4|4.34.4","16":"0.32.12|4.10.22","18":"3.13.23"}},{"v":["І було у дні Амрафела, царя Сеннаарського, Аріоха, царя Єлласарського, Кедорлаомера, царя Єламського, і Фидала, царя Гоїмського,","пішли вони війною проти Бери, царя Содомського, проти Бирши, царя Гоморрського, Шинава, царя Адми, Шемевера, царя Севоїмського, і проти царя Бели, яка є Сигор.","Усі ці з’єдналися в долині Сиддим, де нині море Солоне.","Дванадцять років були вони в неволі у Кедорлаомера, а на тринадцятий рік обурилися.","В чотирнадцятому році прийшли Кедорлаомер і царі, що з ним, й уразили рефаїмів в Аштероф-Карнаїмі, зузимів у Гамі, емимів у Шаве-Кириафаїмі,","і хорреїв у горі їх Сеїрі, до Ел-Фарана, що біля пустелі.","І повернувшись звідти, вони прийшли до джерела Мишпат, що є Кадес, і завоювали всю країну амаликитян, і також аморреїв, що живуть у Хацацон-Фамарі.","І вийшли цар Содомський, цар Гоморрський, цар Адми, цар Севоїмський і цар Бели, яка є Сигор; і вступили в битву з ними в долині Сиддим,","з Кедорлаомером, царем Єламським, Фидалом, царем Гоїмським, Амрафелом, царем Сеннаарським, Аріохом, царем Єлласарським, — чотири царі проти п’яти.","В долині ж Сиддим було багато смоляних ям. І царі Содомський і Гоморрський, утікаючи, упали в них, а останні втекли в гори.","Переможці взяли все майно Содома і Гоморри і весь запас їх і пішли.","І взяли Лота, племінника Аврамового, який жив у Содомі, і майно його і пішли.","І прийшов один з тих, хто уцілів, і сповістив Аврама єврея, який жив тоді біля діброви Мамре, аморреянина, брата Ешколу і брата Анеру, які були союзниками Аврамовими.","Аврам, почувши, що [Лот] родич його узятий у полон, озброїв рабів своїх, і народжених у домі його, триста вісімнадцять, і переслідував ворогів до Дана;","і, розділившись, напав на них уночі, сам і раби його, і подолав їх, і переслідував їх до Хови, що ліворуч від Дамаска;","і повернув усе майно і Лота, родича свого, і майно його повернув, також і жінок і народ.","Коли він повертався після поразки Кедорлаомера і царів, що були з ним, цар Содомський вийшов йому назустріч у долину Шаве, що нині долина царська;","і Мелхиседек, цар Салимський, виніс хліб і вино, — він був священик Бога Всевишнього, —","і благословив його, і сказав: благословенний Аврам від Бога Всевишнього, Владики неба і землі;","і благословенний Бог Всевишній, Який віддав ворогів твоїх у руки твої. [Аврам] дав йому десяту частину з усього.","І сказав цар Содомський Авраму: віддай мені людей, а майно візьми собі.","Але Аврам сказав цареві Содомському: піднімаю руку мою до Господа Бога Всевишнього, Владики неба і землі,","що навіть нитки і ременя від взуття не візьму з усього твого, щоб ти не сказав: я збагатив Аврама;","крім того, що з’їли слуги, і, крім частки, що належить людям, які ходили зі мною; Анер, Ешкол і Мамрій нехай візьмуть свою частку."],"x":{"1":"0.10.10|0.11.2","2":"0.19.22","13":"0.17.8|75.11.9:13","14":"5.19.47","17":"9.18.18","18":"75.7.1","20":"75.7.4","24":"0.14.13"}},{"v":["Після цих подій було слово Господнє до Аврама у видінні [вночі], і сказано: не бійся, Авраме; Я твій щит; нагорода твоя [буде] дуже велика.","Аврам сказав: Владико Господи! що Ти даси мені? я залишаюся бездітним; розпорядник у домі моєму цей Єлиєзер із Дамаска.","І сказав Аврам: ось, Ти не дав мені нащадка, і ось, управитель мій спадкоємець мій.","І було слово Господа до нього, і сказано: не буде він твоїм спадкоємцем, але той, хто народиться з лона твого, буде твоїм спадкоємцем.","І вивів його геть і сказав [йому]: подивися на небо і порахуй зірки, якщо ти можеш порахувати їх. І сказав йому: стільки буде в тебе нащадків.","Аврам повірив Господу, і Він поставив йому це в праведність.","І сказав йому: Я Господь, Який вивів тебе з Ура халдейського, щоб дати тобі землю цю у володіння.","Він сказав: Владико Господи! З чого я довідаюсь, що я буду володіти нею?","Господь сказав йому: візьми Мені трирічну телицю, трирічну козу, трирічного барана, горлицю і молодого голуба.","Він взяв усіх їх, розсік їх навпіл і поклав одну частину навпроти другої; тільки птахів не розсік.","І налетіли на трупи хижі птахи; але Аврам відганяв їх.","Коли заходило сонце, міцний сон напав на Аврама, і ось, напав на нього жах і морок великий.","І сказав Господь Авраму: знай, що нащадки твої будуть мандрівниками в землі не своїй, і поневолять їх, і будуть гнітити їх чотириста років,","але Я вчиню суд над народом, у якого вони будуть у неволі; після цього вони вийдуть [сюди] з великим майном,","а ти відійдеш до батьків твоїх у мирі і будеш похований у старості добрій;","у четвертому роді повернуться вони сюди: тому що міра беззаконь аморреїв досі ще не наповнилася.","Коли зайшло сонце і настала темрява, ось, дим, ніби з печі, і полум’я вогню пройшли між розсіченими тваринами.","В цей день уклав Господь завіт з Аврамом, сказавши: нащадкам твоїм даю Я землю цю, від ріки Єгипетської до великої ріки, ріки Євфрату:","кенеїв, кенезеїв, кедмонеїв,","хеттеїв, ферезеїв, рефаїмів,","аморреїв, хананеїв, [евеїв,] гергесеїв і євусеїв."],"x":{"1":"31.40.10|31.41.10|31.43.1","2":"0.24.2","5":"0.22.17","6":"62.4.3|65.3.6|55.2.23","10":"1.12.41","13":"54.7.6|1.12.40","17":"32.34.18","18":"0.12.7|0.13.15|0.26.4|4.34.4"}},{"v":["Але Сара, дружина Аврамова, не народжувала йому. У неї була служниця, єгиптянка, на ім’я Агар.","І сказала Сара Авраму: ось, Господь закрив утробу мою, щоб я не народжувала; увійди ж до служниці моєї: можливо, я буду мати дітей від неї. Аврам послухався слів Сари.","І взяла Сара, дружина Аврамова, служницю свою, єгиптянку Агар, після десяти років перебування Аврамового в землі Ханаанській, і дала її Авраму, чоловіку своєму, за дружину.","Він увійшов до Агарі, і вона зачала. Побачивши ж, що зачала, вона стала зневажати господиню свою.","І сказала Сара Авраму: в обра́зі моїй винен ти; я віддала служницю мою в надра твої; а вона, побачивши, що зачала, стала нехтувати мене; Господь нехай буде суддею між мною і між тобою.","Аврам сказав Сарі: ось, служниця твоя у твоїх руках; роби з нею, що тобі завгодно. І Сара почала пригноблювати її, і вона втекла від неї.","І знайшов її ангел Господній біля джерела води в пустелі, біля джерела на дорозі до Сура.","І сказав [їй ангел Господній]: Агар, служнице Сарина! звідки ти прийшла і куди йдеш? Вона сказала: я втікаю від лиця Сари, господині моєї.","Ангел Господній сказав їй: повернися до господині своєї і підкорися їй.","І сказав їй ангел Господній: примножуючи, примножу нащадків твоїх, так що не можна буде й перерахувати їх від безлічі.","І ще сказав їй ангел Господній: ось, ти вагітна, і народиш сина, і наречеш йому ім’я Ізмаїл, тому що почув Господь страждання твоє;","він буде між людьми, як дикий осел; руки його на всіх, і руки усіх на нього; жити буде він перед лицем усіх братів своїх.","І нарекла [Агар] Господа, Який говорив до неї, цим ім’ям: Ти Бог, що бачиш мене. Бо сказала вона: дійсно я бачила тут у слід Того, Хто бачить мене.","Тому джерело те називається: Беер-лахай-рої*. Воно знаходиться між Кадесом і між Баредом.","Агар народила Авраму сина; і дав [Аврам] ім’я синові своєму, що народився від Агарі: Ізмаїл.","Аврам був вісімдесяти шести років, коли Агар народила Авраму Ізмаїла."],"x":{"14":"0.24.62","15":"65.4.22"},"n":{"14":["Джерело Живого, що бачить мене."]}},{"v":["Аврам був дев’яноста дев’яти років, і Господь явився Аврамові і сказав йому: Я Бог всемогутній; ходи переді Мною і будь непорочним;","і поставлю завіт Мій між Мною і тобою, і дуже, дуже розмножу тебе.","І упав Аврам на лице своє. Бог продовжував говорити з ним і сказав:","Я — ось завіт Мій з тобою: ти будеш отцем безлічі народів,","і не будеш ти більше називатися Аврамом, але буде тобі ім’я: Авраам, тому що я зроблю тебе отцем безлічі народів;","і дуже, дуже розмножу тебе, і народжу від тебе народи, і царі вийдуть від тебе;","і поставлю завіт Мій між Мною і тобою і між нащадками твоїми після тебе в роди їх, завіт вічний в тому, що Я буду Богом твоїм і нащадків твоїх після тебе;","і дам тобі і нащадкам твоїм після тебе землю, по якій ти мандруєш, усю землю Ханаанську, у володіння вічне; і буду їм Богом.","І сказав Бог Авраамові: ти ж збережи завіт Мій, ти і нащадки твої після тебе в роди їх.","Цей є завіт Мій, який ви повинні зберігати між Мною і між вами і між нащадками твоїми після тебе [в роди їхні]: нехай буде у вас обрізана уся чоловіча стать;","обрізуйте крайню плоть вашу: і це буде знаменням завіту між Мною і вами.","Восьми днів від народження нехай буде обрізане у вас в роди ваші всяке немовля чоловічої статі, народжене у домі і куплене за срібло в якого-небудь іноплемінника, який не від твого сімені.","Обов’язково нехай буде обрізаний народжений у домі твоєму і куплений за срібло твоє, і буде завіт Мій на тілі вашому завітом вічним.","Необрізаний же чоловічої статі, який не обріже крайньої плоті своєї [у восьмий день], знищиться душа його з народу свого, тому що він порушив завіт Мій.","І сказав Бог Аврааму: Сару, дружину твою, не називай Сарою, але нехай буде ім’я їй: Сарра;","Я благословлю її і дам тобі від неї сина; благословлю її, і народяться від неї народи, і царі народів народяться від неї.","І упав Авраам на лице своє, і розсміявся, і сказав сам у собі: невже від столітнього буде син? і Сарра, дев’яностолітня, невже народить?","І сказав Авраам Богові: о, хоч би Ізмаїл був живим перед лицем Твоїм!","Бог же сказав [Аврааму]: саме Сарра, дружина твоя, народить тобі сина, і ти наречеш йому ім’я: Ісаак; і укладу завіт Мій з ним завітом вічним [в тому, що Я буду Богом йому і] нащадкам його після нього.","І про Ізмаїла Я почув тебе: ось, Я благословлю його, і зроблю його плодовитим, і дуже, дуже розмножу; дванадцять князів народяться від нього; і Я породжу від нього великий народ.","Але завіт Мій укладу з Ісааком, якого народить тобі Сарра в цей самий час на наступний рік.","І Бог перестав говорити з Авраамом і відійшов від нього.","І взяв Авраам Ізмаїла, сина свого, і всіх народжених у домі своїм і всіх куплених за срібло своє, всіх чоловічої статі людей дому Авраамового; і обрізав крайню плоть їх у той самий день, як сказав йому Бог.","Авраам був дев’яноста дев’яти років, коли була обрізана крайня плоть його.","А Ізмаїл, син його, був тринадцяти років, коли була обрізана крайня плоть його.","У тот же самий день обрізані були Авраам і Ізмаїл, син його,","і з ним обрізані були всі чоловічої статі дому його, народжені в домі і куплені за срібло в іноплемінників."],"x":{"1":"0.12.7|0.24.40|0.48.15","2":"0.12.2","4":"30.44.19-20|62.4.17","5":"31.51.2","6":"50.1.6","7":"0.15.18|11.13.23|2.26.12","9":"54.7.8","10":"2.12.3|52.2.21|53.7.22","16":"65.4.23|31.51.2|50.1.6","17":"0.18.12|52.1.18","19":"0.18.10|0.21.1-2|52.1.55","20":"0.25.13-16","21":"62.9.9"}},{"v":["І явився йому Господь біля діброви Мамре, коли він сидів при вході в намет [свій], під час спеки денної.","Він звів очі свої і глянув, і ось, три мужі стоять навпроти нього. Побачивши, він побіг назустріч їм від входу в намет [свій] і поклонився до землі,","і сказав: Владико! якщо я знайшов благовоління перед очима Твоїми, не пройди мимо раба Твого;","і принесуть трохи води, й омиють ноги ваші; і відпочинете під цим деревом,","а я принесу хліба, і ви підкріпите серця ваші; потім підіть [у путь свою]; тому що ви йдете мимо раба вашого. Вони сказали: зроби так, як говориш.","І поспішив Авраам в намет до Сарри і сказав [їй]: скоріше заміси три сати кращого борошна і зроби прісні хліби.","І побіг Авраам до стада, і взяв теля ніжне і гарне, і дав слузі, і той поспішив приготувати його.","І взяв олії і молока і теля приготоване, і поставив перед ними, а сам стояв біля них під деревом. І вони їли.","І сказали йому: де Сарра, дружина твоя? Він відповів: тут, у наметі.","І сказав один з них: Я знову буду в тебе у цей же час [у наступному році], і буде син у Сарри, дружини твоєї. А Сарра слухала при вході в намет, позаду його.","Авраам же і Сарра були старі й у літах похилих, і звичайне у жінок у Сарри припинилося.","Сарра внутрішньо розсміялася, сказавши: чи мені, коли я постаріла, мати цю втіху? і господар мій старий.","І сказав Господь Аврааму: чому це [сама в собі] розсміялася Сарра, сказавши: «невже я дійсно можу народити, коли я постаріла»?","Чи є щось важке для Господа? У призначений час буду Я у тебе в наступному році, і [буде] у Сарри син.","Сарра ж не зізналася, а сказала: я не сміялася. Тому що вона злякалася. Але Він сказав [їй]: ні, ти розсміялася.","І встали ті мужі і звідти вирушили до Содома [і Гоморри]; Авраам же пішов з ними, провести їх.","І сказав Господь: чи утаю Я від Авраама [раба Мого], що хочу вчинити!","Від Авраама дійсно піде народ великий і сильний, і благословляться в ньому всі народи землі,","тому що Я обрав його для того, щоб він заповів синам своїм і дому своєму після себе, ходити путтю Господньою, творячи правду і суд; і здійснить Господь над Авраамом [усе], що сказав про нього.","І сказав Господь: крик содомський і гоморрський, великий він, і гріх їх, дуже тяжкий він;","зійду і подивлюся, чи дійсно вони чинять так, яке волання проти них, що доходить до Мене, чи ні; дізнаюся.","І повернули мужі звідти і пішли до Содома; Авраам же ще стояв перед лицем Господа.","І підійшов Авраам і сказав: невже Ти погубиш праведного з нечестивим [і з праведником буде те саме, що з нечестивим]?","може, є в цьому місті п’ятдесят праведників? невже Ти погубиш, і не пощадиш [усього] місця цього ради п’ятдесятьох праведників, [якщо вони перебувають] у ньому?","не може бути, щоб Ти вчинив так, щоб Ти погубив праведного з нечестивим, щоб те саме було з праведником, що з нечестивим; не може бути від Тебе! Суддя всієї землі чи вчинить неправосудно?","Господь сказав: якщо Я знайду в місті Содомі п’ятдесят праведників, то Я заради них пощаджу [все місто й] усе місце це.","Авраам сказав у відповідь: ось, я насмілився говорити Владиці, я, порох і попіл:","можливо, до п’ятдесяти праведників не вистачить п’яти, невже через недостачу п’яти Ти винищиш усе місто? Він сказав: не винищу, якщо найду там сорок п’ять.","Авраам продовжував говорити з Ним і сказав: можливо, знайдеться там сорок? Він сказав: не зроблю того і заради сорока.","І сказав Авраам: нехай не прогнівається Владика, що я буду говорити: може, знайдеться там тридцять? Він сказав: не зроблю, якщо знайдеться там тридцять.","Авраам сказав: ось, я зважився говорити Владиці: можливо, знайдеться там двадцять? Він сказав: не знищу ради двадцяти.","Авраам сказав: нехай не прогнівається Владика, що я скажу ще один раз: можливо, знайдеться там десять? Він сказав: не винищу заради десяти.","І пішов Господь, припинивши говорити з Авраамом; Авраам же повернувся у своє місто."],"x":{"1":"0.13.18|0.17.1","2":"75.13.2","4":"71.5.10","5":"25.103.15","6":"8.28.24|10.17.13","10":"0.17.19|0.21.1-2|62.9.9","11":"62.4.19|75.11.11","12":"56.3.6","14":"32.32.27|48.8.6|50.19.26","18":"0.12.3|0.22.18","19":"4.4.9|4.6.7","20":"0.19.13|36.16.48","21":"0.11.5","25":"25.7.9|53.5.27|54.17.31","27":"0.2.7|24.30.19|27.12.7","32":"55.5.16"}},{"v":["І прийшли ті два ангели в Содом увечері, коли Лот сидів біля воріт Содома. Лот побачив, і встав, щоб зустріти їх, і поклонився лицем до землі","і сказав: господарі мої! зайдіть у дім раба вашого і ночуйте, й умийте ноги ваші, і встаньте вранці і підете дорогою своєю. Але вони сказали: ні, ми ночуємо на вулиці.","Він же дуже умовляв їх; і вони пішли до нього і зайшли в дім його. Він зробив їм частування і спік прісні хліби, і вони їли.","Ще не лягли вони спати, як міські жителі, содомляни, від молодого до старого, весь народ з усіх кінців міста, оточили будинок","і викликали Лота і говорили йому: де люди, які прийшли до тебе на ніч? виведи їх до нас; ми пізнаємо їх.","Лот вийшов до них до входу, і замкнув за собою двері,","і сказав [їм]: брати мої, не робіть зла;","ось у мене дві дочки, що не пізнали чоловіка; краще я виведу їх до вас, робіть з ними, що вам завгодно, тільки людям цим не робіть нічого, тому що вони прийшли під дах дому мого.","Але вони сказали [йому]: йди сюди. І сказали: ось прийшлий, і хоче судити? тепер ми гірше вчинимо з тобою, ніж з ними. І дуже приступали до людини цієї, до Лота, і підійшли, щоб виламати двері.","Тоді мужі ті простягли руки свої і ввели Лота до себе в дім, і двері [дому] замкнули;","а людей, що були при вході в дім, уразили сліпотою, від малого до великого, так що вони змучилися, шукаючи входу.","Сказали мужі ті Лотові: хто в тебе є ще тут? чи зять, чи сини твої, чи дочки твої, і хто б не був у тебе в місті, усіх виведи із цього місця,","тому що ми винищимо це місце, бо великий крик на жителів його до Господа, і Господь послав нас винищити його.","І вийшов Лот, і говорив із зятями своїми, які брали за себе дочок його, і сказав: встаньте, вийдіть із цього місця, бо Господь винищить це місто. Але зятям його здалося, що він жартує.","Коли зійшла зоря, ангели почали прискорювати Лота, говорячи: встань, візьми дружину твою і двох дочок твоїх, які в тебе, щоб не загинути тобі за беззаконня міста.","І оскільки він барився, то мужі ті [ангели], з милости до нього Господньої, взяли за руку його і дружину його, і двох дочок його, і вивели його і поставили його за містом.","Коли ж вивели їх геть, то один з них сказав: спасай душу свою; не оглядайся назад і ніде не зупиняйся в околиці цій; спасайся на горі, щоб тобі не загинути.","Але Лот сказав їм: ні, Владико!","ось, раб Твій знайшов благовоління перед очима Твоїми, і велика милість Твоя, яку Ти зробив зі мною, що врятував життя моє; але я не можу спасатися на горі, щоб не застигло мене лихо і я не вмер;","ось, ближче тікати у це місто, воно ж мале; побіжу я туди, — воно ж мале; і збережеться життя моє [заради Тебе].","І сказав йому: ось, в угоду тобі Я зроблю і це: не знищу місто, про яке ти говориш;","поспішай, спасайся там, тому що Я не можу зробити справи, доки ти не прийдеш туди. Тому і назване місто це: Сигор.","Сонце зійшло над землею, і Лот прийшов у Сигор.","І пролив Господь на Содом і Гоморру дощем сірку і вогонь від Господа з неба,","і знищив міста ці, і всю околицю цю, і всіх жителів міст цих, і [всі] рослини землі.","Дружина ж Лотова оглянулася позаду нього, і стала соляним стовпом.","І встав Авраам рано-вранці [і пішов] на місце, де стояв перед лицем Господа,","і подивився на Содом і Гоморру і на весь простір околиці і побачив: ось, дим піднімається з землі, як дим із печі.","І було, коли Бог винищував [усі] міста околиці цієї, згадав Бог про Авраама і вислав Лота із середовища знищення, коли нищив міста, в яких жив Лот.","І вийшов Лот із Сигора і став жити в горí, і з ним дві дочки його, тому що він боявся жити в Сигорі. І жив у печері, і з ним дві дочки його.","І сказала старша молодшій: батько наш старий, і немає людини на землі, яка ввійшла б до нас за звичаєм усієї землі;","отже, напоїмо батька нашого вином, і переспимо з ним, і відродимо від батька нашого плем’я.","І напоїли батька свого вином у ту ніч; і ввійшла старша і спала з батьком своїм [у ту ніч]; а він не знав, коли вона лягла і коли встала.","На другий день старша сказала молодшій: ось, я спала вчора з батьком моїм; напоїмо його вином і в цю ніч; і ти ввійди, спи з ним, і відродимо від батька нашого плем’я.","І напоїли батька свого вином і в цю ніч; і ввійшла молодша і спала з ним; і він не знав, коли вона лягла і коли встала.","І зробилися обидві дочки Лотові вагітними від батька свого,","і народила старша сина, і нарекла йому ім’я: Моав [говорячи: він від батька мого]. Він батько моавитян донині.","І молодша також народила сина, і нарекла йому ім’я: Бен-Аммі [говорячи: він син роду мого]. Він батько аммонитян донині."],"x":{"1":"0.18.2","2":"75.13.2|0.18.4","5":"6.19.22|62.1.27","7":"36.16.48","9":"57.2.7-8","11":"29.19.16","14":"13.30.10|50.24.38|52.17.27-28","17":"29.10.6","22":"1.32.10|29.10.6|0.13.10","24":"4.29.23|31.13.19|32.50.40|36.16.49|40.4.11|52.17.29|61.1.7|57.2.6","26":"29.10.7|52.17.32","27":"0.18.22","32":"2.18.7","37":"4.2.9"}},{"v":["Авраам піднявся звідти на південь і оселився між Кадесом і між Суром; і був тимчасово в Герарі.","І сказав Авраам про Сарру, дружину свою: вона сестра моя. [Тому що він боявся сказати, що це дружина його, щоб жителі міста того не вбили його за неї.] І послав Авимелех, цар Герарський, і взяв Сарру.","І прийшов Бог до Авимелеха вночі уві сні і сказав йому: ось, ти вмреш за жінку, яку ти взяв, тому що вона має чоловіка.","Авимелех же не доторкався до неї і сказав: Владико! невже ти погубиш [того, хто не знав цього] і невинний народ?","Чи не сам він сказав мені: вона сестра моя? І вона сама сказала: він брат мій. Я зробив це у простоті серця мого й у чистоті рук моїх.","І сказав йому Бог уві сні: і Я знаю, що ти зробив це у простоті серця твого, і стримав тебе від гріха переді Мною, тому і не допустив тебе доторкнутися до неї;","тепер же поверни дружину чоловікові, бо він пророк і помолиться за тебе, і ти будеш живий; а якщо не повернеш, то знай, що неодмінно помреш ти й усі твої.","І встав Авимелех рано-вранці і покликав усіх рабів своїх, і переказав усі слова ці у вуха їхні; і люди ці [усі] дуже злякалися.","І покликав Авимелех Авраама і сказав йому: що ти з нами зробив? чим згрішив я проти тебе, що ти навів було на мене і на царство моє великий гріх? Ти зробив зі мною діла, які не роблять.","І сказав Авимелех Аврааму: що ти мав на увазі, коли чинив цю справу?","Авраам сказав: я подумав, що немає на місці цьому страху Божого, й уб’ють мене за дружину мою;","та вона і насправді сестра мені: вона дочка батька мого, тільки не дочка матері моєї; і стала моєю дружиною;","коли Бог повів мене подорожувати з дому батька мого, то я сказав їй: зроби зі мною цю милість, у яке не прийдемо ми місце, скрізь говори про мене: це брат мій.","І взяв Авимелех [срібла тисячу сиклів і] дрібної та великої худоби, і рабів і рабинь, і дав Аврааму; і повернув йому Сарру, дружину його.","І сказав Авимелех [Аврааму]: ось, земля моя перед тобою; живи, де тобі завгодно.","І Саррі сказав: ось, я дав братові твоєму тисячу сиклів срібла; ось, це тобі покривало для очей перед усіма, хто з тобою, і перед усіма ти виправдана.","І помолився Авраам Богові, і зцілив Бог Авимелеха, і дружину його, і рабинь його, і вони стали народжувати;","бо закрив Господь усяку утробу в домі Авимелеха за Сарру, дружину Авраамову."],"x":{"1":"0.12.9|0.13.18|75.11.9","2":"0.12.13|0.26.1:9","3":"25.104.14","4":"0.18.25","5":"25.25.6","7":"25.104.15|0.23.6|24.42.8","9":"0.26.10","12":"0.12.13"}},{"v":["І споглянув Господь на Сарру, як сказав; і зробив Господь Саррі, як говорив.","Сарра зачала і народила Аврааму сина у старості його в час, про який говорив йому Бог;","і нарік Авраам ім’я сину своєму, який народився від нього, якого народила йому Сарра, Ісаак;","і обрізав Авраам Ісаака, сина свого, у восьмий день, як заповідав Бог.","Авраам був ста років, коли народився в нього Ісаак, син його.","І сказала Сарра: сміх зробив мені Бог; хто не почує про мене, розсміється.","І сказала: хто сказав би Аврааму: Сарра буде годувати дітей грудьми? бо в старості його я народила сина.","Дитя виросло й було відлучене від грудей; і Авраам зробив велику вечерю у той день, коли Ісаак [син його] був відлучений від грудей.","І побачила Сарра, що син Агарі єгиптянки, якого вона народила Аврааму, насміхається [над її сином, Ісааком],","і сказала Аврааму: вижени цю рабиню і сина її, тому що не успадкує син рабині цієї із сином моїм Ісааком.","І здалося це Аврааму дуже неприємним заради сина його [Ізмаїла].","Але Бог сказав Аврааму: не засмучуйся заради отрока і рабині твоєї; в усьому, що скаже тобі Сарра, слухайся голосу її, бо в Ісаакові наречеться тобі сíм’я;","і від сина рабині Я породжу [великий] народ, тому що він сíм’я твоє.","Авраам встав рано-вранці, й узяв хліба і міх води, і дав Агарі, поклавши їй на плечі, й отрока, і відпустив її. Вона пішла, і заблукала у пустелі Вирсавії;","і не стало води в міху, і вона залишила отрока під одним кущем","і пішла, сіла віддалік на відстані одного пострілу з лука. Бо вона сказала: не хочу бачити смерти дитини. І вона сіла [на відстані] навпроти [нього], і підняла крик, і плакала;","і почув Бог голос отрока [звідти, де він був]; і ангел Божий з неба воззвав до Агарі і сказав їй: що з тобою, Агар? не бійся; Бог почув голос отрока звідти, де він знаходиться;","встань, підніми отрока і візьми його за руку, тому що Я породжу від нього великий народ.","І Бог відкрив очі її, і вона побачила колодязь с водою [живою], і пішла, наповнила міх водою і напоїла отрока.","І Бог був з отроком; і він виріс, і став жити в пустелі, і став стрільцем з лука.","Він жив у пустелі Фаран; і мати його взяла із землі Єгипетської.","І було в той час, Авимелех з [Ахузафом, що водив наречену, і] Фихолом, воєначальником своїм, сказав Аврааму: з тобою Бог у всьому, що ти не робив би;","і тепер поклянися мені тут Богом, що ти не скривдиш ні мене, ні сина мого, ні онука мого; і як я добре чинив з тобою, так і ти будеш чинити зі мною і землею, в якій ти гостюєш.","І сказав Авраам: я клянуся.","І Авраам докоряв Авимелеху за колодязь з водою, що його відібрали раби Авимелехові.","Авимелех же сказав [йому]: не знаю, хто це зробив, і ти не сказав мені; я навіть і не чув про те донині.","І взяв Авраам дрібної і великої худоби і дав Авимелеху, і вони обидва уклали союз.","І поставив Авраам сім агниць з отари дрібної худоби окремо.","Авимелех же сказав Аврааму: для чого тут ці сім агниць [з отари овець], яких ти поставив окремо?","[Авраам] сказав: сім агниць оцих візьми від руки моєї, щоб вони були мені свідченням, що я викопав цей колодязь.","Тому і назвав він це місце: Вирсавія, тому що тут вони обоє клялися","й уклали союз у Вирсавії. І встав Авимелех, і [Ахузаф, нареченопровідник його, і] Фихол, воєначальник його, і повернулися в землю Филистимську.","І насадив [Авраам] біля Вирсавії гай і призвав там ім’я Господа, Бога вічного.","І жив Авраам у землі Филистимській, як мандрівник, дні довгі."],"x":{"1":"0.17.19|0.18.10|75.11.11","2":"65.4.22","3":"50.1.2","4":"54.7.8|0.17.10-12","10":"65.4.30","11":"0.17.18","12":"62.9.7|75.11.18","13":"0.16.10|0.17.20|0.25.16","18":"0.17.20","21":"0.14.6","22":"0.20.2","23":"0.26.11","25":"0.26.15:18","31":"0.26.33|5.15.28|5.19.2","33":"0.13.4|31.57.15"}},{"v":["І було, після цих подій Бог спокушав Авраама і сказав йому: Аврааме! Він сказав: ось я.","Бог сказав: візьми сина твого, єдиного твого, якого ти любиш, Ісаака; і піди в землю Моріа і там принеси його у всепалення на одній з гір, про яку Я скажу тобі.","Авраам устав рано-вранці, осідлав осла свого, взяв з собою двох слуг своїх та Ісаака, сина свого; наколов дров для всепалення і, вставши, пішов на місце, про яке сказав йому Бог.","На третій день Авраам звів очі свої, і побачив те місце здалеку.","І сказав Авраам слугам своїм: ви залиштеся тут з ослом, а я і син підемо туди і поклонимося, і повернемося до вас.","І взяв Авраам дрова для всепалення, і поклав на Ісаака, сина свого; взяв у руки вогонь і ніж, і пішли обоє разом.","І почав Ісаак говорити Аврааму, батькові своєму, і сказав: батьку мій! Він відповів: ось я, сину мій. Він сказав: ось вогонь і дрова, де ж агнець для всепалення?","Авраам сказав: Бог угледить Собі агнця для всепалення, сину мій. І йшли далі обоє разом.","І пройшли на місце, про яке сказав йому Бог; і влаштував там Авраам жертовник, розклав дрова і, зв’язавши сина свого Ісаака, поклав його на жертовник поверх дров.","І простяг Авраам руку свою і взяв ніж, щоб заколоти сина свого.","Але ангел Господній воззвав до нього з неба і сказав: Аврааме! Аврааме! Він сказав: ось я.","Ангел сказав: не здіймай руки твоєї на отрока і не роби з ним нічого, тому що тепер Я знаю, що боїшся ти Бога і не пожалів сина твого, єдиного твого, для Мене.","І підвів Авраам очі свої і побачив: і ось, позаду баран, що заплутався у гущавині рогами своїми. Авраам пішов, узяв барана і приніс його у всепалення замість [Ісаака], сина свого.","І нарік Авраам ім’я місцю тому: Єгова-іре*. Тому і нині говориться: на горі Єгови угледиться.","І вдруге воззвав до Авраама ангел Господній з неба","і сказав: Собою клянуся, говорить Господь, що, оскільки ти зробив це діло, і не пожалів сина твого, єдиного твого, [для Мене,]","то Я благословляючи благословлю тебе і примножуючи примножу сíм’я твоє, як зірки небесні і як пісок на березі моря; й оволодіє сíм’я твоє містами ворогів своїх;","і благословляться у сімені твоєму всі народи землі за те, що ти послухався голосу Мого.","І повернувся Авраам до слуг своїх, і встали і пішли разом у Вирсавію; і жив Авраам у Вирсавії.","Після цих подій Авраама сповістили, сказавши: ось, і Милка народила Нахору, братові твоєму, синів:","Уца, первістка його, Вуза, брата його, Кемуїла, батька Арамового,","Кеседа, Хазо, Пилдаша, Ідлафа і Вафуїла;","від Вафуїла народилася Ревекка. Вісьмох цих [синів] народила Милка Нахору, брату Авраамовому;","і наложниця його, на ім’я Реума, також народила Теваха, Гахама, Тахаша і Мааху."],"x":{"1":"75.11.17","16":"25.104.9|30.44.21|21.2.52|52.1.73|75.6.13","18":"0.12.3|0.18.18|0.26.4|30.44.22|54.3.25|65.3.8:16|25.71.17"},"n":{"14":["Господь угледить."]}},{"v":["Життя Сарриного було сто двадцять сім років: ось роки життя Сарриного;","і померла Сарра у Кириаф-Арбі, [який у долині,] що нині Хеврон, у землі Ханаанській. І прийшов Авраам ридати за Саррою й оплакувати її.","І відійшов Авраам від померлої своєї, і говорив до синів Хетових, і сказав:","я у вас подорожній і поселенець; дайте мені у власність місце для гробу між вами, щоб мені померлу мою поховати від очей моїх.","Сини Хета відповіли Аврааму і сказали йому:","послухай нас, господарю наш; ти князь Божий посеред нас; у кращому з наших погребальних місць поховай померлу твою; ніхто з нас не відмовить тобі в погребальному місці, для поховання [в ньому] померлої твоєї.","Авраам встав і поклонився народу землі тієї, синам Хетовим;","і говорив до них [Авраам] і сказав: якщо ви згодні, щоб я поховав померлу мою, то послухайте мене, попросіть за мене Ефрона, сина Цохарового,","щоб він віддав мені печеру Махпелу, що у нього на кінці поля його, щоб за задовільну ціну віддав її мені посеред вас, у власність для поховання.","Ефрон же сидів серед синів Хетових; і відповів Ефрон хеттеянин Аврааму, щоб чули сини Хета, і всі, що входили у ворота міста його, і сказав:","ні, господарю мій, послухай мене: я даю тобі поле і печеру, що на ньому, даю тобі, перед очима синів народу мого дарую тобі її, поховай померлу твою.","Авраам поклонився народу землі тієї","і промовив до Ефрона, щоб чув [увесь] народ землі тієї, і сказав: якщо послухаєш, я даю тобі за поле срібло; візьми у мене, і я поховаю там померлу мою.","Ефрон відповів Аврааму і сказав йому:","господарю мій! послухай мене: земля коштує чотириста сиклів срібла; для мене і для тебе що це? поховай померлу твою.","Авраам вислухав Ефрона; і відважив Авраам Ефрону срібла, скільки він оголосив так, щоб чули сини Хетові, чотириста сиклів срібла, яке ходить серед купців.","І стало поле Ефронове, що при Махпелі, навпроти Мамре, поле і печера, що на ньому, і всі дерева, що на полі, в усіх межах його,","володінням Авраамовим перед очима синів Хета, усіх, що входять у ворота міста його.","Після цього Авраам поховав Сарру, дружину свою, у печері поля в Махпелі, навпроти Мамре, що нині Хеврон, у землі Ханаанській.","Так дістались Аврааму від синів Хетових поле і печера, що на ньому, у власність для поховання."],"x":{"16":"0.25.10|0.50.13|5.24.3|54.7.16"}},{"v":["Авраам був уже старий і в літах похилих. Господь благословив Авраама усім.","І сказав Авраам рабові своєму, старшому в домі його, який управляв усім, що у нього було: поклади руку твою під стегно моє","і клянися мені Господом, Богом неба і Богом землі, що ти не візьмеш синові моєму [Ісааку] дружини з дочок хананеїв, серед яких я живу,","але підеш у землю мою, на батьківщину мою [і до племені мого], і візьмеш [звідти] дружину синові моєму Ісааку.","Раб сказав йому: можливо, не захоче жінка йти зі мною в цю землю, чи повинен я повернути сина твого в землю, з якої ти вийшов?","Авраам сказав йому: бережися, не повертай сина мого туди;","Господь, Бог неба [і Бог землі], Який взяв мене з дому батька мого і з землі народження мого, Який говорив мені і Який клявся мені, говорячи: [тобі і] нащадкам твоїм дам цю землю, — Він пошле ангела Свого перед тобою, і ти візьмеш дружину синові моєму [Ісааку] звідти;","якщо ж не захоче жінка йти з тобою [у землю цю], ти будеш вільний від цієї клятви моєї; тільки сина мого не повертай туди.","І поклав раб руку свою під стегно Авраама, господаря свого, і поклявся йому в цьому.","І взяв раб з верблюдів господаря свого десять верблюдів і пішов. У руках у нього були також різні скарби господаря його. Він встав і пішов у Месопотамію, в місто Нахора,","і зупинив верблюдів за містом, біля колодязя води, надвечір, у той час, коли виходять жінки брати [воду],","і сказав: Господи, Боже господаря мого Авраама! пошли її сьогодні назустріч мені і вчини милість з господарем моїм Авраамом;","ось, я стою біля джерела води, і дочки жителів міста виходять черпати воду;","і дівчина, якій я скажу: нахили глечик твій, я нап’юся, і яка скаже [мені]: пий, я й верблюдам твоїм дам пити, [поки не нап’ються,] — ось та, яку Ти призначив рабу Твоєму Ісааку; і з того довідаюсь я, що Ти твориш милість з господарем моїм [Авраамом].","Ще не перестав він говорити [у розумі своєму], і ось, вийшла Ревекка, яка народилася від Вафуїла, сина Милки, дружини Нахора, брата Авраамового, і глечик її на плечі її;","дівчина була прекрасна на вигляд, діва, якої не пізнав чоловік. Вона зійшла до джерела, наповнила глечик свій і пішла нагору.","І побіг раб назустріч їй і сказав: дай мені напитися трохи із глечика твого.","Вона сказала: пий, господарю мій. І негайно спустила глечик свій на руку свою і напоїла його.","І, коли напоїла його, сказала: я наберу води також і для верблюдів твоїх, доки не нап’ються [усі].","І негайно вилила воду із глечика свого в поїлку і побігла знову до колодязя почерпнути [води], і набрала для усіх верблюдів його.","Чоловік той дивився на неї зі здивуванням у мовчанні, бажаючи зрозуміти, чи благословив Господь путь його, чи ні.","Коли верблюди перестали пити, тоді чоловік той узяв золоту сергу, вагою півсикля, і два зап’ястя на руки їй, вагою в десять сиклів золота;","[і запитав її] і сказав: чия ти дочка? скажи мені, чи є в домі батька твого місце, щоб нам переночувати?","Вона сказала йому: я дочка Вафуїла, сина Милки, якого вона народила Нахору.","І ще сказала йому: у нас багато соломи і корму, і є місце для ночівлі.","І схилився чоловік той і поклонився Господу,","і сказав: благословенний Господь Бог господаря мого Авраама, Який не залишив господаря мого милістю Своєю й істиною Своєю! Господь прямою дорогою привів мене до дому брата господаря мого.","Дівчина побігла і розповіла про це в домі матері своїй.","У Ревекки був брат, на ім’я Лаван. Лаван вибіг до тієї людини, до джерела.","І коли він побачив сергу і зап’ястя на руках у сестри своєї і почув слова Ревекки, сестри своєї, яка говорила: так говорив зі мною той чоловік, — то прийшов до чоловіка цього, і ось, він стоїть з верблюдами біля джерела;","і сказав [йому]: ввійди, благословенний Господом; чому ти стоїш ззовні? я приготував дім і місце для верблюдів.","І ввійшов чоловік. Лаван розсідлав верблюдів і дав соломи і корму верблюдам, і води, щоб умити ноги йому і людям, які були з ним;","і запропонована була йому їжа; але він сказав: не буду їсти, поки не скажу про діло своє. І сказали: говори.","Він сказав: я раб Авраамів;","Господь дуже благословив господаря мого, і він став великим: Він дав йому овець і волів, срібло і золото, рабів і рабинь, верблюдів і ослів;","Сарра, дружина господаря мого, вже будучи старою, народила господарю моєму [одного] сина, якому він віддав усе, що в нього;","і взяв з мене клятву господар мій, сказавши: не бери дружини синові моєму з дочок хананеїв, у землі яких я живу,","а піди в дім батька мого і до родичів моїх, і візьмеш [звідти] дружину синові моєму.","Я сказав господарю моєму: можливо, не піде жінка зі мною.","Він сказав мені: Господь [Бог], перед лицем Якого я ходжу, пошле з тобою ангела Свого і благовлаштує путь твою, і візьмеш дружину сину моєму з рідних моїх і з дому батька мого;","тоді будеш ти вільним від клятви моєї, коли сходиш до родичів моїх; і якщо вони не дадуть тобі, то будеш вільним від клятви моєї.","І прийшов я нині до джерела, і сказав: Господи, Боже господаря мого Авраама! Якщо Ти благовлаштуєш путь, яку я звершую,","то ось, я стою біля джерела води, [і дочки жителів міста виходять черпати воду,] і дівчина, яка вийде черпати, і якій я скажу: дай мені напитися трохи з глечика твого,","і яка скаже мені: і ти пий, і верблюдам твоїм я начерпаю, ось дружина, яку Господь призначив синові господаря мого [рабу Своєму Ісааку; і з цього дізнаюсь я, що Ти чиниш милість господарю моєму Аврааму].","Ще не перестав я говорити в розумі моєму, і ось, вийшла Ревекка, і глечик її на плечі її, і зійшла до джерела і зачерпнула [води]; і я сказав їй: напої мене.","Вона негайно спустила з себе глечик свій [на руку свою] і сказала: пий, і верблюдів твоїх я напою. І я пив, і верблюдів [моїх] вона напоїла.","Я запитав її і сказав: чия ти дочка? [скажи мені]. Вона сказала: дочка Вафуїла, сина Нахорового, якого народила йому Милка. І дав я серги їй і зап’ястя на руки її.","І схилився я і поклонився Господу, і благословив Господа, Бога господаря мого Авраама, Який прямою дорогою привів мене, щоб узяти дочку брата господаря мого за сина його.","І нині скажіть мені: чи маєте ви намір зробити милість і правду господарю моєму чи ні? скажіть мені, і я обернуся праворуч, або ліворуч.","І відповіли Лаван і Вафуїл і сказали: від Господа прийшла ця справа; ми не можемо сказати тобі всупереч ні поганого, ні доброго;","ось Ревекка перед тобою; візьми [її] і піди; нехай буде вона дружиною синові господаря твого, як сказав Господь.","Коли раб Авраамів почув слова їхні, то поклонився Господу до землі.","І вийняв раб срібні і золоті речі й одяг і дав Ревецці; також і братові її і матері її дав багаті подарунки.","І їли і пили він і люди, які були з ним, і переночували. Коли ж встали вранці, то він сказав: відпустіть мене [і я піду] до господаря мого.","Але брат її і мати її сказали: нехай побуде з нами дівчина днів хоч десять, потім підеш.","Він сказав їм: не затримуйте мене, тому що Господь благовлаштував путь мою; відпустіть мене, і я піду до господаря мого.","Вони сказали: покличемо дівчину і запитаємо, що вона скаже.","І покликали Ревекку і сказали їй: чи підеш з цим чоловіком? Вона сказала: піду.","І відпустили Ревекку, сестру свою, і годівницю її, і раба Авраамового, і людей його.","І благословили Ревекку і сказали їй: сестро наша! нехай народяться від тебе тисячі тисяч, і нехай володіють нащадки твої оселями ворогів твоїх!","І встала Ревекка і служниці її, і сіли на верблюдів, і поїхали за тим чоловіком. І раб узяв Ревекку і пішов.","А Ісаак прийшов з Беер-лахай-рої, бо жив він у землі полуденній.","Коли настав вечір, Ісаак вийшов у поле пороздумувати, і звів очі свої, і побачив: ось, йдуть верблюди.","Ревекка глянула, і побачила Ісаака, і спустилася з верблюда.","І сказала рабові: хто ця людина, яка йде по полю назустріч нам? Раб сказав: це господар мій. І вона взяла покривало і покрилася.","Раб же розповів Ісааку усе, що зробив.","І ввів її Ісаак у шатро Сарри, матері своєї, і взяв Ревекку, і вона стала йому дружиною, і він полюбив її; й утішився Ісаак у печалі за [Саррою,] матір’ю своєю."],"x":{"1":"0.21.5","2":"0.47.29","3":"0.27.46","7":"0.12.7|0.13.15|0.15.18|0.26.3-4","15":"0.22.23","17":"53.4.7","36":"0.21.2|0.25.5","40":"0.17.1","42":"0.24.12","62":"0.16.14","65":"56.3.6","67":"0.23.2"}},{"v":["І взяв Авраам ще дружину, на ім’я Хеттура.","Вона народила йому Зимрана, Іокшана, Медана, Мадіана, Ішбака і Шуаха.","Іокшан породив Шеву, [Фемана] і Дедана. Сини Дедана були: [Рагуїл, Навдеїл,] Ашурим, Летушим і Леюмим.","Сини Мадіана: Ефа, Ефер, Ханох, Авида й Елдага. Усі ці — сини Хеттури.","І віддав Авраам усе, що було в нього, Ісааку [синові своєму],","а синам наложниць, які були у Авраама, дав Авраам подарунки і відіслав їх від Ісаака, сина свого, ще за життя свого, на схід, у землю східну.","Днів життя Авраамового, які він прожив, було сто сімдесят п’ять років;","і упокоївся Авраам, і помер у старості добрій, старий і насичений [життям], і приєднався до народу свого.","І поховали його Ісаак та Ізмаїл, сини його, у печері Махпеле, на полі Ефрона, сина Цохара, хеттеянина, що напроти Мамре,","на полі [і в печері], які Авраам придбав від синів Хетових. Там поховані Авраам і Сарра, дружина його.","Після смерти Авраама Бог благословив Ісаака, сина його. Ісаак жив при Беер-лахай-рої.","Ось родовід Ізмаїла, сина Авраамового, якого народила Аврааму Агар єгиптянка, служниця Саррина;","і ось імена синів Ізмаїлових, імена їх за родоводом їх: первісток Ізмаїлів Наваїоф, за ним Кедар, Адбеєл, Мивсам,","Мишма, Дума, Масса,","Хадад, Фема, Ієтур, Нафиш і Кедма.","Ці є сини Ізмаїлові, і це імена їхні, у селищах їхніх, у кочовищах їхніх. Це дванадцять князів племен їхніх.","Років же життя Ізмаїлового було сто тридцять сім років; і упокоївся він, і помер, і приєднався до народу свого.","Вони жили від Хавили до Сура, що перед Єгиптом, як ідеш до Ассирії. Вони оселилися перед лицем усіх братів своїх.","Ось родовід Ісаака, сина Авраамового. Авраам породив Ісаака.","Ісаак був сорока років, коли він узяв собі за дружину Ревекку, дочку Вафуїла арамеянина з Месопотамії, сестру Лавана арамеянина.","І молився Ісаак Господу за [Ревекку] дружину свою, тому що вона була неплідна; і Господь почув його, і зачала Ревекка, дружина його.","Сини в утробі її почали битися, і вона сказала: якщо так буде, то для чого мені це? І пішла запитати Господа.","Господь сказав їй: два племені в утробі твоїй, і два різних народи вийдуть з утроби твоєї; один народ стане сильнішим за інший, і більший буде служити меншому.","І настав час народити їй: і ось близнюки в утробі її.","Першим вийшов червоний, весь, як шкіра, кошлатий; і нарекли йому ім’я Ісав.","Потім вийшов брат його, тримаючись рукою своєю за п’яту Ісава; і наречено йому ім’я Яків. Ісаак же був шістдесяти років, коли вони народилися [від Ревекки].","Діти виросли, і став Ісав людиною вправною у звіроловстві, людиною полів; а Яків людиною лагідною, що живе у наметах.","Ісаак любив Ісава, тому що здобич його була за смаком його, а Ревекка любила Якова.","І зварив Яків страву; а Ісав прийшов з поля втомленим.","І сказав Ісав Якову: дай мені поїсти червоного, червоного цього, тому що я втомився. Від цього дано йому прізвисько: Єдом.","Але Яків сказав [Ісаву]: продай мені зараз же своє первородство.","Ісав сказав: ось, я вмираю, що мені з цього первородства?","Яків сказав [йому]: поклянися мені зараз же. Він поклявся йому, і продав [Ісав] первородство своє Якову.","І дав Яків Ісаву хліби і страви із сочевиці; і він їв і пив, і встав і пішов; і зневажив Ісав первородство."],"x":{"2":"12.1.32-33","5":"0.15.4|0.21.10|0.24.36","8":"0.35.29|75.12.23","9":"0.49.30-31","10":"0.23.16","11":"0.16.14|0.24.62","12":"0.16.15","13":"12.1.29","15":"24.6.19","19":"0.21.2|12.1.34|50.1.2","23":"62.9.10-12|49.1.2","25":"0.27.11","26":"38.12.3|54.7.8","30":"0.36.1:19","33":"75.12.16|0.27.36"}},{"v":["Був голод у землі, більший за колишній голод, що був у дні Авраама; і пішов Ісаак до Авимелеха, царя Филистимського, у Герар.","Господь явився йому і сказав: не ходи в Єгипет; живи в землі, про яку Я скажу тобі,","подорожуй по цій землі, і Я буду з тобою і благословлю тебе, бо тобі і нащадкам твоїм дам усі землі ці і виконаю клятву [Мою], якою Я клявся Аврааму, батькові твоєму;","примножу нащадків твоїх, як зірки небесні, і дам нащадкам твоїм усі землі ці; благословляться в сімені твоєму всі народи земні,","за те, що Авраам [батько твій] послухався голосу Мого і виконував, що Мною заповідано було виконувати: повеління Мої, постанови Мої і закони Мої.","Ісаак оселився в Герарі.","Жителі місця того запитали про [Ревекку] дружину його, і він сказав: це сестра моя; тому що боявся сказати: дружина моя, щоб не вбили мене, думав він, жителі місця цього, за Ревекку, тому що вона прекрасна на вигляд.","Але коли вже багато часу він там прожив, Авимелех, цар Филистимський, подивившись у вікно, побачив, що Ісаак грається з Ревеккою, дружиною своєю.","І покликав Авимелех Ісаака і сказав: ось, це дружина твоя; як же ти сказав: вона сестра моя? Ісаак сказав йому: тому що я думав, не вмерти б мені заради неї.","Але Авимелех сказав [йому]: навіщо ти зробив це з нами? ледве один з народу [мого] не з’єднався з дружиною твоєю, і ти ввів би нас у гріх.","І дав Авимелех повеління всьому народові, сказавши: хто доторкнеться до цього чоловіка і до дружини його, той відданий буде на смерть.","І посіяв Ісаак на землі тій і одержав у той рік ячменю у стократ: так благословив його Господь.","І став великим чоловік цей і звеличувався більше і більше до того, що став дуже великим.","У нього були стада дрібної і отари великої худоби і безліч орних земель, і филистимляни почали заздрити йому.","І всі колодязі, що їх викопали раби батька його за життя батька його Авраама, филистимляни завалили і засипали землею.","І Авимелех сказав Ісааку: відійди від нас, бо ти зробився набагато сильнішим за нас.","І Ісаак відійшов звідти, і розташувався наметами в долині Герарській, і оселився там.","І знову викопав Ісаак колодязі води, що були викопані у дні Авраама, батька його, і які завалили филистимляни після смерти Авраама [батька його]; і назвав їх тими ж іменами, якими назвав їх [Авраам,] батько його.","І копали раби Ісаакові в долині [Герарській] і знайшли там колодязь води живої.","І сперечалися пастухи герарські з пастухами Ісаака, говорячи: наша вода. І він нарік колодязю ім’я: Есек, тому що сперечалися з ним.","[Коли рушив звідти Ісаак,] викопали інший колодязь; сперечалися також і через нього; і він нарік йому ім’я: Ситна.","І він рушив звідти і викопав інший колодязь, про який уже не сперечалися, і нарік йому ім’я: Реховоф, тому що, сказав він, тепер Господь дав нам просторе місце, і ми розмножимося на землі.","Звідти перейшов він у Вирсавію.","І в ту ніч явився йому Господь і сказав: Я Бог Авраама, батька твого; не бійся, бо Я з тобою; і благословлю тебе і розмножу нащадків твоїх, заради [батька твого] Авраама, раба Мого.","І він влаштував там жертовник і закликав ім’я Господнє. І розкинув там намет свій, і викопали там раби Ісаакові колодязь, [у долині Герарській].","Прийшов до нього з Герара Авимелех і Ахузаф, друг його, і Фихол, воєначальник його.","Ісаак сказав їм: для чого ви прийшли до мене, коли ви зненавиділи мене і вислали мене від себе?","Вони сказали: ми ясно побачили, що Господь з тобою, і тому ми сказали: поставимо між нами і тобою клятву й укладемо з тобою союз,","щоб ти не чинив нам зла, як і ми не доторкнулися до тебе, а робили тобі тільки добре і відпустили тебе з миром; тепер ти благословенний Господом.","Він зробив їм вечерю, і вони їли і пили.","І, вставши рано-вранці, поклялись один одному; і відпустив їх Ісаак, і вони пішли від нього з миром.","У той самий день прийшли раби Ісаакові і сповістили його про колодязь, який копали вони, і сказали йому: ми знайшли воду.","І він назвав його: Шива. Тому ім’я місту тому Беершива [Вирсавія] до цього дня.","І був Ісав сорока років, і взяв собі за дружин Ієгудифу, дочку Беера хеттеянина, і Васемафу, дочку Елона хеттеянина;","і вони були тягарем для Ісаака і Ревекки."],"x":{"3":"0.12.7|0.13.15|0.15.7:18","4":"0.12.3|0.18.18|0.22.18|0.28.13-14|25.71.17","10":"0.20.9","23":"0.46.1","24":"0.17.7|31.41.10|31.43.1","26":"0.21.22:32"}},{"v":["Коли Ісаак постарів і притупився зір очей його, він покликав старшого сина свого Ісава і сказав йому: сину мій! Той сказав йому: ось я.","[Ісаак] сказав: ось, я постарів; не знаю дня смерти моєї;","візьми тепер знаряддя твої, сагайдак твій і лук твій, піди в поле, і налови мені дичини,","і приготуй мені страву, яку я люблю, і принеси мені її, щоб благословила тебе душа моя, раніше ніж я помру.","Ревекка чула, коли Ісаак говорив синові своєму Ісаву. І пішов Ісав у поле дістати і принести дичини;","а Ревекка сказала [молодшому] синові своєму Якову: ось, я чула, як батько твій говорив братові твоєму Ісаву:","принеси мені дичини і приготуй мені страву; я поїм і благословлю тебе перед лицем Господнім, перед смертю моєю.","Тепер, сину мій, послухайся слів моїх у тому, що я накажу тобі:","піди в стадо і візьми мені звідти двох козенят [молодих] гарних, і я приготую з них батьку твоєму страву, яку він любить,","а ти принесеш батькові твоєму, і він поїсть, щоб благословити тебе перед смертю своєю.","Яків сказав Ревецці, матері своїй: Ісав, брат мій, людина кошлата, а я людина гладенька;","може статися, обмацає мене батько мій, і я буду в очах його обманщиком і наведу на себе прокляття, а не благословення.","Мати його сказала йому: на мені нехай буде прокляття твоє, сину мій, тільки послухайся слів моїх і піди, принеси мені.","Він пішов, і взяв, і приніс матері своїй; і мати його приготувала страву, яку любив батько його.","І взяла Ревекка багатий одяг старшого сина свого Ісава, що був у неї в домі, й одягла [в нього] молодшого сина свого Якова;","а руки його і гладеньку шию його обклала шкурою козеняти;","і дала страву і хліб, які вона приготувала, у руки Якову, синові своєму.","Він увійшов до батька свого і сказав: батьку мій! Той сказав: ось я; хто ти, сину мій?","Яків сказав батькові своєму: я Ісав, первісток твій; я зробив, як ти сказав мені; встань, сядь і поїж дичини моєї, щоб благословила мене душа твоя.","І сказав Ісаак синові своєму: як це ти так швидко знайшов, сину мій? Він сказав: тому що Господь Бог твій послав мені назустріч.","І сказав Ісаак Якову: підійди [до мене], я обмацаю тебе, сину мій, чи ти син мій Ісав, чи ні?","Яків підійшов до Ісаака, батька свого, і він обмацав його і сказав: голос, голос Якова; а руки, руки Ісавові.","І не впізнав його, тому що руки його були, як руки Ісава, брата його, волохаті; і благословив його","і сказав: чи ти син мій Ісав? Він відповів: я.","Ісаак сказав: подай мені, я поїм дичини сина мого, щоб благословила тебе душа моя. Яків подав йому, і він їв; приніс йому і вино, і він пив.","Ісаак, батько його, сказав йому: підійди [до мене], поцілуй мене, сину мій.","Він підійшов і поцілував його. І відчув Ісаак запах від одягу його і благословив його і сказав: ось, запах від сина мого, як запах від поля [повного], яке благословив Господь;","нехай дасть тобі Бог від роси небесної і від багатства землі, і безліч хліба і вина;","нехай послужать тобі народи, і нехай поклоняться тобі племена; будь господарем над братами твоїми, і нехай поклоняться тобі сини матері твоєї; ті, що проклинають тебе, — прокляті; ті, що благословляють тебе, — благословенні!","Як тільки Ісаак благословив Якова [сина свого], і як тільки вийшов Яків від лиця Ісаака, батька свого, Ісав, брат його, прийшов з полювання свого.","Приготував і він страву, і приніс батькові своєму, і сказав батькові своєму: встань, батьку мій, і поїж дичини сина твого, щоб благословила мене душа твоя.","Ісаак же, батько його, сказав йому: хто ти? Він сказав: я син твій, первісток твій, Ісав.","І затремтів Ісаак дуже великим трепетом, і сказав: хто ж це, що дістав [мені] дичини і приніс мені, і я їв від усього, раніше ніж ти прийшов, і я благословив його? він і буде благословенний.","Ісав, вислухавши слова батька свого [Ісаака], підняв голосне і дуже гірке волання і сказав батькові своєму: батьку мій! благослови і мене.","Але він сказав [йому]: брат твій прийшов з хитрістю і взяв благословення твоє.","І сказав [Ісав]: чи не тому дано йому ім’я: Яків, що він запнув мене вже двічі? Він узяв первородство моє, і ось, тепер узяв благословення моє. І ще сказав [Ісав батькові своєму]: невже ти не залишив [і] мені благословення?","Ісаак відповів Ісаву: ось, я поставив його господарем над тобою і всіх братів його віддав йому в раби: обдарував його хлібом і вином; що ж я зроблю для тебе, сину мій?","Але Ісав сказав батькові своєму: невже, батьку мій, одне в тебе благословення? благослови і мене, батьку мій! І [оскільки Ісаак мовчав,] підняв Ісав голос свій і заплакав.","І відповів Ісаак, батько його, і сказав йому: ось, від багатства землі буде перебування твоє і від роси небесної звище;","і ти будеш жити мечем твоїм і будеш служити братові твоєму; прийде ж час, коли ти вчиниш опір і скинеш ярмо його з шиї твоєї.","І зненавидів Ісав Якова через благословення, яким благословив його батько його; і сказав Ісав у серці своїм: наближаються дні плачу за батьком моїм, і я вб’ю Якова, брата мого.","І переказані були Ревецці слова Ісава, старшого сина її; і вона послала, і покликала молодшого сина свого Якова, і сказала йому: ось, Ісав, брат твій, погрожує убити тебе;","і тепер, сину мій, послухайся слів моїх, встань, біжи [у Месопотамію] до Лавана, брата мого, у Харран,","і поживи в нього трохи часу, доки вгамується лють брата твого,","доки вгамується гнів брата твого на тебе, і він забуде, що ти зробив йому: тоді я пошлю і візьму тебе звідти; для чого мені в один день позбутися обох вас?","І сказала Ревекка Ісааку: я життю не рада від дочок хеттейських; якщо Яків візьме дружину з дочок хеттейських, які ці, з дочок цієї землі, то для чого мені і життя?"],"x":{"1":"0.48.10","27":"75.11.20","29":"3.22.6|3.24.9","34":"75.12.17","36":"0.25.33","38":"75.12.17","39":"75.11.20","40":"11.8.20|13.21.8","41":"41.1.10","46":"0.26.34-35"}},{"v":["І покликав Ісаак Якова і благословив його, і заповідав йому і сказав: не бери собі дружини з дочок ханаанських;","встань, піди в Месопотамію, в дім Вафуїла, батька матері твоєї, і візьми собі дружину звідти, з дочок Лавана, брата матері твоєї;","Бог же Всемогутній нехай благословить тебе, нехай розплодить тебе і нехай розмножить тебе, і нехай буде від тебе безліч народів,","і нехай дасть тобі благословення Авраама [батька мого], тобі і нащадкам твоїм з тобою, щоб тобі успадкувати землю подорожування твого, яку Бог дав Аврааму!","І відпустив Ісаак Якова, і він пішов у Месопотамію до Лавана, сина Вафуїла арамеянина, до брата Ревекки, матері Якова та Ісава.","Ісав побачив, що Ісаак благословив Якова і благословляючи послав його в Месопотамію, взяти собі дружину звідти, і заповів йому, сказавши: не бери дружини з дочок ханаанських;","і що Яків послухав батька свого і матері своєї і пішов у Месопотамію.","І побачив Ісав, що дочки ханаанські неугодні Ісааку, батькові його;","і пішов Ісав до Ізмаїла і взяв собі дружину Махалафу, дочку Ізмаїла, сина Авраамового, сестру Наваїофову, зверх інших дружин своїх.","Яків же вийшов із Вирсавії і пішов у Харан,","і прийшов на одне місце, і залишився там ночувати, тому що зайшло сонце. І взяв один із каменів того місця, і поклав собі під голову, і ліг на тому місці.","І побачив сон: ось, ліствиця стоїть на землі, а верх її торкається неба; і ось, ангели Божі піднімаються і сходять по ній.","І ось, Господь стоїть на ній і промовляє: Я Господь, Бог Авраама, отця твого, і Бог Ісаака; [не бійся]. Землю, на якій ти лежиш, Я дам тобі і твоєму потомству;","і буде потомство твоє — як пісок земний; і поширишся ти до моря і на схід, і на північ, і на південь, і благословляться у тобі й у твоєму потомстві всі племена земні;","і ось, Я з тобою, і збережу тебе всюди, куди ти не підеш; і поверну тебе в цю землю, бо Я не залишу тебе, доки не виконаю того, що Я сказав тобі.","Яків прокинувся від сну свого і сказав: істинно Господь присутній на цьому місці; а я не знав!","І убоявся він і сказав: яке страшне це місце! це не що інше, як дім Божий, це врата небесні.","І встав Яків рано-вранці, і взяв камінь, який поклав собі під голову, і поставив його пам’ятником, і полив єлей на верхівку його.","І нарік [Яків] ім’я місцю тому: Вефиль*, а раніше ім’я того міста було: Луз.","І дав Яків обітницю, сказавши: якщо [Господь] Бог буде зі мною і збереже мене в путі цій, у яку я йду, і дасть мені хліб їсти й одяг одягнутися,","і я у мирі повернусь у дім батька мого, і буде Господь моїм Богом, —","то цей камінь, який я поставив пам’ятником, буде [у мене] домом Божим; і з усього, що Ти, Боже, даруєш мені, я дам Тобі десяту частину."],"x":{"1":"0.24.3","2":"0.22.23","5":"38.12.12","6":"0.26.34","9":"0.25.13","10":"0.26.23|0.27.43","11":"0.35.1|0.48.3","12":"53.1.51","13":"0.35.1:7|0.48.3|30.44.25","14":"4.12.20|4.19.8|0.26.4","15":"31.43.2","17":"1.3.5|5.5.15","18":"0.31.13","19":"0.35.6","20":"71.6.8","22":"0.35.7"},"n":{"19":["Дім Божий."]}},{"v":["І встав Яків і пішов у землю синів сходу [до Лавана, сина Вафуїла арамеянина, до брата Ревекки, матері Якова та Ісава].","І побачив: ось, на полі колодязь, і там три отари дрібної худоби, що лежала біля нього, тому що із того колодязя напували отари. Над отвором колодязя був великий камінь.","Коли збиралися туди всі отари, відвалювали камінь від отвору колодязя і напували овець; потім знову клали камінь на своє місце, на отвір колодязя.","Яків сказав їм [пастухам]: брати мої! звідки ви? Вони сказали: ми з Харрана.","Він сказав їм: чи знаєте ви Лавана, сина Нахорового? Вони сказали: знаємо.","Він ще сказав їм: чи здоровий він? Вони сказали: здоровий; і ось, Рахиль, дочка його, йде з вівцями.","І сказав [Яків]: ось, день ще довгий; не час збирати худобу; напоїть овець і йдіть, пасіть.","Вони сказали: не можемо, поки не зберуться всі отари, і не відвалять каменя від отвору колодязя; тоді будемо ми поїти овець.","Ще він говорив з ними, як прийшла Рахиль [дочка Лавана] з дрібною худобою батька свого, бо вона пасла [дрібну худобу батька свого].","Коли Яків побачив Рахиль, дочку Лавана, брата матері своєї, і овець Лавана, брата матері своєї, то підійшов Яків, відвалив камінь від отвору колодязя і напоїв овець Лавана, брата матері своєї.","І поцілував Яків Рахиль і підніс голос свій і заплакав.","І сказав Яків Рахилі, що він родич батька її і що він син Ревекки. А вона побігла і сказала батьку своєму [все це].","Лаван, почувши про Якова, сина сестри своєї, вибіг йому назустріч, обійняв його і поцілував його, і ввів його в дім свій; і він розповів Лавану про все це.","Лаван же сказав йому: дійсно ти кость моя і плоть моя. І жив у нього Яків цілий місяць.","І Лаван сказав Якову: невже ти задарма будеш служити мені, тому що ти родич? скажи мені, що заплатити тобі?","У Лавана ж було дві дочки; ім’я старшої: Лія; ім’я молодшої: Рахиль.","Лія була слабка на очі, а Рахиль була красива станом і красива лицем.","Яків полюбив Рахиль і сказав: я буду служити тобі сім років за Рахиль, молодшу дочку твою.","Лаван сказав [йому]: краще віддати мені її за тебе, ніж віддати її за іншого кого; живи в мене.","І служив Яків за Рахиль сім років; і вони видалися йому за кілька днів, тому що він любив її.","І сказав Яків Лавану: дай дружину мою, тому що мені вже виповнився час, щоб увійти до неї.","Лаван скликав усіх людей того міста і зробив вечерю.","Увечері ж узяв [Лаван] дочку свою Лію і ввів її до нього; і ввійшов до неї [Яків].","І дав Лаван служницю свою Зелфу у служниці дочці своїй Лії.","Вранці ж виявилося, що це Лія. І [Яков] сказав Лавану: що це зробив ти зі мною? чи не за Рахиль я служив у тебе? навіщо ти обманув мене?","Лаван сказав: у нашому місці так не роблять, щоб молодшу видати раніше за старшу;","закінчи тиждень цією, потім дамо тобі і ту за службу, яку ти будеш виконувати в мене ще сім років інших.","Яків так і зробив і закінчив тиждень цією. І [Лаван] дав Рахиль, дочку свою, йому за дружину.","І дав Лаван служницю свою Валлу в служниці дочці своїй Рахилі.","[Яків] увійшов і до Рахилі, і любив Рахиль більше, ніж Лію; і служив у нього ще сім років інших.","Господь [Бог] побачив, що Лія була нелюбою, і відкрив утробу її, а Рахиль була неплідна.","Лія зачала і народила [Якову] сина, і нарекла йому ім’я: Рувим, тому що сказала вона: Господь споглянув на моє нещастя [і дав мені сина], бо тепер буде любити мене чоловік мій.","І зачала [Лія] знову і народила [Якову другого] сина, і сказала: Господь почув, що я нелюба, і дав мені і цього. І нарекла йому ім’я: Симеон.","І зачала ще і народила сина, і сказала: тепер-то прилучиться до мене чоловік мій, тому що я народила йому трьох синів. Від цього наречено йому ім’я: Левій.","І ще зачала і народила сина, і сказала: тепер-то я звеличу Господа. Тому нарекла йому ім’я Іуда. І перестала народжувати."],"x":{"13":"0.33.4|0.45.14","14":"6.9.2|9.5.1","20":"38.12.12","32":"0.35.23","35":"50.1.2"}},{"v":["І побачила Рахиль, що вона не народжує дітей Якову, і позаздрила Рахиль сестрі своїй, і сказала Якову: дай мені дітей, а якщо не так, я вмираю.","Яків розгнівався на Рахиль і сказав [їй]: хіба я Бог, Який не дав тобі плоду утроби?","Вона сказала: ось служниця моя Валла; увійди до неї; нехай вона народить на коліна мої, щоб і я мала дітей від неї.","І дала вона Валлу, служницю свою, за дружину йому; і ввійшов до неї Яків.","Валла [служниця Рахилина] зачала і народила Якову сина.","І сказала Рахиль: розсудив мене Бог, і почув голос мій, і дав мені сина. Тому нарекла йому ім’я: Дан.","І ще зачала і народила Валла, служниця Рахилина, другого сина Якову.","І сказала Рахиль: боротьбою сильною боролась я із сестрою моєю і перемогла. І нарекла йому ім’я: Неффалим.","Лія побачила, що перестала народжувати, і взяла служницю свою Зелфу, і дала її Якову за дружину, [і він увійшов до неї].","І Зелфа, служниця Ліїна, [зачала і] народила Якову сина.","І сказала Лія: додалося. І нарекла йому ім’я: Гад.","І [ще зачала] Зелфа, служниця Лії, [і] народила іншого сина Якову.","І сказала Лія: до блага мого, тому що блаженною будуть називати мене жінки. І нарекла йому ім’я: Асир.","Рувим пішов під час жнив пшениці, і знайшов мандрагорові яблука в полі, і приніс їх Лії, матері своїй. І Рахиль сказала Лії [сестрі своїй]: дай мені мандрагорів сина твого.","Але [Лія] сказала їй: невже мало тобі заволодіти чоловіком моїм, що ти домагаєшся і мандрагорів сина мого? Рахиль сказала: так нехай він ляже з тобою в цю ніч, за мандрагори сина твого.","Яків прийшов з поля ввечері, і Лія вийшла йому назустріч і сказала: увійди до мене [сьогодні], тому що я купила тебе за мандрагори сина мого. І ліг він з нею в ту ніч.","І почув Бог Лію, і вона зачала і народила Якову п’ятого сина.","І сказала Лія: Бог дав відплату мені за те, що я віддала служницю мою чоловікові моєму. І нарекла йому ім’я: Іссахар [що значить відплата].","І ще зачала Лія і народила Якову шостого сина.","І сказала Лія: Бог дав мені прекрасний дарунок; тепер буде жити в мене чоловік мій, тому що я народила йому шість синів. І нарекла йому ім’я: Завулон.","Потім народила дочку і нарекла їй ім’я: Діна.","І згадав Бог про Рахиль, і почув її Бог, і відкрив утробу її.","Вона зачала і народила [Якову] сина, і сказала [Рахиль]: зняв Бог ганьбу мою.","І нарекла йому ім’я: Йосиф, сказавши: Господь дасть мені і другого сина.","Після того, як Рахиль народила Йосифа, Яків сказав Лавану: відпусти мене, і піду я у своє місце, й у свою землю;","віддай [мені] дружин моїх і дітей моїх, за яких я служив тобі, і я піду, бо ти знаєш службу мою, яку я служив тобі.","І сказав йому Лаван: о, якби я знайшов благовоління перед очима твоїми! я помічаю, що за тебе Господь благословив мене.","І сказав: признач собі нагороду від мене, і я дам [тобі].","І сказав йому [Яків]: ти знаєш, як я служив тобі, і якою стала худоба твоя при мені;","бо мало було у тебе до мене, а стало багато; Господь благословив тебе з приходом моїм; коли ж я буду працювати для свого дому?","І сказав [йому Лаван]: що дати тобі? Яків сказав [йому]: не давай мені нічого. Якщо тільки зробиш мені, що я скажу, то я знову буду пасти і стерегти овець твоїх.","Я пройду сьогодні через усю отару овець твоїх; відокрем з нього всяку худобу з цятками і з плямами, усяку тварину чорну із овець, також із плямами і з цятками з кіз. Така худоба буде нагородою мені [і буде моєю].","І буде говорити за мене перед тобою справедливість моя в наступний час, коли прийдеш подивитися нагороду мою. Усяка коза не з цятками і не з плямами, і з овець не чорна, крадене це в мене.","Лаван сказав [йому]: добре, нехай буде за твоїм словом.","І відокремив у той день козлів строкатих і з плямами, і всіх кіз із цятками і з плямами, усіх, на яких було трохи білого, і всіх чорних овець, і віддав у руки синам своїм;","і призначив відстань між собою і між Яковом на три дні путі. Яків же пас іншу дрібну худобу Лаванову.","І взяв Яків свіже пруття із тополі, мигдалю та явора, і повирізував на ньому [Яків] білі смуги, знявши до білизни кору, що на прутті,","і поклав пруття з нарізкою перед худобою у водопійних коритах, куди худоба приходила пити, і де, приходячи пити, зачинала перед пруттям.","І зачинала худоба перед пруттям, і народжувалася худоба строката, і з цятками, і з плямами.","І відокремлював Яків ягнят і ставив худобу лицем до строкатої і всієї чорної худоби Лаванової; і тримав свої отари окремо і не ставив їх разом з худобою Лавана.","Кожного разу, коли зачинала худоба міцна, Яків клав пруття в коритах перед очима худоби, щоб вона зачинала перед пруттям.","А коли зачинала худоба слабка, тоді він не клав. І діставалася слабка худоба Лавану, а міцна Якову.","І стала ця людина дуже, дуже багатою, і було в нього безліч дрібної худоби [і великої худоби], і рабинь, і рабів, і верблюдів, і ослів."],"x":{"22":"0.25.21","43":"0.24.35"}},{"v":["І почув [Яків] слова синів Лаванових, які говорили: Яків заволодів усім, що було у батька нашого, і з маєтку батька нашого склав усе багатство це.","І побачив Яків обличчя Лавана, і ось, воно не таке до нього, як було вчора і третього дня.","І сказав Господь Якову: повернися в землю батьків твоїх і на батьківщину твою; і Я буду з тобою.","І послав Яків, і покликав Рахиль і Лію в поле, до отари дрібної своєї худоби,","і сказав їм: я бачу обличчя батька вашого, що воно до мене не таке, яким було вчора і третього дня; але Бог батька мого був зі мною;","ви самі знаєте, що я всіма силами служив батьку вашому,","а батько ваш обманював мене і разів десять переміняв нагороду мою; але Бог не попустив йому зробити мені зло.","Коли сказав він, що худоба з цятками буде тобі в нагороду, то худоба вся народжувалася з цятками. А коли він сказав: строкаті будуть тобі в нагороду, то вся худоба народжувала строкатих.","І відібрав Бог [усю] худобу у батька вашого і дав [її] мені.","Одного разу в такий час, коли худоба зачинає, я глянув і побачив уві сні, і ось козли [і барани], що піднялися на худобу [на кіз і овець], строкаті, з цятками і плямами.","Ангел Божий сказав мені уві сні: Якове! Я сказав: ось я.","Він сказав: зведи очі твої і подивися: усі козли [і барани], що піднялися на худобу [на кіз і овець], строкаті, з цятками і з плямами, бо Я бачу все, що Лаван робить з тобою;","Я Бог [Який явився тобі] у Вефилі, де ти возлив єлей на пам’ятник і де ти дав Мені обітницю; тепер встань, вийди з землі цієї і повернися в землю батьківщини твоєї [і Я буду з тобою].","Рахиль і Лія сказали йому у відповідь: чи є ще нам частка і спадщина в домі батька нашого?","чи не за чужих він нас вважає? бо він продав нас і з’їв навіть срібло наше;","тому все [маєток і] багатство, що Бог відібрав у батька нашого, є наше і дітей наших; отже, роби все, що Бог сказав тобі.","І встав Яків, і посадив дітей своїх і дружин своїх на верблюдів,","і взяв із собою всю худобу свою і все багатство своє, яке надбав, худобу власну його, яку він придбав у Месопотамії, [і все своє,] щоб іти до Ісаака, батька свого, в землю Ханаанську.","І коли Лаван пішов стригти худобу свою, то Рахиль викрала ідолів, що були у батька її.","Яків же украв серце у Лавана арамеянина, тому що не сповістив його, що відходить.","І пішов з усім, що у нього було; і, вставши, перейшов ріку і попрямував до гори Галаад.","На третій день сказали Лавану [арамеянину], що Яків пішов.","Тоді він взяв із собою [синів і] родичів своїх, і гнався за ним сім днів, і наздогнав його на горі Галаад.","І прийшов Бог до Лавана арамеянина вночі уві сні і сказав йому: бережися, не говори Якову ні доброго, ні злого.","І наздогнав Лаван Якова; Яків же поставив намет свій на горі, і Лаван з родичами своїми поставив на горі Галаад.","І сказав Лаван Якову: що ти зробив? для чого ти обманув мене, і повів дочок моїх, як полонених зброєю?","навіщо ти втік таємно, і сховався від мене, і не сказав мені? я відпустив би тебе з веселощами і з піснями, з тимпаном і з гуслами;","ти не дозволив мені навіть поцілувати онуків моїх і дочок моїх; нерозважливо ти зробив.","Є в руці моїй сила вчинити вам зло; але Бог батька вашого вчора говорив до мене і сказав: бережися, не говори Якову ні доброго, ні злого.","Але нехай би ти пішов, тому що ти нетерпляче захотів бути у домі батька твого, — навіщо ти украв богів моїх?","Яків відповів Лавану і сказав: я боявся, тому що я думав, не відняв би ти в мене дочок своїх [і все моє].","[І сказав Яків:] у кого знайдеш богів твоїх, той не буде живим; при родичах наших дізнавайся, що [є твого] у мене, і візьми собі. [Але він нічого від нього не дізнався.] Яків не знав, що Рахиль [дружина його] украла їх.","І ходив Лаван у намет Якова, і в намет Лії, і в намет двох рабинь, [і обшукував,] але не знайшов. І, вийшовши з намету Лії, ввійшов у намет Рахилі.","Рахиль же взяла ідолів, і поклала їх під верблюже сідло і сіла на них. І обшукав Лаван увесь намет; але не знайшов.","Вона ж сказала батькові своєму: нехай не прогнівається господар мій, що я не можу встати перед тобою, тому що в мене звичайне жіноче. І [Лаван] шукав [у всьому наметі], але не знайшов ідолів.","Яків розсердився і вступив у суперечку з Лаваном. І почав Яків говорити і сказав Лавану: яка провина моя, який гріх мій, що ти переслідуєш мене?","ти оглянув у мене усі речі [в домі моєму], що знайшов ти з усіх речей твого дому? покажи тут перед родичами моїми і перед родичами твоїми; нехай вони розсудять між нами обома.","Ось, двадцять років я був у тебе; вівці твої і кози твої не викидали; баранів отари твоєї я не їв;","роздертого звіром я не приносив до тебе, це був мій збиток; ти з мене стягував, чи вдень що пропадало, чи вночі пропадало;","я знемагав удень від спеки, а вночі від холоду, і сон мій тікав від очей моїх.","Такі мої двадцять років у домі твоєму. Я служив тобі чотирнадцять років за двох дочок твоїх і шість років за худобу твою, а ти десять разів переміняв нагороду мою.","Якби не був зі мною Бог батька мого, Бог Авраама і страх Ісаака, ти тепер відпустив би мене ні з чим. Бог побачив недолю мою і працю рук моїх і заступився за мене вчора.","І відповів Лаван і сказав Якову: дочки — мої дочки; діти — мої діти; худоба — моя худоба, і все, що ти бачиш, це моє: чи можу я що зробити тепер з дочками моїми і з дітьми їхніми, які народжені ними?","Тепер укладімо союз я і ти, і це буде свідоцтвом між мною і тобою. [При цьому Яків сказав йому: ось, з нами немає нікого; дивися, Бог свідок між мною і тобою.]","І взяв Яків камінь і поставив його пам’ятником.","І сказав Яків родичам своїм: наберіть каміння. Вони взяли каміння, і зробили пагорб, і їли [і пили] там на пагорбі. [І сказав йому Лаван: пагорб цей свідок сьогодні між мною і тобою.]","І назвав його Лаван: Ієгар-Сагадуфа; а Яків назвав його Галаадом.","І сказав Лаван [Якову]: сьогодні цей пагорб [і пам’ятник, що я поставив,] між мною і тобою свідок. Тому і наречено йому ім’я: Галаад,","також: Мицпа, від того, що Лаван сказав: нехай наглядає Господь за мною і за тобою, коли ми розійдемося один від одного;","якщо ти будеш чинити лихе з дочками моїми, або якщо візьмеш дружин, крім дочок моїх, то, хоч немає людини між нами, [яка б бачила,] але дивись, Бог свідок між мною і між тобою.","І сказав Лаван Якову: ось пагорб цей і ось пам’ятник, який я поставив між мною і тобою;","цей пагорб свідок, і цей пам’ятник свідок, що ні я не перейду до тебе за цей пагорб, ні ти не перейдеш до мене за цей пагорб і за цей пам’ятник, для зла;","Бог Авраамів і Бог Нахорів нехай судить між нами, Бог батька їхнього. Яків поклявся страхом батька свого Ісаака.","І заколов Яків жертву на горі і покликав родичів своїх їсти хліб; і вони їли хліб [і пили] і ночували на горі.","І встав Лаван рано-вранці і поцілував онуків своїх і дочок своїх, і благословив їх. І пішов і повернувся Лаван у своє місце."],"x":{"13":"0.28.18","19":"8.19.13","29":"0.48.16","39":"1.22.12","42":"0.28.13|31.8.13","48":"5.22.27|5.24.27","53":"0.28.13|5.24.2|0.26.3|31.8.13","55":"0.29.11"}},{"v":["А Яків пішов шляхом своїм. [І, глянувши, побачив ополчення Боже, що ополчилося]. І зустріли його ангели Божі.","Яків, побачивши їх, сказав: це ополчення Боже. І нарік ім’я місцю тому: Маханаїм.","І послав Яків перед собою вісників до брата свого Ісава в землю Сеїр, в область Едом,","і наказав їм, промовивши: так скажіть добродію моєму Ісаву: ось що говорить раб твій Яків: я жив у Лавана і прожив донині;","і є в мене воли й осли і дрібна худоба, і раби й рабині; і я послав сповістити про себе добродія мого [Ісава], щоб придбати [рабу твоєму] благовоління перед очима твоїми.","І повернулися вісники до Якова і сказали: ми ходили до брата твого Ісава, він іде назустріч тобі, і з ним чотириста чоловік.","Яків дуже злякався і схвилювався; і розділив людей, що були з ним, і худобу дрібну й велику і верблюдів на два стани.","І сказав [Яків]: якщо Ісав нападе на один стан і поб’є його, то другий стан може врятуватися.","І сказав Яків: Боже отця мого Авраама і Боже отця мого Ісаака, Господи [Боже], що сказав мені: повернися в землю твою, на батьківщину твою, і Я буду благодіяти тобі!","Недостойний я всіх милостей і всіх благодіянь, що Ти створив рабу Твоєму, тому що я з посохом моїм перейшов цей Йордан, а тепер у мене два стани.","Визволи мене від руки брата мого, від руки Ісава, тому що я боюся його, щоб він, прийшовши, не убив мене [і] матері з дітьми.","Ти сказав: Я буду благодіяти тобі і зроблю нащадків твоїх, як пісок морський, якого не порахувати від безлічі.","І ночував там Яків у ту ніч. І взяв з того, що у нього було, [і послав] у подарунок Ісаву, братові своєму:","двісті кіз, двадцять козлів, двісті овець, двадцять баранів,","тридцять верблюдиць дійних з верблюжатами їх, сорок корів, десять волів, двадцять ослиць, десять ослів.","І дав у руки рабам своїм кожне стадо окремо і сказав рабам своїм: підіть переді мною і залишайте відстань від стада до стада.","І наказав першому, сказавши: коли брат мій Ісав зустрінеться тобі і запитає тебе, говорячи: чий ти? і куди йдеш? і чиє це стадо [йде] перед тобою?","то скажи: раба твого Якова; це подарунок, посланий господарю моєму Ісаву; ось, і сам він за нами [йде].","Те саме [що першому] наказав він і другому, і третьому, і всім, які йшли за стадами, говорячи: так скажіть Ісаву, коли зустрінете його;","і скажіть: ось, і раб твій Яків [іде] за нами. Бо він сказав сам у собі: умилостивлю його дарами, що йдуть переді мною, і потім побачу лице його; можливо, і прийме мене.","І пішли дари перед ним, а він у ту ніч ночував у стані.","І встав у ту ніч, і, взявши двох дружин своїх і двох рабинь своїх, і одинадцять синів своїх, перейшов через Іавок убрід;","і, взявши їх, перевів через потік, і перевів усе, що в нього було.","І залишився Яків один. І боровся Хтось з ним до появи зорі;","і, побачивши, що не подолає його, торкнувся суглоба стегна його і пошкодив суглоб стегна у Якова, коли він боровся з Ним.","І сказав [йому]: відпусти Мене, бо зійшла зоря. Яків сказав: не відпущу Тебе, доки не благословиш мене.","І сказав: як ім’я твоє? Він сказав: Яків.","І сказав [йому]: відтепер ім’я твоє буде не Яків, а Ізраїль, тому що ти боровся з Богом, і людей перемагати будеш.","Запитав і Яків, говорячи: скажи [мені] ім’я Твоє. І Він сказав: навіщо ти запитуєш про ім’я Моє? [воно дивне.] І благословив його там.","І нарік Яків ім’я місцю тому: Пенуел; тому бо, говорив він, я бачив Бога лицем до лиця, і збереглася душа моя.","І зійшло сонце, коли він проходив Пенуел; і кульгав він на стегно своє.","Тому і донині сини Ізраїлеві не їдять жил, що на суглобі стегна, тому що Той, Хто боровся, торкнувся жили на суглобі стегна Якова."],"x":{"1":"25.33.8","2":"9.2.8","3":"0.14.6|0.36.8|4.2.5:22","4":"0.31.38","9":"0.28.13|0.31.3:13","10":"9.7.18","12":"0.28.14|25.138.18","17":"0.33.8","20":"26.18.17|26.21.14","22":"3.21.24|4.2.37","24":"38.12.3-4","28":"0.35.10","29":"6.13.18","30":"6.8.8|10.12.25"}},{"v":["Глянув Яків і побачив, і ось, іде Ісав, [брат його,] і з ним чотириста чоловік. І розділив [Яків] дітей Лії, Рахилі і двох служниць.","І поставив [двох] служниць і дітей їхніх попереду, Лію і дітей її за ними, а Рахиль і Йосифа позаду.","А сам пішов перед ними і поклонився до землі сім разів, підходячи до брата свого.","І побіг Ісав до нього назустріч і обійняв його, й упав на шию його і цілував його, і плакали [обидва].","І глянув [Ісав] і побачив дружин і дітей і сказав: хто це у тебе? Яків сказав: діти, яких Бог дарував рабу твоєму.","І підійшли служниці і діти їхні й поклонилися;","підійшли і Лія та діти її і поклонилися; в кінці підійшли Йосиф і Рахиль і поклонились.","І сказав Ісав: для чого у тебе така кількість, яку я зустрів? І сказав Яків: щоб [рабу твоєму] придбати благовоління в очах господаря мого.","Ісав сказав: у мене багато, брате мій; нехай буде твоє у тебе.","Яків сказав: ні, якщо я придбав благовоління в очах твоїх, прийми дар мій від руки моєї, тому що я побачив лице твоє, наче хто побачив лице Боже, і ти був доброзичливим до мене;","прийми благословення моє, яке я приніс тобі, тому що Бог дарував мені, і є у мене все. І ублагав його, і той узяв","і сказав: піднімемося і підемо; і я піду перед тобою.","Яків сказав йому: господар мій знає, що діти ніжні, а дрібна і велика худоба у мене дійна: якщо погнати її один день, то помре вся худоба;","нехай господар мій піде попереду раба свого, а я піду повільно, як піде худоба, що переді мною, і як підуть діти, і прийду до господаря мого у Сеїр.","Ісав сказав: залишу я з тобою кілька людей, які при мені. Яків сказав: до чого це? тільки б мені придбати благовоління в очах господаря мого!","І повернувся Ісав того ж дня шляхом своїм у Сеїр.","А Яків рушив у Сокхоф, і побудував собі дім, і для худоби своєї зробив курені. Тому він нарік ім’я місцю: Сокхоф.","Яків, повернувшись з Месопотамії, благополучно прийшов до міста Сихема, що в землі Ханаанській, і розташувався перед містом.","І купив частину поля, на якому розкинув намет свій, у синів Еммора, батька Сихемового, за сто монет.","І поставив там жертовник, і призвав ім’я Господа Бога Ізраїлевого."],"x":{"8":"0.32.17","17":"5.13.27|6.8.5","19":"54.7.16"}},{"v":["Діна, дочка Лії, яку вона народила Якову, вийшла подивитися на дочок землі тієї.","І побачив її Сихем, син Еммора евеянина, князя землі тієї, і взяв її, і спав з нею, і вчинив над нею насильство.","І приліпилася душа його до Діни, дочки Якова, і він полюбив дівчину і говорив до серця дівочого.","І сказав Сихем Еммору, батькові своєму, говорячи: візьми мені цю дівчину за дружину.","Яків чув, що [син Емморів] збезчестив Діну, дочку його, але оскільки сини його були з худобою його в полі, то Яків мовчав, поки не прийшли вони.","І вийшов Еммор, батько Сихемів, до Якова, поговорити з ним.","Сини ж Якова прийшли з поля, і коли почули, то засмутилися мужі ті й запалали гнівом, тому що безчестя зробив він Ізраїлю, переспавши з дочкою Якова, а так не можна робити.","Еммор став говорити їм, і сказав: Сихем, син мій, приліпився душею до дочки вашої; дайте ж її за дружину йому;","порідніться з нами; віддавайте за нас дочок ваших, а наших дочок беріть собі [за синів ваших];","і живіть з нами; земля ця [простора] перед вами, живіть і промишляйте на ній і здобувайте її у володіння.","Сихем же сказав батьку її і братам її: тільки б мені знайти благовоління в очах ваших, я дам, що тільки скажете мені;","призначте найбільше віно й дарунки; я дам, що не скажете мені, тільки віддайте мені дівчину за дружину.","І відповіли сини Якова Сихему та Еммору, батькові його, з лукавством; а говорили так тому, що він збезчестив Діну, сестру їхню;","і сказали їм [Симеон і Левій, брати Діни, сини Ліїні]: не можемо цього зробити, віддати сестру нашу за чоловіка, який необрізаний, тому що це безчесно для нас;","тільки за тієї умови ми погодимося з вами [й оселимося у вас], якщо ви будете як ми, щоб і у вас уся чоловіча стать була обрізана;","і будемо віддавати за вас дочок наших і брати за себе ваших дочок, і будемо жити з вами, і складемо один народ;","а якщо не послухаєтеся нас у тому, щоб обрізатися, то ми візьмемо дочку нашу і відійдемо.","І сподобалися слова ці Еммору і Сихему, сину Еммора.","Юнак не барився зробити це, тому що любив дочку Якова. А його більше за всіх поважали в домі батька його.","І прийшли Еммор і Сихем, син його, до воріт міста свого, і стали говорити жителям міста свого і сказали:","ці люди мирні з нами; нехай вони селяться на землі і промишляють на ній; земля ж ось простора перед ними. Станемо брати дочок їхніх собі за дружин і наших дочок віддавати за них.","Тільки за тієї умови ці люди погоджуються жити з нами і бути одним народом, щоб і в нас обрізана була вся чоловіча стать, як вони обрізані.","Чи не для нас отари їх, і маєтки їх, і вся худоба їх? Тільки [у тому] погодимося з ними, і будуть жити з нами.","І послухалися Еммора і Сихема, сина його, всі, хто виходив з воріт міста його: і була обрізана вся чоловіча стать, — усі, що виходили з воріт міста його.","На третій день, коли вони хворіли, два сини Якова, Симеон і Левій, брати Діни, взяли кожен свій меч, і сміливо напали на місто, й умертвили всю чоловічу стать;","і самого Еммора і Сихема, сина його, убили мечем; і взяли Діну з дому Сихемового і вийшли.","Сини Якова прийшли до убитих і розграбували місто за те, що збезчестили [Діну] сестру їхню.","Вони взяли дрібну і велику худобу їх, і ослів їх, і все, що було в місті, і що було в полі;","і все багатство їх, і всіх дітей їх, і дружин їх взяли в полон, і розграбували усе, що було в [місті, й усе, що було в] домах.","І сказав Яків Симеону і Левію: ви обурили мене, зробивши мене ненависним для [усіх] жителів цієї землі, для хананеїв і ферезеїв. У мене людей мало; зберуться проти мене, подолають мене, і знищений буду я і дім мій.","Вони ж сказали: а хіба можна чинити з сестрою нашою, як з блудницею!"],"x":{"1":"0.30.21","7":"4.23.17","12":"1.22.16","14":"5.5.9","20":"0.23.10","24":"0.23.10","25":"0.49.6","30":"0.49.5|1.5.21|8.13.4"}},{"v":["Бог сказав Якову: встань, піди у Вефиль і живи там, і зроби там жертовник Богу, Який явився тобі, коли ти тікав від лиця Ісава, брата твого.","І сказав Яків дому своєму і всім, хто був з ним: киньте богів чужих, що знаходяться у вас, і очистіться, і перемініть одяг ваш;","встанемо і підемо у Вефиль; там влаштую я жертовник Богу, Який почув мене в день біди моєї і був зі мною [й оберігав мене] в путі, якою я ходив.","І віддали Якову всіх богів чужих, що були в руках їх, і серги, що були у вухах їхніх, і закопав їх Яків під дубом, який поблизу Сихема. [І залишив їх невідомими навіть до нинішнього дня.]","І вирушили вони [від Сихема]. І був жах Божий на навколишніх містах, і не переслідували синів Яковових.","І прийшов Яків у Луз, що в землі Ханаанській, тобто у Вефиль, сам і всі люди, що були з ним,","і влаштував там жертовник, і назвав це місце: Ел-Вефиль, бо тут явився йому Бог, коли він тікав від лиця [Ісава] брата свого.","І померла Девора, годувальниця Ревеккина, і поховали її нижче Вефиля під дубом, який і назвав Яків дубом плачу.","І явився Бог Якову [в Лузі] після повернення його з Месопотамії, і благословив його,","і сказав йому Бог: ім’я твоє Яків; відтепер ти не будеш називатися Яковом, але буде ім’я твоє: Ізраїль. І нарік йому ім’я: Ізраїль.","І сказав йому Бог: Я Бог Всемогутній; плодись й розмножуйся; народ і безліч народів буде від тебе, і царі народяться із лона твого;","землю, яку Я дав Аврааму й Ісааку, Я дам тобі, і нащадкам твоїм після тебе дам землю цю.","І відійшов від нього Бог з місця, на якому говорив йому.","І поставив Яків пам’ятник на місці, на якому говорив йому [Бог], пам’ятник кам’яний, і злив на нього узливання, і злив на нього єлей;","і нарік Яків ім’я місцю, на якому Бог говорив йому: Вефиль.","І вирушили з Вефиля. [І розкинув він намет свій за вежею Гадер.] І коли ще залишалася деяка відстань землі до Ефрафи, Рахиль народила, і пологи її були тяжкими.","Коли ж вона страждала в пологах, повитуха сказала їй: не бійся, бо і це тобі син.","І коли виходила з неї душа, бо вона вмирала, то нарекла йому ім’я: Беноні. Але батько його назвав його Веніаміном.","І вмерла Рахиль, і похована була по дорозі у Ефрафу, тобто Вифлеєм.","Яків поставив над гробом її пам’ятник. Це надгробний пам’ятник Рахилі до цього дня.","І вирушив [звідти] Ізраїль і розкинув намет свій за вежею Гадер.","Під час перебування Ізраїля в тій країні, Рувим пішов і переспав з Валлою, наложницею батька свого [Якова]. І почув Ізраїль [і прийняв це зі смутком]. Синів же в Якова було дванадцять.","Сини Лії: первісток Якова Рувим, після нього Симеон, Левій, Іуда, Іссахар і Завулон.","Сини Рахилі: Йосиф і Веніамін.","Сини Валли, служниці Рахилиної: Дан і Неффалим.","Сини Зелфи, служниці Ліїної: Гад і Асир. Ці сини Якова, які народилися йому в Месопотамії.","І прийшов Яків до Ісаака, батька свого, [бо він був ще живий,] у Мамре, у Кириаф-Арбу, тобто Хеврон [у землі Ханаанській,] де подорожували Авраам та Ісаак.","І було днів [життя] Ісаакового сто вісімдесят років.","І спустив Ісаак дух і помер, і приєднався до народу свого, будучи старим і насиченим життям; і поховали його Ісав і Яків, сини його."],"x":{"1":"0.28.13","2":"0.31.19|66.4.22|68.3.9","4":"5.24.26|6.9.6","5":"1.23.27|8.14.15","6":"0.12.8|0.28.19","7":"0.28.13","8":"12.10.12","10":"0.32.28","11":"0.1.28|0.17.1:6","12":"0.12.7","13":"0.17.22","14":"0.28.18","15":"0.28.19","17":"8.4.20","19":"0.48.7","20":"21.13.27|8.10.2","21":"43.4.8","22":"0.49.4","23":"0.46.8|1.1.2","24":"0.30.23","25":"0.30.5","26":"0.30.9","27":"0.23.2|0.14.13","29":"0.25.9"}},{"v":["Ось родовід Ісава, він же Едом.","Ісав узяв собі дружин з дочок ханаанських: Аду, дочку Елона хеттеянина, й Оливему, дочку Ани, сина Цивеона евеянина,","і Васемафу, дочку Ізмаїла, сестру Наваїофа.","Ада народила Ісаву Елифаза, Васемафа народила Рагуїла,","Оливема народила Ієуса, Ієглома і Корея. Це сини Ісава, що народилися йому в землі Ханаанській.","І взяв Ісав дружин своїх і синів своїх, і дочок своїх, і всіх людей дому свого, й [усі] отари свої, і всю худобу свою, і все майно своє, яке він придбав у землі Ханаанській, і пішов [Ісав] в іншу землю від лиця Якова, брата свого,","тому що майно їх було таке велике, що вони не могли жити разом, і земля подорожування їх не вміщала їх, через безлічі отар їхніх.","І оселився Ісав на горі Сеїр, Ісав, він же Едом.","І ось родовід Ісава, батька ідумеїв, на горі Сеїр.","Ось імена синів Ісава: Елифаз, син Ади, дружини Ісавової, і Рагуїл, син Васемафи, дружини Ісавової.","У Елифаза були сини: Феман, Омар, Цефо, Гафам і Кеназ.","Фамна ж була наложницею Елифаза, сина Ісавового, і народила Елифазу Амалика. Ось сини Ади, дружини Ісавової.","І ось сини Рагуїла: Нахаф і Зерах, Шамма і Миза. Це сини Васемафи, дружини Ісавової.","І ці були сини Оливеми, дочки Ани, сина Цивеонового, дружини Ісавової: вона народила Ісаву Ієуса, Ієглома і Корея.","Ось старійшини синів Ісавових. Сини Елифаза, первістка Ісавового: старійшина Феман, старійшина Омар, старійшина Цефо, старійшина Кеназ,","старійшина Корей, старійшина Гафам, старійшина Амалик. Ці старійшини Елифазові в землі Едома; ці сини Ади.","Ці сини Рагуїла, сина Ісавового: старійшина Нахаф, старійшина Зерах, старійшина Шамма, старійшина Миза. Ці старійшини Рагуїлові в землі Едома; ці сини Васемафи, дружини Ісавової.","Ці сини Оливеми, дружини Ісавової: старійшина Ієус, старійшина Ієглом, старійшина Корей. Ці старійшини Оливеми, дочки Ани, дружини Ісавової.","Ось сини Ісава, і ось старійшини їх. Це Едом.","Ці сини Сеїра хорреянина, що жили в землі тій: Лотан, Шовал, Цивеон, Ана,","Дишон, Ецер і Дишан. Ці старійшини хорреїв, синів Сеїра, у землі Едома.","Сини Лотана були: Хори і Геман; а сестра у Лотана: Фамна.","Ці сини Шовала: Алван, Манахаф, Евал, Шефо й Онам.","Ці сини Цивеона: Аїа й Ана. Це той Ана, що знайшов теплі води в пустелі, коли пас ослів Цивеона, батька свого.","Ці діти Ани: Дишон і Оливема, дочка Ани.","Ці сини Дишона: Хемдан, Ешбан, Іфран і Херан.","Ці сини Ецера: Билган, Зааван, [Укам] і Акан.","Ці сини Дишана: Уц і Аран.","Ці старійшини хорреїв: старійшина Лотан, старійшина Шовал, старійшина Цивеон, старійшина Ана,","старійшина Дишон, старійшина Ецер, старійшина Дишан. Ось старійшини хорреїв, за старшинством їх у землі Сеїр.","Ось царі, що царювали в землі Едома, раніше царювання царів у синів Ізраїлевих:","царював у Едомі Бела, син Веорів, а ім’я міста його Дингава.","І помер Бела, і зацарював після нього Іовав, син Зераха, з Восори.","Помер Іовав, і зацарював після нього Хушам, із землі феманитян.","І помер Хушам, і запанував після нього Гадад, син Бедадів, який переміг мадіанитян на полі Моава; ім’я міста його Авиф.","І помер Гадад, і зацарював після нього Самла з Масреки.","І помер Самла, і зацарював після нього Саул з Реховофа, що біля річки.","І помер Саул, і зацарював після нього Баал-Ханан, син Ахбора.","І помер Баал-Ханан, син Ахбора, і зацарював після нього Гадар [син Варадів]; ім’я міста його Пау; ім’я дружини його Мегетавеель, дочка Матреди, сина Мезагава.","Ці імена старійшин Ісавових, за племенами їх, за місцями їх, за іменами їх, [за народами їх]: старійшина Фимна, старійшина Алва, старійшина Ієтеф,","старійшина Оливема, старійшина Ела, старійшина Пинон,","старійшина Кеназ, старійшина Феман, старійшина Мивцар,","старійшина Магдиїл, старійшина Ірам. Ось старійшини ідумейські, за їхніми селищами, у землі володіння їх. Ось Ісав, батько ідумеїв."],"x":{"1":"0.25.30","2":"0.26.34","3":"0.28.9","4":"12.1.35","6":"5.24.4|0.32.3","7":"0.13.6|0.26.14","8":"5.24.4","10":"12.1.35","20":"4.2.11-12|12.1.38","23":"12.1.40","33":"31.34.6|31.63.1","37":"0.10.11","38":"12.1.49","40":"12.1.51"}},{"v":["Яків жив у землі подорожування батька свого [Ісаака], у землі Ханаанській.","Ось житіє Якова. Йосиф, сімнадцяти років, пас худобу [батька свого] разом із братами своїми, будучи отроком, з синами Валли і з синами Зелфи, дружин батька свого. І доносив Йосиф недобрі про них чутки до [Ізраїля] батька їх.","Ізраїль любив Йосифа більше за всіх синів своїх, тому що він був сином старости його, — і зробив йому різнобарвний одяг.","І побачили брати його, що батько їх любить його більше, ніж усіх братів його; і зненавиділи його і не могли говорити з ним дружньо.","І бачив Йосиф сон, і розповів [його] братам своїм: і вони зненавиділи його ще більше.","Він сказав їм: вислухайте сон, який я бачив:","ось, ми в’яжемо снопи посередині поля; і ось, мій сніп встав і став прямо; і ось, ваші снопи стали навкруги і поклонилися моєму снопові.","І сказали йому брати його: невже ти будеш царювати над нами? невже будеш володіти нами? І зненавиділи його ще більше за сни його і за слова його.","І бачив він ще інший сон і розповів його [батькові своєму і] братам своїм, говорячи: ось, я бачив ще сон: ось, сонце і місяць і одинадцять зірок поклоняються мені.","І він розповів батькові своєму і братам своїм; і насварив його батько його і сказав йому: що це за сон, який ти бачив? невже я і твоя мати, і твої брати прийдемо поклонитися тобі до землі?","Брати його досаджували на нього, а батько його запам’ятав це слово.","Брати його пішли пасти худобу батька свого в Сихем.","І сказав Ізраїль Йосифові: брати твої чи не пасуть у Сихемі? піди, я пошлю тебе до них. Він відповів йому: ось я.","[Ізраїль] сказав йому: піди, подивися, чи здорові брати твої і чи ціла худоба, і принеси мені відповідь. І послав його з долини Хевронської; і він прийшов у Сихем.","І знайшов хтось його, що блукав у полі, і запитав його той чоловік, говорячи: чого ти шукаєш?","Він сказав: я шукаю братів моїх; скажи мені, де вони пасуть?","І сказав той чоловік: вони пішли звідси, бо я чув, як вони говорили: підемо в Дофан. І пішов Йосиф за братами своїми і знайшов їх у Дофані.","І побачили вони його здаля, і раніше ніж він наблизився до них, стали замишляти проти нього, щоб убити його.","І сказали один одному: ось, іде сновидець;","підемо тепер, і вб’ємо його, і кинемо його в який-небудь рів, і скажемо, що хижий звір з’їв його; і побачимо, що буде із його снів.","І почув це Рувим і порятував його від рук їхніх, сказавши: не вб’ємо його.","І сказав їм Рувим: не проливайте крови; киньте його у рів, що у пустелі, а руки не накладайте на нього. Це говорив він [з тим наміром], щоб урятувати його від рук їхніх і повернути його до батька його.","Коли Йосиф прийшов до братів своїх, вони зняли з Йосифа одежу його, одежу різнобарвну, яка була на ньому,","і взяли його і кинули його у рів; рів же той був порожнім; води в ньому не було.","І сіли вони їсти хліб, і, глянувши, побачили, ось, іде з Галаада караван ізмаїльтян, і верблюди їхні несуть стираксу, бальзам і ладан: ідуть вони відвезти це в Єгипет.","І сказав Іуда братам своїм: яка користь, якщо ми вб’ємо брата нашого і сховаємо кров його?","Підемо, продамо його ізмаїльтянам, а руки наші нехай не будуть на ньому, тому що він брат наш, плоть наша. Брати його послухалися","і, коли проходили купці мадіамські, витягли Йосифа з рову і продали Йосифа ізмаїльтянам за двадцять срібників; а вони відвели Йосифа в Єгипет.","Рувим же прийшов знову до рову; і ось, немає Йосифа в рові. І роздер він одяг свій,","і повернувся до братів своїх, і сказав: отрока нема, а я, куди я дінуся?","І взяли одяг Йосифа, і закололи козла, і вимазали одяг кров’ю;","і послали різнобарвний одяг, і принесли до батька свого, і сказали: ми це знайшли; подивися, чи сина твого цей одяг, чи ні.","Він упізнав його і сказав: це одяг сина мого; хижий звір з’їв його; очевидно, розтерзаний Йосиф.","І розідрав Яків одяг свій, і одяг веретище на стегна свої, й оплакував сина свого багато днів.","І зібрались усі сини його і всі дочки його, щоб утішити його; але він не хотів утішитися і сказав: з печаллю зійду до сина мого в пекло. Так оплакував його батько його.","Мадіанитяни ж продали його в Єгипті Потифару, царедворцеві фараона, начальникові охоронців."],"x":{"1":"0.35.27|0.36.6|75.11.13","4":"54.7.9","11":"37.7.28|52.2.19:51","14":"8.17.18|0.23.2","17":"11.6.13","20":"50.21.38|25.40.8","21":"0.42.22","22":"0.42.22","24":"48.9.11","25":"0.31.21|32.8.22|32.22.6","26":"24.16.18","28":"6.8.26|29.10.13|25.104.17","29":"0.44.13|2.10.6|3.14.6","33":"0.44.28","34":"8.4.12|9.3.31|10.20.32","35":"18.10.7|0.42.38","36":"0.39.1|25.104.17"}},{"v":["У той час Іуда відійшов від братів своїх і оселився поблизу одного одолламитянина, якому ім’я: Хира.","І побачив там Іуда дочку одного хананеянина, якому ім’я: Шуа; і взяв її і ввійшов до неї.","Вона зачала і народила сина; і він нарік йому ім’я: Ір.","І зачала знову, і народила сина, і нарекла йому ім’я: Онан.","І ще народила сина [третього] і нарекла йому ім’я: Шела. Іуда був у Хезиві, коли вона народила його.","І взяв Іуда дружину Ірові, первісткові своєму; ім’я їй Фамар.","Ір, первісток Іудин, був неугодний перед очима Господа, й умертвив його Господь.","І сказав Іуда Онану: увійди до дружини брата твого, одружися з нею, як дівер, і віднови сíм’я братові твоєму.","Онан знав, що сíм’я буде не йому, і тому, коли входив до дружини брата свого, виливав [сíм’я] на землю, щоб не дати сімені братові своєму.","Злом було перед очима Господа те, що він робив; і Він умертвив його.","І сказав Іуда Фамарі, невістці своїй [після смерти двох синів своїх]: живи вдовою в домі батька твого, доки підросте Шела, син мій. Тому що він сказав [у розумі своєму]: не помер би і він подібно до братів його. Фамар пішла і стала жити в домі батька свого.","Минуло багато часу, і померла дочка Шуї, дружина Іудина. Іуда, утішившись, пішов у Фамну до охоронців худоби його, сам і Хира, друг його, одолламитянин.","І повідомили Фамар, говорячи: ось, свекор твій іде у Фамну стригти худобу свою.","І зняла вона із себе одяг удівства свого, покрила себе покривалом і, закрившись, сіла біля воріт Енаїма, що на дорозі до Фамни. Бо бачила, що Шела виріс, і вона не дана йому за дружину.","І побачив її Іуда і прийняв її за блудницю, тому що вона закрила лице своє. [І не впізнав її.]","Він повернув до неї і сказав: я увійду до тебе. Тому що не знав, що це невістка його. Вона сказала: що ти даси мені, якщо ввійдеш до мене?","Він сказав: я надішлю тобі козеня з отари [моєї]. Вона сказала: чи даси ти мені заставу, поки пришлеш?","Він сказав: яку дати тобі заставу? Вона сказала: печатку твою, і перев’язь твою, і тростину твою, що в руці твоїй. І дав він їй і ввійшов до неї; і вона зачала від нього.","І, вставши, пішла, зняла з себе покривало своє й одяглася в одяг удівства свого.","Іуда ж послав козеня через друга свого одолламитянина, щоб взяти заставу з руки жінки, але він не знайшов її.","І запитав жителів того місця, говорячи: де блудниця, що була в Енаїмі при дорозі? Але вони сказали: тут не було блудниці.","І повернувся він до Іуди і сказав: я не знайшов її; та й жителі місця того сказали: тут не було блудниці.","Іуда сказав: нехай вона візьме собі, аби тільки не стали над нами сміятися; ось, я посилав це козеня, але ти не знайшов її.","Минуло близько трьох місяців, і сказали Іуді, говорячи: Фамар, невістка твоя, впала у блуд, і ось, вона вагітна від блуду. Іуда сказав: виведіть її, і нехай вона буде спалена.","Але коли повели її, вона послала сказати свекру своєму: я вагітна від того, чиї ці речі. І сказала: впізнавай, чия ця печатка і перев’язь і тростина.","Іуда впізнав і сказав: вона правіша за мене, тому що я не дав її Шелі, синові моєму. І не пізнавав її більше.","Під час пологів її виявилося, що в утробі у неї близнюки.","І під час пологів її з’явилася рука [одного]; і взяла повитуха і нав’язала йому на руку червону нитку, сказавши: цей вийшов першим.","Але він повернув руку свою; і ось, вийшов брат його. І вона сказала: як ти подолав собі перешкоду? І наречено йому ім’я: Фарес.","Потім вийшов брат його з червоною ниткою на руці. І наречено йому ім’я: Зара."],"x":{"3":"0.46.12|3.26.19|12.2.3","5":"3.26.20","7":"3.26.19","8":"4.25.5|50.22.24|51.12.19","11":"18.7.11","12":"8.25.2","14":"26.9.14|32.3.2","15":"26.7.12","16":"2.18.15|2.20.12","24":"0.20.3|2.21.9|4.22.22","27":"12.2.4|50.1.3","29":"0.46.12|12.4.1"}},{"v":["Йосиф же відведений був до Єгипту, і купив його з рук ізмаїльтян, які привели його туди, єгиптянин Потифар, царедворець фараонів, начальник охоронців.","І був Господь з Йосифом: він був успішним у справах і жив у домі господаря свого, єгиптянина.","І побачив господар його, що Господь з ним і що в усьому, що він робить, Господь у руках його дає успіх.","І здобув Йосиф благовоління в очах його і служив йому. І він поставив його над домом своїм, і все, що мав, віддав до рук його.","І з того часу, як він поставив його над домом своїм і над усім, що мав, Господь благословив дім єгиптянина заради Йосифа, і було благословення Господнє на всьому, що мав він у домі й у полі [його].","І залишив він усе, що мав, у руках Йосифа і не знав він при ньому нічого, крім хліба, який він їв. Йосиф же був красивий станом і красивий лицем.","І звернула погляди на Йосифа дружина господаря його і сказала: спи зі мною.","Але він відмовився і сказав дружині господаря свого: ось, господар мій не знає при мені нічого в домі, і все, що має, віддав у мої руки;","немає більшого за мене в домі цьому; і він не заборонив мені нічого, крім тебе, тому що ти дружина його; як же зроблю я це велике зло і згрішу перед Богом?","Коли вона щодня так говорила Йосифу, а він не слухав її, щоб спати з нею і бути з нею,","трапилося в один день, що він увійшов у дім робити справу свою, а нікого із домашніх тут у домі не було;","вона схопила його за одяг його і сказала: лягай зі мною. Але він, залишивши одежу свою в руках її, побіг і вибіг геть.","Вона ж, побачивши, що він залишив одяг свій у руках її і побіг геть,","покликала домашніх своїх і сказала їм так: подивіться, він привів до нас єврея насміхатися над нами. Він прийшов до мене, щоб лягти зі мною, але я закричала гучним голосом,","і він, почувши, що я здійняла крик і закричала, залишив у мене одяг свій, і побіг, і вибіг геть.","І залишила одежу його у себе до приходу господаря його в дім свій.","І переказала йому ті самі слова, говорячи: раб єврей, якого ти привів до нас, приходив до мене насміятися наді мною [і говорив мені: ляжу я з тобою],","але, коли [почув, що] я підняла крик і закричала, він залишив у мене одяг свій і втік геть.","Коли господар його почув слова дружини своєї, які вона сказала йому, говорячи: так вчинив зі мною раб твій, то спалахнув гнівом;","і взяв Йосифа господар його і віддав його у в’язницю, де утримувалися в’язні царя. І був він там у в’язниці.","І Господь був з Йосифом, і простягнув до нього милість, і дарував йому благовоління в очах начальника в’язниці.","І віддав начальник в’язниці в руки Йосифові усіх в’язнів, що перебували у в’язниці, і в усьому, що вони там не робили б, він був розпорядником.","Начальник в’язниці і не дивився ні за чим, що було у нього в руках, тому що Господь був з Йосифом, і в усьому, що він робив, Господь давав успіх."],"x":{"1":"25.104.17|54.7.9","2":"54.7.9","3":"0.21.22|25.1.3","5":"0.30.27|31.45.4","7":"24.31.1|26.7.5|57.2.14","9":"24.24.15|30.23.27|31.29.15","12":"9.13.11","14":"30.25.19","20":"25.104.18","21":"29.10.14|54.7.10","23":"0.39.3|25.1.3"}},{"v":["Після цього виночерпій царя Єгипетського і хлібодар провинилися перед господарем своїм, царем Єгипетським.","І прогнівався фараон на двох царедворців своїх, на головного виночерпія і на головного хлібодара,","і віддав їх під варту в дім начальника охоронців, у в’язницю, у місце, де ув’язнений був Йосиф.","Начальник охоронців приставив до них Йосифа, і він служив їм. І пробули вони під вартою деякий час.","Одного разу виночерпію і хлібодару царя Єгипетського, замкненим у в’язниці, бачилися сни, кожному свій сон, обом в одну ніч, кожному сон особливого значення.","І прийшов до них Йосиф вранці, побачив їх, і ось, вони засмучені.","І запитав він царедворців фараонових, що перебували з ним у домі господаря його під вартою, говорячи: чому у вас сьогодні сумні обличчя?","Вони сказали йому: ми бачили сни; а витлумачити їх нема кому. Йосиф сказав їм: чи не від Бога тлумачення? розкажіть мені.","І розповів головний виночерпій Йосифу сон свій і сказав йому: мені снилося, ось виноградна лоза переді мною;","на лозі три гілки; вона розвинулася, показався на ній цвіт, виросли й дозріли на ній ягоди;","і чаша фараонова у руці моїй; я взяв ягід, вичавив їх у чашу фараонову і подав чашу в руку фараонові.","І сказав йому Йосиф: ось тлумачення його: три гілки — це три дні;","через три дні фараон піднесе голову твою і поверне тебе на місце твоє, і ти подаси чашу фараонову в руку його, за колишнім звичаєм, коли ти був у нього виночерпієм;","згадай же мене, коли добре тобі буде, і зроби мені благодіяння, і скажи про мене фараонові, й виведи мене з цього дому,","бо я украдений із землі євреїв; а також і тут нічого не зробив, за що б кинути мене у в’язницю.","Головний хлібодар побачив, що витлумачив він добре, і сказав Йосифові: мені також снилося: ось на голові в мене три кошики решітчастих;","у верхньому кошику всяка їжа фараонова, вироби пекаря, і птахи [небесні] клювали її з кошика на голові моїй.","І відповів Йосиф і сказав [йому]: ось тлумачення його: три кошики — це три дні;","через три дні фараон зніме з тебе голову твою і повісить тебе на дереві, і птахи [небесні] будуть клювати плоть твою з тебе.","На третій день, день народження фараонового, зробив він вечерю для всіх слуг своїх і згадав він про головного виночерпія і головного хлібодара серед слуг своїх;","і повернув головного виночерпія на попереднє місце, і він подав чашу в руку фараонову,","а головного хлібодара повісив [на дереві], як витлумачив їм Йосиф.","І не згадав головний виночерпій про Йосифа, але забув його."],"x":{"3":"0.39.20","5":"37.2.1:29|50.27.19","6":"0.41.8","8":"0.41.16|37.2.27-28","12":"0.41.25","14":"17.5.19|17.13.31|52.23.42","15":"0.37.28","19":"0.41.13","20":"51.6.21","22":"0.40.19","23":"40.6.6"}},{"v":["Коли минуло два роки, фараону снилося: ось, він стоїть біля ріки;","і ось, вийшли з ріки сім корів, гарних на вигляд і повних тілом, і паслися в очереті;","але ось, після них вийшли з ріки сім корів інших, худих на вигляд і охлялих тілом, і стали поряд з тими коровами, на березі ріки;","і з’їли корови худі на вигляд і охлялі тілом сім корів гарних на вигляд і повних. І прокинувся фараон,","і заснув знову, і снилося йому іншого разу: ось, на одному стеблі піднялося сім колосків гладеньких і гарних;","але ось, після них виросло сім колосків виснажених і висушених східним вітром;","і пожерли худі колоски сім колосків гладеньких і повних. І прокинувся фараон і зрозумів, що це сон.","Уранці засмутився дух його, і послав він, і покликав усіх волхвів Єгипту і всіх мудреців його, і розповів їм фараон сон свій; але не було нікого, хто витлумачив би його фараону.","І став говорити головний виночерпій фараонові і сказав: гріхи мої згадую я нині;","фараон прогнівався на рабів своїх і віддав мене і головного хлібодара під варту в дім начальника охоронців;","і снився нам сон в одну ніч, мені і йому, кожному снився сон особливого значення;","там саме був з нами молодий єврей, раб начальника охоронців; ми розповіли йому сни наші, і він витлумачив нам кожному відповідно до його сновидіння;","і як він витлумачив нам, так і збулося: я повернений на місце моє, а той повішений.","І послав фараон і покликав Йосифа. І поспішно вивели його з в’язниці. Він постригся і перемінив одяг свій і прийшов до фараона.","Фараон сказав Йосифові: мені снився сон, і нема нікого, хто витлумачив би його, а про тебе я чув, що ти вмієш тлумачити сни.","І відповів Йосиф фараону, говорячи: це не моє; Бог дасть відповідь на благо фараонові.","І сказав фараон Йосифові: мені снилося: ось, стою я на березі ріки;","і ось, вийшли з ріки сім корів повних тілом і гарних на вигляд і паслися в очереті;","але ось, після них ішли сім корів інших, худих, дуже поганих на вигляд і охлялих тілом: я не бачив по всій землі Єгипетській таких худих, як вони;","бо з’їли охлялі й худі корови попередніх сім корів повних;","і ввійшли повні в утробу їх, але не помітно було, що вони ввійшли в утробу їх: вони були так само худими на вигляд, як і спочатку. І я прокинувся.","Потім снилося мені: ось, на одному стеблі піднялися сім колосків повних і гарних;","але ось, після них виросло сім колосків тонких, виснажених і висушених східним вітром;","і пожерли худі колоски сім колосків гарних. Я розповів це волхвам, але ніхто не пояснив мені.","І сказав Йосиф фараонові: сон фараонів один: що́ Бог зробить, те́ Він звістив фараонові.","Сім корів гарних, це сім років; і сім колосків добрих, це сім років: сон один;","і сім корів охлялих і худих, що вийшли після тих, це сім років, також і сім колосків виснажених і висушених східним вітром, це сім років голоду.","Ось чому сказав я фараонові: що́ Бог зробить, те́ Він показав фараонові.","Ось, настає сім років великого достатку в усій землі Єгипетській;","після них настануть сім років голоду, і забудеться весь той достаток у землі Єгипетській, і виснажить голод землю,","і непримітним буде колишній достаток на землі, через голод, що прийде, тому що він буде дуже тяжким.","А що сон повторився фараону двічі, це значить, що це істинне слово Боже, і що незабаром Бог виконає це.","І нині нехай знайде фараон чоловіка розумного і мудрого і нехай поставить його над землею Єгипетською.","Нехай накаже фараон поставити над землею наглядачів збирати за сім років достатку п’яту частину [усього врожаю] землі Єгипетської;","нехай вони беруть усякий хліб цих гарних років, що настають, і зберуть у містах хліб під відання фараона для їжі, і нехай бережуть;","і буде ця їжа в запас для землі на сім років голоду, які будуть у землі Єгипетській, щоб земля не загинула від голоду.","Це сподобалося фараонові й усім слугам його.","І сказав фараон слугам своїм: чи знайдемо ми таку, як він, людину, у якій був би Дух Божий?","І сказав фараон Йосифу: оскільки Бог відкрив тобі все це, то немає настільки розумного і мудрого, як ти;","ти будеш над домом моїм, і твого слова буде дотримуватися весь народ мій; тільки престолом я буду більшим за тебе.","І сказав фараон Йосифові: ось, я поставляю тебе над усією землею Єгипетською.","І зняв фараон перстень свій з руки своєї і надів його на руку Йосифа; вдяг його у висонний одяг, поклав золотий ланцюг на шию його;","повелів везти його на другій із своїх колісниць і проголошувати перед ним: схиляйтеся! І поставив його над усією землею Єгипетською.","І сказав фараон Йосифу: я фараон; без тебе ніхто не ворухне ні рукою своєю, ні ногою своєю по всій землі Єгипетській.","І нарік фараон Йосифові ім’я: Цафнаф-панеах, і дав йому за дружину Асенефу, дочку Потифера, жерця Іліопольського. І пішов Йосиф по землі Єгипетській.","Йосифові було тридцять років від народження, коли він став перед лице фараона, царя Єгипетського. І вийшов Йосиф від лиця фараонового і пройшов по всій землі Єгипетській.","Земля ж у сім років достатку принесла з одного зерна по жмені.","І зібрав він усякий хліб семи років, які були [родючі] в землі Єгипетській, і поклав хліб у містах; у кожному місті поклав хліб полів, що оточують його.","І зібрав Йосиф хліба дуже багато, як піску морського, так що перестав і рахувати, тому що не стало рахунку.","До настання років голоду, у Йосифа народилися два сини, яких народила йому Асенефа, дочка Потифера, жерця Іліопольського.","І нарік Йосиф ім’я первісткові: Манассія, тому що [говорив він] Бог дав мені забути усі нещастя мої і весь дім батька мого.","А другому нарік ім’я: Єфрем, тому що [говорив він] Бог зробив мене плідним у землі страждання мого.","І минули сім років достатку, що був у землі Єгипетській,","і настали сім років голоду, як сказав Йосиф. І був голод по всіх землях, а в усій землі Єгипетській був хліб.","Але коли і вся земля Єгипетська почала терпіти голод, то народ почав волати до фараона про хліб. І сказав фараон усім єгиптянам: підіть до Йосифа і робіть, що він вам скаже.","І був голод по всій землі; і відчинив Йосиф усі житниці, і став продавати хліб єгиптянам. Голод же посилювався в землі Єгипетській.","І з усіх країн приходили в Єгипет купувати хліб у Йосифа, тому що голод посилився по всій землі."],"x":{"1":"37.2.1","6":"36.17.10","8":"0.40.7|37.2.3|1.7.11","10":"0.40.3","11":"0.40.8","13":"0.40.19","14":"25.104.20","16":"37.2.30|50.10.20|63.15.10","21":"0.41.4","26":"0.40.12","30":"11.8.1","40":"25.104.21|21.2.53|54.7.10","41":"29.10.14","42":"20.3.10|36.16.11|37.5.29","46":"0.37.2","50":"0.46.20|0.48.5:20","54":"25.104.16","55":"53.2.5","56":"0.42.6","57":"0.12.10"}},{"v":["І довідався Яків, що в Єгипті є хліб, і сказав Яків синам своїм: що ви дивитеся?","І сказав: ось, я чув, що є хліб у Єгипті; підіть туди і купіть нам звідти хліба, щоб нам жити і не вмерти.","Десять братів Йосифових пішли купити хліба в Єгипті,","а Веніаміна, брата Йосифового, не послав Яків з братами його, тому що сказав: не трапилося б з ним лиха.","І прийшли сини Ізраїлеві купувати хліб, разом з іншими, що прийшли, бо в землі Ханаанській був голод.","Йосиф же був начальником у землі тій; він і продавав хліб усьому народові землі. Брати Йосифа прийшли і поклонилися йому лицем до землі.","І побачив Йосиф братів своїх і впізнав їх; але показав, що начебто не знає їх, і говорив з ними суворо і сказав їм: звідки ви прийшли? Вони сказали: із землі Ханаанської, купити їжу.","Йосиф упізнав братів своїх, але вони не впізнали його.","І згадав Йосиф сни, що снилися йому про них; і сказав їм: ви підглядачі, ви прийшли вигледіти наготу* землі цієї.","Вони сказали йому: ні, господарю наш; раби твої прийшли купити їжі;","ми всі діти однієї людини; ми люди чесні; раби твої не бували підглядачами.","Він сказав їм: ні, ви прийшли вигледіти наготу землі цієї.","Вони сказали: нас, рабів твоїх, дванадцять братів; ми сини одного чоловіка в землі Ханаанській, і ось, менший тепер з батьком нашим, а одного не стало.","І сказав їм Йосиф: це саме я і говорив вам, сказавши: ви підглядачі;","ось як ви будете випробувані: клянуся життям фараона, ви не вийдете звідси, якщо не прийде сюди менший брат ваш;","пошліть одного з вас, і нехай він приведе брата вашого, а ви будете затримані; і відкриється, чи правда у вас; і якщо ні, то клянусь життям фараона, що ви підглядачі.","І віддав їх під варту на три дні.","І сказав їм Йосиф на третій день: ось що зробіть, і залишитеся живими, тому що я боюся Бога:","якщо ви люди чесні, то один брат із вас нехай утримується в домі, де ви ув’язнені; а ви підіть, відвезіть хліб, заради голоду сімей ваших;","брата ж вашого меншого приведіть до мене, щоб виправдалися слова ваші і щоб не померти вам. Так вони і зробили.","І говорили вони один одному: дійсно ми караємося за гріх проти брата нашого; ми бачили страждання душі його, коли він благав нас, але не послухали [його]; за те і спостигло нас горе це.","Рувим відповів їм і сказав: чи не говорив я вам: не грішіть проти отрока? але ви не послухалися; ось, кров його стягується.","А того не знали вони, що Йосиф розуміє; бо між ними був перекладач.","І відійшов від них [Йосиф] і заплакав. І повернувся до них, і говорив з ними, і, взявши з них Симеона, зв’язав його перед очима їхніми.","І наказав Йосиф наповнити мішки їхні хлібом, а срібло їх повернути кожному в мішок його, і дати їм запасів на дорогу. Так і зроблено з ними.","Вони поклали хліб свій на ослів своїх, і пішли звідти.","І відкрив один із них мішок свій, щоб дати корму ослові своєму на ночівлі, і побачив срібло своє в отворі мішка його,","і сказав своїм братам: срібло моє повернуто; ось воно в мішку моєму. І засмутилося серце їх, і вони з тремтінням говорили один одному: що це Бог зробив з нами?","І прийшли до Якова, батька свого, у землю Ханаанську і розповіли йому все, що трапилося з ними, говорячи:","начальник над тією землею говорив з нами суворо і прийняв нас за підглядачів землі тієї.","І сказали ми йому: ми люди чесні; ми не бували підглядачами;","нас дванадцять братів, синів у батька нашого; одного не стало, а менший тепер з батьком нашим у землі Ханаанській.","І сказав нам начальник над тією землею: ось як дізнаюсь я, чи чесні ви люди: залиште у мене одного брата з вас, а ви візьміть хліб заради голоду сімей ваших і підіть,","і приведіть до мене молодшого брата вашого; і буду знати я, що ви не підглядачі, але люди чесні; віддам вам брата вашого, і ви можете промишляти у цій землі.","Коли ж вони спорожняли мішки свої, ось, у кожного вузлик срібла його в мішку його. І побачили вони вузлики срібла свого, вони і батько їхній, і злякалися.","І сказав їм Яків, батько їхній: ви позбавили мене дітей: Йосифа нема, і Симеона нема, і Веніаміна взяти хочете, — усе це на мене!","І сказав Рувим батькові своєму, говорячи: убий двох моїх синів, якщо я не приведу його до тебе; віддай його на мої руки; я поверну його тобі.","Він сказав: не піде син мій з вами; тому що брат його помер, і він один залишився; якщо трапиться з ним нещастя на шляху, в який ви підете, то зведете ви сивину мою з печаллю в могилу."],"x":{"1":"54.7.12","4":"0.43.5","6":"0.37.7:9|0.41.40:56","7":"0.43.7|0.44.19","9":"0.37.5:9","13":"0.37.33|0.44.20","15":"0.43.5|0.44.23","20":"0.43.8","21":"0.37.25","22":"0.37.21-22","35":"0.43.18:21|0.44.1","36":"0.37.33","37":"0.46.9","38":"0.37.35|0.44.29-31"},"n":{"9":["Слабкі місця."]}},{"v":["Голод посилився на землі.","І коли вони з’їли хліб, який привезли з Єгипту, тоді батько їхній сказав їм: підіть знову, купіть нам трохи їжі.","І сказав йому Іуда, говорячи: той чоловік рішуче заявив нам, сказавши: не з’являйтеся до мого лиця, якщо брата вашого не буде з вами.","Якщо пошлеш з нами брата нашого, то підемо і купимо тобі їжі,","а якщо не пошлеш, то не підемо, тому що той чоловік сказав нам: не з’являйтеся до мого лиця, якщо брата вашого не буде з вами.","Ізраїль сказав: для чого ви зробили мені таке зло, сказавши тому чоловікові, що у вас є ще брат?","Вони сказали: розпитував той чоловік про нас і про рід наш, говорячи: чи живий ще батько ваш? чи є у вас брат? Ми і розповіли йому за цими розпитами. Чи могли ми знати, що він скаже: приведіть брата вашого?","Іуда ж сказав Ізраїлю, батькові своєму: відпусти отрока зі мною, і ми встанемо і підемо, і живі будемо і не помрем і ми, і ти, і діти наші;","я відповідаю за нього, з моїх рук вимагатимеш його; якщо я не приведу його до тебе і не поставлю його перед лицем твоїм, то залишусь я винним перед тобою в усі дні життя;","якби ми не барилися, то вже сходили б двічі.","Ізраїль, батько їх, сказав їм: якщо так, то ось що зробіть: візьміть із собою плодів землі цієї і віднесіть у дарунок тому чоловікові трохи бальзаму і трохи меду, стиракси і ладану, фісташок і мигдалевих горіхів;","візьміть і інше срібло в руки ваші; а срібло, назад покладене в отвори мішків ваших, поверніть руками вашими: можливо, це недогляд;","і брата вашого візьміть і, вставши, підіть знову до чоловіка того;","Бог же Всемогутній нехай дасть вам знайти милість у чоловіка того, щоб він відпустив вам і іншого брата вашого і Веніаміна, а мені якщо вже бути бездітним, то нехай буду бездітним.","І взяли ті люди дарунки ці, і срібла вдвічі взяли в руки свої, і Веніаміна, і встали, пішли в Єгипет і постали перед лицем Йосифа.","Йосиф, побачивши між ними Веніаміна [брата свого, сина матері своєї], сказав начальнику дому свого: введи цих людей у дім і заколи що-небудь з худоби, і приготуй, тому що зі мною будуть їсти ці люди опівдні.","І зробив чоловік той, як сказав Йосиф, і ввів чоловік той людей цих у дім Йосифів.","І злякалися люди ці, що ввели їх у дім Йосифів, і сказали: це за срібло, повернуте раніше у мішки наші, ввели нас, щоб причепитися до нас і напасти на нас, і взяти нас у рабство, і ослів наших.","І підійшли вони до начальника дому Йосифового, і стали говорити йому біля дверей дому,","і сказали: послухай, господарю наш, ми приходили вже раніше купувати їжу,","і трапилося, що, коли прийшли ми на ночівлю і відкрили мішки наші, — ось срібло кожного в отворі мішка його, срібло наше за вагою його, і ми повертаємо його своїми руками;","а для купівлі їжі ми принесли інше срібло в руках наших, ми не знаємо, хто поклав срібло наше в мішки наші.","Він сказав: будьте спокійні, не бійтеся; Бог ваш і Бог батька вашого дав вам скарб у мішках ваших; срібло ваше дійшло до мене. І привів до них Симеона.","І ввів той чоловік людей цих у дім Йосифів і дав води, і вони обмили ноги свої; і дав корму ослам їхнім.","І вони приготували дарунки до приходу Йосифа опівдні, тому що чули, що там будуть їсти хліб.","І прийшов Йосиф додому; і вони принесли йому в дім дарунки, які були в руках їхніх, і поклонилися йому до землі.","Він запитав їх про здоров’я і сказав: чи здоровий батько ваш старий, про якого ви говорили? чи живий ще він?","Вони сказали: здоровий раб твій, батько наш; ще живий. [Він сказав: благословенна людина ця від Бога.] І схилилися вони і поклонилися.","І підняв очі свої [Йосиф], і побачив Веніаміна, брата свого, сина матері своєї, і сказав: це брат ваш менший, про якого ви говорили мені? І сказав: нехай буде милість Божа з тобою, сину мій!","І поспіхом вийшов Йосиф, тому що закипіла любов до брата його, і він готовий був заплакати, і вийшов він у внутрішню кімнату і плакав там.","І, умивши лице своє, ввійшов, і укріпився і сказав: подавайте страву.","І подали йому окремо, і їм окремо, і єгиптянам, які обідали з ним, окремо, бо єгиптяни не можуть їсти з євреями, тому що це мерзота для єгиптян.","І сіли вони перед ним, первородний за первородством його, і молодший за молодістю його, і дивувалися ці люди один перед одним.","І посилалися їм страви від нього, і частка Веніаміна була вп’ятеро більшою за частки кожного з них. І пили, і доволі пили вони з ним."],"x":{"2":"0.44.25","3":"0.42.20","5":"0.42.4:15","7":"0.42.7|0.44.19","9":"0.44.32","14":"0.42.24|7.1.8|9.2.6","21":"0.42.27","23":"0.42.25","24":"0.18.4|0.19.2|52.7.44","26":"0.37.7:9","29":"0.42.13","30":"0.45.2","32":"1.8.26|18.1.11|37.1.8","34":"25.103.15|28.5.1|47.1.6"}},{"v":["І наказав [Йосиф] начальнику дому свого, говорячи: наповни мішки цих людей харчами, скільки вони зможуть нести, і срібло кожного поклади в отвір мішка його,","а чашу мою, чашу срібну, поклади в отвір мішка до молодшого разом зі сріблом за куплений ним хліб. І зробив той за словом Йосифа, яке сказав він.","Уранці, коли розвиднилося, ці люди були відпущені, вони й осли їхні.","Ще не далеко відійшли вони від міста, як Йосиф сказав начальникові дому свого: іди, наздоганяй цих людей і, коли наздоженеш, скажи їм: чому ви заплатили злом за добро? [для чого украли в мене срібну чашу?]","Чи не та це, з якої п’є господар мій і він ворожить на ній? Це лихе ви зробили.","Він наздогнав їх і сказав їм ці слова.","Вони сказали йому: для чого господар наш говорить такі слова? Ні, раби твої не зроблять такої справи.","Ось, срібло, знайдене нами в отворах мішків наших, ми назад принесли тобі із землі Ханаанської: як же нам украсти з дому господаря твого срібло або золото?","У кого з рабів твоїх знайдеться [чаша], тому смерть, і ми будемо рабами господаря нашого.","Він сказав: добре; як ви сказали, так нехай і буде: у кого знайдеться [чаша], той буде мені рабом, а ви будете не винні.","Вони поспіхом опустили кожен свій мішок на землю і відкрили кожен свій мішок.","Він обшукав, починаючи зі старшого і закінчуючи молодшим; і знайшлася чаша в мішку Веніаміновому.","І роздерли вони одяг свій, і, поклавши кожен на осла свого ношу, повернулися до міста.","І прийшли Іуда і брати його в дім Йосифа, який був ще вдома, й упали перед ним на землю.","Йосиф сказав їм: що це ви зробили? хіба ви не знали, що така людина, як я, звичайно, вгадає?","Іуда сказав: що нам сказати господарю нашому? що говорити? чим виправдовуватися? Бог знайшов неправду рабів твоїх; ось, ми раби господарю нашому, і ми, і той, у чиїх руках знайшлася чаша.","Але [Йосиф] сказав: ні, я цього не зроблю; той, у чиїх руках знайшлася чаша, буде мені рабом, а ви йдіть з миром до батька вашого.","І підійшов Іуда до нього і сказав: господарю мій, дозволь рабові твоєму сказати слово у вуха господаря мого, і не прогнівайся на раба твого, бо ти те саме, що фараон.","Господар мій запитував рабів своїх, говорячи: чи є у вас батько або брат?","Ми сказали господарю нашому, що у нас є батько старий, і [у нього] молодший син, син старости, брат якого помер, а він залишився один від матері своєї, і батько любить його.","Ти ж сказав рабам твоїм: приведіть його до мене, щоб мені поглянути на нього.","Ми сказали господарю нашому: отрок не може залишити батька свого, і якщо він залишить батька свого, то цей помре.","Але ти сказав рабам твоїм: якщо не прийде з вами менший брат ваш, то ви більше не з’являйтеся перед моїм лицем.","Коли ми прийшли до раба твого, батька нашого, то переказали йому слова господаря мого.","І сказав батько наш: підіть знову, купіть нам трохи їжі.","Ми сказали: не можна нам іти; а якщо буде з нами менший брат наш, то підемо; тому що не можна нам бачити лиця тієї людини, якщо не буде з нами найменшого брата нашого.","І сказав нам раб твій, батько наш: ви знаєте, що дружина моя народила мені двох синів;","один пішов від мене, і я сказав: очевидно, він розтерзаний; і я не бачив його донині;","якщо і цього візьмете від очей моїх, і трапиться з ним нещастя, то зведете ви сивину мою з печаллю у могилу.","Тепер якщо я прийду до раба твого, батька нашого, і не буде з нами отрока, з душею якого пов’язана душа його,","то він, побачивши, що немає отрока, помре; і зведуть раби твої сивину раба твого, батька нашого, із печаллю в могилу.","При цьому я, раб твій, взявся відповідати за отрока батькові моєму, сказавши: якщо не приведу його до тебе [і не поставлю його перед тобою], то залишусь я винним перед батьком моїм на всі дні життя.","Отже, нехай я, раб твій, замість отрока залишуся рабом у господаря мого, а отрок нехай іде з братами своїми:","бо як піду я до батька мого, коли отрока не буде зі мною? я побачив би біду, що осягла б батька мого."],"x":{"4":"25.37.21","9":"0.31.32","13":"0.37.29","19":"0.43.7","20":"0.42.13","23":"0.43.5","25":"0.43.2","28":"0.37.33","29":"0.42.38","31":"0.37.35","32":"0.43.9"}},{"v":["Йосиф не міг більш утримуватися при всіх, що стояли біля нього і закричав: виведіть від мене усіх. І не залишалося при Йосифові нікого, коли він відкрився братам своїм.","І голосно заридав він, і почули єгиптяни, і почув дім фараонів.","І сказав Йосиф братам своїм: я — Йосиф, чи живий ще батько мій? Але брати його не могли відповідати йому, тому що вони зніяковіли перед ним.","І сказав Йосиф братам своїм: підійдіть до мене. Вони підійшли. Він сказав: я — Йосиф, брат ваш, якого ви продали в Єгипет;","але тепер не засмучуйтеся і не шкодуйте про те, що ви продали мене сюди, тому що Бог послав мене перед вами для збереження вашого життя;","тому що тепер два роки голоду на землі: [залишається] ще п’ять років, в які ні орати, ні жати не будуть;","Бог послав мене перед вами, щоб залишити вас на землі і зберегти ваше життя великим визволенням.","Отже, не ви послали мене сюди, але Бог, Який і поставив мене батьком фараонові і господарем в усьому домі його і владикою по всій землі Єгипетській.","Йдіть швидше до батька мого і скажіть йому: так говорить син твій Йосиф: Бог поставив мене господарем над усім Єгиптом; прийди до мене, не барися;","ти будеш жити в землі Гесем; і будеш біля мене, ти, і сини твої, і сини синів твоїх, і дрібна і велика худоба твоя, й усе твоє;","і прогодую тебе там, бо голод буде ще п’ять років, щоб не зубожів ти і дім твій і все твоє.","І ось, очі ваші й очі брата мого Веніаміна бачать, що це мої уста говорять з вами;","скажіть же батькові моєму про всю славу мою в Єгипті і про все, що ви бачили, і приведіть швидше батька мого сюди.","Й упав він на шию Веніаміну, брату своєму, і плакав; і Веніамін плакав на шиї його.","І цілував усіх братів своїх і плакав, обіймаючи їх. Потім говорили з ним брати його.","Дійшла до дому фараона чутка, що прийшли брати Йосифа; і приємно було фараонові і рабам його.","І сказав фараон Йосифові: скажи братам твоїм: ось що зробіть: нав’ючте худобу вашу [хлібом] і йдіть у землю Ханаанську;","і візьміть батька вашого і сім’ї ваші і прийдіть до мене; я дам вам краще [місце] в землі Єгипетській, і ви будете їсти плоди землі.","Тобі ж повеліваю сказати їм: зробіть це: візьміть собі з землі Єгипетської колісниці для дітей ваших і для дружин ваших, і привезіть батька вашого і прийдіть;","і не шкодуйте речей ваших, бо найкраще з усієї землі Єгипетської дам вам.","Так і зробили сини Ізраїлеві. І дав їм Йосиф колісниці за наказом фараона, і дав їм запас на дорогу,","кожному з них він дав переміну одягу, а Веніаміну дав триста срібників і п’ять перемін одягу;","також і батькові своєму послав десять ослів, нав’ючених кращими здобутками єгипетськими, і десять ослиць, нав’ючених зерном, хлібом і припасами батькові своєму на дорогу.","І відпустив братів своїх, і вони пішли. І сказав їм: не сваріться на дорозі.","І пішли вони з Єгипту, і прийшли в землю Ханаанську до Якова, батька свого,","і сповістили його, сказавши: Йосиф [син твій] живий і тепер володарює над усією землею Єгипетською. Але серце його збентежилося, тому що він не вірив їм.","Коли ж вони переказали йому всі слова Йосифа, які він говорив їм, і коли побачив колісниці, що прислав Йосиф, щоб везти його, тоді ожив дух Якова, батька їх,","і сказав Ізраїль: досить [цього для мене], ще живий син мій Йосиф; піду й побачу його, поки не помру."],"x":{"1":"54.7.13|0.42.7","4":"54.7.13","5":"0.50.20","8":"29.10.14|0.50.20","9":"54.7.14","10":"0.46.28","14":"0.33.4|0.46.29","15":"1.4.27","18":"0.47.6:11|25.144.14|25.147.3","21":"54.7.14","28":"0.46.30"}},{"v":["І вирушив Ізраїль з усім, що в нього було, і прийшов у Вирсавію, і приніс жертви Богу батька свого Ісаака.","І сказав Бог Ізраїлю у видінні нічному: Якове! Якове! Він сказав: ось я.","Бог сказав: Я Бог, Бог батька твого; не бійся йти в Єгипет, тому що там породжу від тебе народ великий;","Я піду з тобою в Єгипет, Я і виведу тебе назад. Йосиф своєю рукою закриє очі твої.","Яків вирушив з Вирсавії; і повезли сини Ізраїлеві Якова, батька свого, і дітей своїх, і дружин своїх на колісницях, які послав фараон, щоб привезти його.","І взяли вони худобу свою і майно своє, що придбали в землі Ханаанській, і прийшли в Єгипет, — Яків і весь рід його з ним.","Синів своїх і онуків своїх із собою, дочок своїх і онучок своїх і весь рід свій привів він із собою в Єгипет.","Ось імена синів Ізраїлевих, що прийшли в Єгипет: Яків і сини його. Первісток Якова Рувим.","Сини Рувима: Ханох і Фаллу, Хецрон і Хармі.","Сини Симеона: Іємуїл та Іамин, і Огад, і Іахин, і Цохар, і Саул, син хананеянки.","Сини Левія: Гирсон, Кааф і Мерарі.","Сини Іуди: Ір і Онан, і Шела, і Фарес, і Зара; але Ір і Онан померли в землі Ханаанській. Сини Фареса були: Есром і Хамул.","Сини Іссахара: Фола і Фува, Іов і Шимрон.","Сини Завулона: Серед і Елон, і Іахлеїл.","Це сини Лії, яких вона народила Якову в Месопотамії, і Діну, дочку його. Всіх душ синів його і дочок його — тридцять три.","Сини Гада: Цифіон і Хаггі, Шуні й Ецбон, Ері й Ароді й Арелі.","Сини Асира: Імна та Ішва, й Ішви, і Бриа, і Серах, сестра їхня. Сини Бриї: Хевер і Малхиїл.","Це сини Зелфи, яку Лаван дав Лії, дочці своїй; вона народила їх Якову шістнадцять душ.","Сини Рахилі, дружини Якова: Йосиф і Веніамін.","І народилися у Йосифа в землі Єгипетській Манассія та Єфрем, яких народила ему Асенефа, дочка Потифера, жреця Іліопольського.","Сини Веніаміна: Бела і Бехер і Ашбел; [сини Бели були:] Гера і Нааман, Ехі і Рош, Муппим і Хуппим і Ард.","Це сини Рахилі, що народилися в Якова, усього чотирнадцять душ.","Син Дана: Хушим.","Сини Неффалима: Іахцеїл і Гуні, й Ієцер, і Шиллем.","Це сини Валли, яку дав Лаван дочці своїй Рахилі; вона народила їх Якову всього сім душ.","Усіх душ, що прийшли з Яковом в Єгипет, що пішли зі стегон його, крім дружин синів Яковових, усього шістдесят шість душ.","Синів Йосифа, які народилися у нього в Єгипті, дві душі. Всіх душ дому Яковового, що прийшли [з Яковом] у Єгипет, сімдесят [п’ять].","Іуду послав він перед собою до Йосифа, щоб він показав шлях у Гесем. І прийшли в землю Гесем.","Йосиф запряг колісницю свою і виїхав назустріч Ізраїлю, батькові своєму, в Гесем, і, побачивши його, упав на шию його, і довго плакав на шиї його.","І сказав Ізраїль Йосифові: помру я тепер, побачивши лице твоє, бо ти ще живий.","І сказав Йосиф братам своїм і дому батька свого: я піду, сповіщу фараона і скажу йому: брати мої і дім батька мого, які були в землі Ханаанській, прийшли до мене;","ці люди пастухи овець, бо скотарі вони; і дрібна і велика худоба своя, й усе, що у них, привели вони.","Якщо фараон покличе вас і скаже: яке заняття ваше?","то ви скажіть: ми, раби твої, скотарями були від юности нашої донині, і ми і батьки наші, щоб вас оселили в землі Гесем. Тому що мерзота є для єгиптян усякий пастух овець."],"x":{"1":"1.1.1|3.20.15|4.10.22","4":"0.50.1","5":"54.7.15","6":"5.24.4|25.104.23|31.52.4","8":"1.1.1-2|1.6.14|3.26.5|12.5.1:3","10":"12.4.24","11":"12.6.1|1.6.16|3.3.17","12":"0.38.2-3|12.2.3","13":"12.7.1","14":"3.26.26","16":"3.26.15","17":"12.7.30","20":"0.41.50-52","21":"12.7.6","23":"3.26.42","24":"3.26.48|12.7.13","27":"1.1.5|4.10.22|54.7.14","29":"0.33.4|0.45.14","30":"0.45.28|52.2.29-30","31":"0.47.1","34":"0.47.6:27|0.43.32"}},{"v":["І прийшов Йосиф і сповістив фараона і сказав: батько мій і брати мої, із дрібною і великою худобою своєю і з усім, що у них, прийшли з землі Ханаанської; і ось, вони в землі Гесем.","І з братів своїх він узяв п’ять чоловік і представив їх фараону.","І сказав фараон братам його: яке ваше заняття? Вони сказали фараонові: пастухи овець раби твої, і ми і батьки наші.","І сказали вони фараонові: ми прийшли пожити в цій землі, тому що немає пасовищ для худоби рабів твоїх, бо в землі Ханаанській сильний голод; отже, дозволь оселитися рабам твоїм у землі Гесем.","І сказав фараон Йосифові: батько твій і брати твої прийшли до тебе;","земля Єгипетська перед тобою; на кращому місці землі осели батька твого і братів твоїх; нехай живуть вони в землі Гесем; і якщо знаєш, що між ними є здібні люди, постав їх доглядачами над моєю худобою.","І привів Йосиф Якова, батька свого, і представив його фараону; і благословив Яків фараона.","Фараон сказав Якову: скільки років життя твого?","Яків сказав фараону: днів подорожування мого сто тридцять років; малі і нещасні дні життя мого і не досягли років життя батьків моїх у днях подорожування їх.","І благословив фараона Яків і вийшов від фараона.","І оселив Йосиф батька свого і братів своїх, і дав їм володіння в землі Єгипетській, у кращій частині землі, у землі Раамсес, як повелів фараон.","І забезпечував Йосиф батька свого і братів своїх і весь дім батька свого хлібом, за потребою кожної родини.","І не було хліба по всій землі, тому що голод дуже посилився, і були виснажені від голоду земля Єгипетська і земля Ханаанська.","Йосиф зібрав усе срібло, яке було в землі Єгипетській і в землі Ханаанській, за хліб, який купували, і вніс Йосиф срібло в дім фараонів.","І срібло вичерпалося в землі Єгипетській і у землі Ханаанській. Усі єгиптяни прийшли до Йосифа і говорили: дай нам хліба; навіщо нам помирати перед тобою, тому що срібло закінчилося у нас?","Йосиф сказав: приганяйте худобу вашу, і я буду давати вам [хліб] за худобу вашу, якщо срібло закінчилося у вас.","І приганяли вони до Йосифа худобу свою; і давав їм Йосиф хліб за коней, і за отари дрібної худоби, і за стада великої худоби, і за ослів; і постачав їм хліб у той рік за всю худобу їхню.","І минув цей рік; і прийшли до нього на другий рік і сказали йому: не приховаємо від господаря нашого, що срібло вичерпалося і стада худоби нашої у господаря нашого; нічого не залишилося у нас перед господарем нашим, крім тіл наших і земель наших;","для чого нам гинути на очах твоїх, і нам і землям нашим? купи нас і землі наші за хліб, і ми з землями нашими будемо рабами фараону, а ти дай нам насіння, щоб нам бути живими і не вмерти, і щоб не спустошилася земля.","І купив Йосиф усю землю Єгипетську для фараона, тому що продали єгиптяни кожен своє поле, бо голод долав їх. І дісталася земля фараону.","І зробив він народ рабами від одного кінця Єгипту до іншого.","Тільки землі жерців не купив [Йосиф], тому що жерцям від фараона виділена була ділянка, і вони годувалися зі своєї ділянки, яку дав їм фараон; тому і не продали землі своєї.","І сказав Йосиф народу: ось, я купив тепер для фараона вас і землю вашу; ось вам насіння, і засівайте землю;","коли будуть жнива, віддавайте п’яту частину фараону, а чотири частини залишаться вам на засівання поля, на прогодування вам і тим, хто в домах ваших, і на їжу дітям вашим.","Вони сказали: ти врятував нам життя; нехай знайдемо милість в очах господаря нашого і нехай будемо рабами фараона.","І поставив Йосиф за закон землі Єгипетській, навіть до цього дня: п’яту частину давати фараонові, за винятком тільки землі жерців, яка не належала фараонові.","І жив Ізраїль у землі Єгипетській, у землі Гесем, і володіли вони нею, і плодилися, і дуже розмножились.","І жив Яків у землі Єгипетській сімнадцять років; і було днів Якова, років життя його, сто сорок сім років.","І прийшов час Ізраїлю померти, і покликав він сина свого Йосифа і сказав йому: якщо я знайшов благовоління в очах твоїх, поклади руку твою під стегно моє і клянись, що ти зробиш мені милість і правду, не поховаєш мене в Єгипті,","щоб мені лягти з батьками моїми; винесеш мене з Єгипту і поховаєш мене в їхній гробниці. Йосиф сказав: зроблю за словом твоїм.","І сказав: клянися мені. І клявся йому. І поклонився Ізраїль до узголів’я постелі*."],"x":{"1":"0.46.31|54.7.14-15","3":"0.46.33-34","6":"0.34.10","9":"25.118.19|75.11.13|75.13.14","11":"1.1.11","12":"30.49.17","27":"1.5.5|25.104.24","29":"0.24.2|0.50.5","30":"0.23.19|0.50.13","31":"0.50.5|75.11.21"},"n":{"31":["За перекладом 70-ти: на верх жезла його."]}},{"v":["Після того Йосифові сказали: ось, батько твій хворий. І він узяв з собою двох синів своїх, Манассію і Єфрема [і пішов до Якова].","Якова сповістили і сказали: ось, син твій Йосиф іде до тебе. Ізраїль зібрав сили свої і сів на постелі.","І сказав Яків Йосифові: Бог Всемогутній явився мені в Лузі, в землі Ханаанській, і благословив мене,","і сказав мені: ось, Я розплоджу тебе, і розмножу тебе, і породжу від тебе безліч народів, і дам землю цю нащадкам твоїм після тебе, у вічне володіння.","І нині два сини твої, які народилися тобі в землі Єгипетській, до мого прибуття до тебе в Єгипет, мої вони; Єфрем і Манассія, як Рувим і Симеон, будуть мої;","діти ж твої, які народяться від тебе після них, будуть твої; вони під ім’ям братів своїх будуть іменуватися в їхньому наслідді.","Коли я йшов з Месопотамії, померла в мене Рахиль [мати твоя] у землі Ханаанській, по дорозі, не дійшовши трохи до Ефрафи, і я поховав її там по дорозі до Ефрафи, що нині Вифлеєм.","І побачив Ізраїль синів Йосифа і сказав: хто це?","І сказав Йосиф батькові своєму: це сини мої, яких Бог дав мені тут. [Яків] сказав: підведи їх до мене, і я благословлю їх.","Очі ж Ізраїлеві притупилися від старости; не міг він бачити ясно. Йосиф підвів їх до нього, і він поцілував їх і обійняв їх.","І сказав Ізраїль Йосифу: не сподівався я бачити твоє лице; але ось, Бог показав мені і дітей твоїх.","І відвів їх Йосиф від колін його і поклонився йому лицем своїм до землі.","І взяв Йосиф обох [синів своїх], Єфрема у праву свою руку навпроти лівої Ізраїля, а Манассію в ліву навпроти правої Ізраїля, і підвів до нього.","Але Ізраїль простяг праву руку свою і поклав на голову Єфрема, хоча цей був менший, а ліву на голову Манассії. З наміром поклав він так руки свої, хоча Манассія був первістком.","І благословив Йосифа і сказав: Бог, перед Яким ходили батьки мої Авраам та Ісаак, Бог, Який пасе мене з тих пір, як я існую, до цього дня,","ангел, що визволяє мене від усякого зла, нехай благословить отроків цих; нехай буде на них наречене ім’я моє й ім’я батьків моїх Авраама та Ісаака, і нехай виростуть вони в безліч посеред землі.","І побачив Йосиф, що батько його поклав праву руку свою на голову Єфрема; і прикро було йому через це. І взяв він руку батька свого, щоб перекласти її з голови Єфрема на голову Манассії,","і сказав Йосиф батькові своєму: не так, батьку мій, бо це — первісток; поклади на його голову праву руку твою.","Але батько його не погодився і сказав: знаю, сину мій, знаю; і від нього народиться народ, і він буде великим; але менший його брат буде більшим за нього, і від сімені його народиться численний народ.","І благословив їх у той день, говорячи: тобою буде благословляти Ізраїль, говорячи: Бог нехай вчинить тобі, як Єфрему і Манассії. І поставив Єфрема вище за Манассію.","І сказав Ізраїль Йосифові: ось, я вмираю; і Бог буде з вами і поверне вас у землю батьків ваших;","я даю тобі, переважно перед братами твоїми, одну ділянку, яку я взяв з рук аморреїв мечем моїм і луком моїм."],"x":{"3":"0.28.13","4":"0.13.16|0.35.11-12|0.41.52","5":"0.41.50-52|0.35.19","9":"0.33.5|0.27.4|0.27.1|8.3.2","14":"50.19.15|75.11.21","16":"0.31.29","19":"4.33.16","20":"7.4.11|4.33.17|32.31.20","22":"5.24.32|53.4.5"}},{"v":["І покликав Яків синів своїх і сказав: зберіться, і я сповіщу вам, що буде з вами у грядущі дні;","зійдіться і послухайте, сини Якова, послухайте Ізраїля, батька вашого.","Рувиме, первістку мій! ти — кріпкість моя і початок сили моєї, верх достоїнства і верх могутности;","але ти бушував, як вода, — не будеш мати переваги, бо ти зійшов на ложе батька твого, ти осквернив постіль мою, [на яку] зійшов.","Симеон і Левій брати, знаряддя жорстокости мечі їхні;","в раду їх нехай не ввійде душа моя, і до зібрання їх нехай не прилучиться слава моя, бо вони у гніві своєму убили мужа і з примхи своєї перерізали жили тельця;","проклятий гнів їх, бо жорстокий, і розлюченість їх, тому що люта; розділю їх в Якові і розсію їх в Ізраїлі.","Іудо! тебе хвалитимуть брати твої. Рука твоя на хребті ворогів твоїх; поклоняться тобі сини батька твого.","Молодий лев Іуда, піднімається зі здобичі, син мій. Схилився він, ліг, як лев і як левиця: хто підніме його?","Не відійде скіпетр від Іуди і законодавець від стегон його, доки не прийде Примиритель, і Йому покірність народів.","Він прив’язує до виноградної лози осля своє і до лози кращого винограду сина ослиці своєї; миє у вині одяг свій і у крові грон убрання своє;","блискучі очі [його] від вина, і білі зуби [його] від молока.","Завулон біля берега морського буде жити і біля пристані корабельної, і межа його до Сидона.","Іссахар осел міцний, що лежить між протоками вод;","і побачив він, що спокій добрий, і що земля приємна: і схилив плечі свої для носіння тягаря і став працювати на виплату данини.","Дан буде судити народ свій, як одне з колін Ізраїля;","Дан буде змієм на дорозі, аспидом на путі, що вражає ногу коня, так що вершник його впаде назад.","На допомогу твою сподіваюся, Господи!","Гад, — натовп буде тіснити його, але він відтіснить його по п’ятах.","Для Асира — занадто ситний хліб його, і він буде постачати царські страви.","Неффалим — теревинф рослий, що розпускає прекрасні гілки*.","Йосиф — віття плодоносного дерева, віття плодоносного дерева над джерелом; гілки його простягаються над стіною;","засмучували його, і стріляли і ворогували проти нього стрільці,","але твердим залишився лук його, і міцні м’язи рук його, від рук могутнього Бога Якового. Звідти Пастир і твердиня Ізраїлева,","від Бога батька твого, Який нехай і допоможе тобі, і від Всемогутнього, Який нехай і благословить тебе благословеннями небесними звище, благословеннями безодні, що лежить долі, благословеннями сосків і утроби,","благословеннями батька твого, які перевищують благословення гір давніх і приємності пагорбів вічних; нехай будуть вони на голові Йосифа і на тімені обраного між братами своїми.","Веніамін, хижий вовк, вранці буде їсти ловитву і ввечері буде ділити здобич.","Ось усі дванадцять колін Ізраїлевих; і ось що сказав їм батько їх; і благословив їх, і дав їм благословення, кожному своє.","І заповідав він їм і сказав їм: я прилучаюся до народу мого; поховайте мене з батьками моїми в печері, яка на полі Ефрона хеттеянина,","у печері, яка на полі Махпела, що перед Мамре, у землі Ханаанській, яку [печеру] купив Авраам з полем у Ефрона хеттеянина у власність для поховання;","там поховали Авраама і Сарру, дружину його; там поховали Ісаака і Ревекку, дружину його; і там поховав я Лію;","це поле і печера, яка на ньому, куплена у синів Хеттеєвих.","І закінчив Яків заповіт синам своїм, і поклав ноги свої на постіль, і помер, і приєднався до народу свого."],"x":{"1":"4.33.1","3":"0.29.32|4.21.17","4":"0.35.22|12.5.1","5":"0.34.25|19.9.2","6":"0.34.26","7":"5.19.1|5.21.3","9":"3.24.9","10":"12.5.2|53.1.45|53.5.46|50.2.6","11":"31.63.1-2","12":"76.1.14","13":"5.19.10","14":"6.5.15","15":"4.33.18","16":"6.13.25","17":"6.18.1","18":"25.118.166|52.2.30","19":"3.32.17","20":"4.33.24","21":"6.4.6","22":"0.48.16","24":"4.33.17","26":"4.33.16","28":"30.44.26","29":"0.25.8|0.47.30","30":"0.23.16-17|0.50.13|54.7.16","31":"0.25.9|0.35.29","33":"54.7.15"},"n":{"21":["За іншим прочитанням: Неффалим — сарна струнка; він говорить прекрасні вислови."]}},{"v":["Йосиф упав на лице батька свого, і плакав над ним, і цілував його.","І повелів Йосиф слугам своїм — лікарям, бальзамувати батька його; і лікарі набальзамували Ізраїля.","І виповнилося йому сорок днів, бо стільки днів потрібно для бальзамування, і оплакували його єгиптяни сімдесят днів.","Коли ж минули дні плачу по ньому, Йосиф сказав придворним фараона, говорячи: якщо я знайшов благовоління в очах ваших, то скажіть фараонові так:","батько мій закляв мене, сказавши: ось, я вмираю; у гробі моєму, який я викопав собі в землі Ханаанській, там поховай мене. І тепер хотів би я піти і поховати батька мого і повернутися. [Слова Йосифа переказали фараонові.]","І сказав фараон: піди і поховай батька твого, як він закляв тебе.","І пішов Йосиф ховати батька свого. І пішли з ним усі слуги фараона, старійшини дому його й усі старійшини землі Єгипетської,","і весь дім Йосифа, і брати його, і дім батька його. Тільки дітей своїх і дрібну й велику худобу свою залишили в землі Гесем.","З ним вирушили також колісниці і вершники, так що зібрання було дуже великим.","І дійшли вони до Горен-гаатада при Йордані і плакали там плачем великим і дуже сильним; і зробив Йосиф плач по батькові своєму сім днів.","І бачили жителі землі тієї, хананеї, плач у Горен-гаатаді, і сказали: великий плач цей у єгиптян! Тому наречено ім’я [місцю] тому: плач єгиптян, що при Йордані.","І зробили сини Яковові з ним, як він заповів їм;","і віднесли його сини його в землю Ханаанську і поховали його в печері на полі Махпела, яку купив Авраам з полем у власність для поховання у Ефрона хеттеянина, перед Мамре.","І повернувся Йосиф у Єгипет, сам і брати його і всі, що ходили з ним ховати батька його, після погребіння ним батька свого.","І побачили брати Йосифові, що помер батько їх, і сказали: що, коли Йосиф зненавидить нас і захоче помститися нам за все зло, яке ми йому зробили?","І послали вони сказати Йосифові: батько твій перед смертю своєю заповів, говорячи:","так скажіть Йосифові: прости братам твоїм провину і гріх їх, оскільки вони зробили тобі зло. І нині прости провини рабів Бога батька твого. Йосиф плакав, коли йому говорили це.","Прийшли і самі брати його, і упали перед лицем його, і сказали: ось, ми раби тобі.","І сказав Йосиф: не бійтеся, тому що я боюся Бога;","ось, ви замишляли проти мене зло; але Бог перетворив це на добро, щоб зробити те, що тепер є: зберегти життя великій кількості людей;","отже, не бійтеся: я буду годувати вас і дітей ваших. І заспокоїв їх і говорив по серцю їх.","І жив Йосиф у Єгипті сам і дім батька його; жив же Йосиф усього сто десять років.","І бачив Йосиф дітей у Єфрема до третього роду, також і сини Махира, сина Манассіїного, народилися на коліна Йосифа.","І сказав Йосиф братам своїм: я вмираю, але Бог відвідає вас і виведе вас із землі цієї у землю, про яку клявся Аврааму, Ісааку і Якову.","І закляв Йосиф синів Ізраїлевих, говорячи: Бог відвідає вас, і ви винесіть кості мої звідси.","І помер Йосиф ста десяти років. І набальзамували його і поклали в ковчег у Єгипті."],"x":{"1":"0.46.4","5":"0.47.29","10":"30.22.11","13":"54.7.16|0.23.17","17":"0.26.24|0.31.42","20":"0.45.5","22":"0.41.46","23":"3.32.39","24":"75.11.22","25":"1.13.19|5.24.32"}}];
